import {createContext, useContext, useState} from "react";
import UserStatus from "./userStatus";

const UserStatusContext = createContext(null)

export const UserStatusProvider = ({children})=>{
    const [userId, setUserId] = useState([]);

    const addUserId = (id) => {
        setUserId(prev => {
            const alreadyExists = prev.some(u => u.id === id);
            if (alreadyExists) return prev;
            return [...prev, { id, status: "inactive" }];
        });
    }


    const getUserStatus = (id)=>{
        if (!id) return "inactive";
        const isUserInTab = userId.find((e)=>e.id ===id)
        if (isUserInTab){
            return isUserInTab.status
        }
        return "inactive"
    }

    return (
        <UserStatusContext.Provider value={{getUserStatus, addUserId}}>
            {children}
            {userId.map((e)=>(
                <UserStatus setStatesStatus={setUserId} id={e.id} key={e.id} />
            ))}
        </UserStatusContext.Provider>
    )
}
export const useUserStatus = ()=> useContext(UserStatusContext);