import React, {useCallback, useContext, useMemo, useState} from "react";
import {Dropdown} from "react-bootstrap";
import RenduDAO from "../../Model/RenduDAO";
import {UserContext} from "../Main/Utilitaire/UserProvider";
import {Form} from 'react-bootstrap'
const Taches = ({date,rendu,id, setAll}) => {
    const { user: userContext }=useContext(UserContext)
    const today = useMemo(()=>{
        return new Date().toLocaleDateString().split('T')[0]
    },[])
    const [formClicked,setFormClicked]=useState(false)
    const [tache,setTache]=useState('')
    const [comment,setComment]=useState('')
    const [statut,setStatut]=useState(-1)
    const [valid,setValid]=useState(false)
    const handleClickForm = useCallback((value) => {
        setTache('')
        setComment('')
        setStatut(-1)
        setFormClicked(value)
        setValid(false)
    },[])
    const [load, setLoad] = useState(false);
    const subbmit = useCallback(() => {
        if (tache.trim().length===0){
            setValid(true)
            return
        }
        setLoad(true)
        RenduDAO.addRendu({idRendu: -210212, employe: userContext?.idEmp, dateDebut: new Date(), tache: tache.trim(), comment: comment.trim(), statut: statut}).then((res)=>{
            rendu.push(res)
            setAll((prev)=>[...prev,res])
        }).catch((error)=>{
            console.log(error.message)
        }).finally(()=>{
            handleClickForm(false)
            setLoad(false)
        })
    },[userContext?.idEmp, tache, comment, statut])

    const titreStatut=useMemo(()=>{
        return [{id: -1 , titre: 'À faire'},{id: 0 , titre: 'En cours'},{id: 1 , titre: 'Terminer'}]
    },[])

    const deleteRendu=(idDelete)=>{
        RenduDAO.deleteS(idDelete).then((res)=>{
            setAll((prev)=>prev.filter(rend=>rend.idRendu !==idDelete))
            rendu = rendu.filter(r => r.idRendu !== idDelete)
        }).catch((e)=>{
            console.log(e.message)
        })
    }

    const modif=useCallback(()=>{

    },[])
    return (
        <>
            <table className="table p-0">
                <tbody>
                {rendu.map(({tache,comment,statut,idRendu},index)=>{
                    const st=titreStatut.find((element)=>element.id===statut)
                    return(
                        <tr key={index}>
                            <th scope="row" style={{ width: '30%' }}><pre className="m-0 p-0 pe-2"><span className="fw-bold fs-6 text-uppercase">{tache}</span></pre></th>
                            <td style={{ width: '55%' }}>
                                <span className="small" dangerouslySetInnerHTML={{ __html: comment.replaceAll('\n', '<br />') }} />
                            </td>
                            <td className="me-0 pe-0 " style={{ width: '15%' }}>
                                <div className="w-100 d-flex align-items-center justify-content-end">
                                    <span className={`py-1 px-2 rounded-2 text-white ${st?.id===-1 ? 'bg-primary' : st?.id===0 ? 'bg-warning' : 'bg-success'} `}>
                                      {st?.titre}
                                </span>

                                    <Dropdown className="ms-2">
                                        <Dropdown.Toggle as={"span"} className="py-2 px-3 rounded-3 bg-secondary-subtle d-inline-flex hover-span cursor-pointer">
                                            <i className="fa fa-ellipsis-v"/>
                                        </Dropdown.Toggle>
                                        {id!==userContext?.idEmp ? ("") : date.toLocaleDateString().split('T')[0] === today && (
                                            <Dropdown.Menu>
                                                {titreStatut
                                                    .filter((element) => element.id !== statut)
                                                    .map((e) => (
                                                        <Dropdown.Item key={e.id} className={`${e.id===-1 ? 'text-primary' : e.id===0 ? 'text-warning' : 'text-success'}`}>
                                                            <i  className={`fa ${e.id===-1 ? 'fa-hourglass-1' : e.id===0 ? 'fa-hourglass-half' : 'fa-hourglass-3'} me-2`} /> {e.titre}
                                                        </Dropdown.Item>
                                                    ))
                                                }
                                                <Dropdown.Divider/>
                                                <Dropdown.Item className="text-info"><i className="me-2 fa fa-edit"/> Modifier</Dropdown.Item>
                                                <Dropdown.Item className="text-danger" onClick={()=>deleteRendu(idRendu)}> <i className="me-2 fa fa-trash-can" /> Supprimer</Dropdown.Item>
                                            </Dropdown.Menu>
                                        )}
                                    </Dropdown>
                                </div>
                            </td>
                        </tr>
                    )
                })}

                {formClicked && (
                    <>
                        <tr>
                            <th >
                                <Form.Group  controlId="tache">
                                    <Form.Control isInvalid={valid} type="text" value={tache} onChange={(event)=>setTache(event.target.value)} placeholder="Nom de la tâche" />
                                </Form.Group>
                            </th>
                            <td >
                                <textarea
                                    className="form-control"
                                    placeholder="Commentaire"
                                    rows="2"
                                    value={comment}
                                    onChange={(event)=>setComment(event.target.value)}
                                />
                            </td>
                            <td >
                                <select
                                    className="form-control"
                                    name="status"
                                    value={statut.toString()}
                                    onChange={(event)=>setStatut(parseInt(event.target.value))}
                                >{titreStatut.map(({id,titre}, key)=>(
                                    <option key={key} value={id}>{titre}</option>
                                ))}
                                </select>
                            </td>
                        </tr>
                    </>
                )}

                </tbody>
            </table>
            {id!==userContext?.idEmp ? ("") : date.toLocaleDateString().split('T')[0] === today ? !formClicked ? (
                <div className="w-100 d-flex justify-content-end">
                    <button type="button" className="btn btn-primary" onClick={()=>handleClickForm(true)}>Ajouter une tâche</button>
                </div>
            ) : (
                <div className="w-100 d-flex justify-content-end">
                    <button type="button" className="btn btn-danger me-2" onClick={()=>handleClickForm(false)}>Annuler</button>
                    {load ? (
                        <button type="button" className="btn btn-primary ms-1" >
                            <span className="spinner-border spinner-border-sm" role="status" aria-hidden="true"/>
                            Loading...
                        </button>
                    ): (
                        <button type="button" className="btn btn-primary ms-1" onClick={subbmit}>Valider</button>
                    )}
                </div>
            ) : ("")}
        </>
    )
}

export default Taches