import MessageText, {DateLimiter, MessageDate, MessageSecondary} from "./MessageText";
import React, {useEffect, useLayoutEffect, useRef, useState} from "react";
import {Message} from "../../Model/Message";

function areDatesEqual(date1, date2) {
    const d1 = new Date(date1);
    const d2 = new Date(date2);
    return (
        d1.getFullYear() === d2.getFullYear() &&
        d1.getMonth() === d2.getMonth() &&
        d1.getDate() === d2.getDate()
    );
}
function diffInMinutes(date1, date2) {
    const d1 = new Date(date1);
    const d2 = new Date(date2);
    const diffMs = Math.abs(d2 - d1);
    return Math.floor(diffMs / (1000 * 60));
}


const MainMessage = ({messages, user, receiver, setMessage, isInsert})=>{
    const scrollMessage = useRef(null);
    const [loadingTop, setLoadingTop] = useState(false);

    const containerRef = useRef(null);
    const messageRefs = useRef({});
    const [topVisibleDate, setTopVisibleDate] = useState(null);

    const checkTopVisibleMessage = () => {
        if (!containerRef.current) return;

        const containerTop = containerRef.current.getBoundingClientRect().top;

        let topMostMessage = null;
        let topMostOffset = Infinity;

        Object.entries(messageRefs.current).forEach(([id, el]) => {
            if (el) {
                const rect = el.getBoundingClientRect();
                const offset = rect.top - containerTop;

                if (offset >= 0 && offset < topMostOffset) {
                    topMostOffset = offset;
                    topMostMessage = { id, date: el.getAttribute("data-date") };
                }
            }
        });

        if (topMostMessage) {
            setTopVisibleDate(topMostMessage.date);
        }
    };
    useEffect(() => {
        const container = containerRef.current;
        if (!container) return;

        const onScroll = () => {
            checkTopVisibleMessage();
        };

        container.addEventListener('scroll', onScroll);
        return () => container.removeEventListener('scroll', onScroll);
    }, []);

    useEffect(() => {
        const container = containerRef.current;
        if (!container) return;

        const handleScroll = async () => {
            if (container.scrollTop ===0 && messages.length>0) {
                setLoadingTop(true);
                const previousScrollHeight = container.scrollHeight;
                Message.getPrevMessage(user.idEmp,receiver.receiver.idEmp ,(new Date(messages[0].dateEnvoye)).toISOString()).then((rep)=>{
                    setMessage(rep, user.idEmp, receiver.receiver.idEmp)
                }).catch((e)=>console.log(e.message)).finally(()=>{
                    setLoadingTop(false)
                })
                setTimeout(() => {
                    const newScrollHeight = container.scrollHeight;
                    container.scrollTop = newScrollHeight - previousScrollHeight;
                }, 0);
            }
        };
        container.addEventListener("scroll", handleScroll);
        return () => container.removeEventListener("scroll", handleScroll);
    }, [user]);

    useLayoutEffect(() => {
        if (scrollMessage.current) {
            scrollMessage.current.scrollIntoView({ behavior: "smooth" });
        }
    }, [receiver.receiver.idEmp,isInsert]);

    return(
        <div ref={containerRef} className="position-sticky flex-grow-1 overflow-y-auto custom-scroll bg-message p-1">
            {messages.length ===0 ? (
                <div className="w-100 text-center mt-2 text-white">
                    <span className="text-print">Démarrez une conversation avec les equipes d' <span className="text-aris fw-bold fs-4">Aris</span> <span className="text-concept fs-4 fw-bold">Concept</span></span>
                </div>
            ): (
                <>
                    {topVisibleDate && (
                        <MessageDate date={topVisibleDate}/>
                    )}
                    {loadingTop && (
                        <div className="w-100 d-inline-flex justify-content-center">
                            <i className="fa fa-spinner fa-spin-pulse fs-5 text-white"/>
                        </div>
                    )}
                    {messages.map((e, index)=>{
                        const dPrev = messages[index-1]
                        let date = null
                        let sameDate = false
                        if (dPrev){
                            if (areDatesEqual(dPrev.dateEnvoye, e.dateEnvoye)){
                                date = null
                                if (dPrev.mine===e.mine && diffInMinutes(dPrev.dateEnvoye, e.dateEnvoye)<10){
                                    sameDate = true
                                }
                            }else{
                                date = e.dateEnvoye
                            }
                        }else{
                            date = messages[0].dateEnvoye
                        }
                        return(
                            <React.Fragment key={e.idMessage}>
                                {date && (
                                    <DateLimiter date={date}/>
                                )}
                                <div ref={(el) => (messageRefs.current[e.idMessage] = el)} data-date={e.dateEnvoye}>
                                    {sameDate ? (
                                        <MessageSecondary
                                            isMine={e.mine}
                                            content={e.message}
                                            date={e.dateEnvoye}
                                            status={e.status}
                                        />
                                    ) : (
                                        <MessageText
                                            isMine={e.mine}
                                            content={e.message}
                                            date={e.dateEnvoye}
                                            status={e.status}
                                        />
                                    )}
                                </div>
                            </React.Fragment>
                        )
                    })}
                </>
            )}
            <div ref={scrollMessage} />
        </div>
    )
}
export default MainMessage