import React, {useCallback, useEffect, useMemo, useState} from "react";
import {Dropdown, Form, InputGroup} from "react-bootstrap";
import EtatEmployer from "../../Model/EtatEmployer";
import {APIURL} from "../../Model/APIURL";

const AdminSearch = ({setUser, setAllUser})=>{

    const [allEmp, setAllEmp] = useState([]);

    useEffect(() => {
        EtatEmployer.getEmployeValider().then((resp)=>{
            setAllUser(resp)
            setAllEmp(resp)
        }).catch(()=>{})
    }, []);

    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [filtered, setFiltered] = useState([]);

    const [show, setShow] = useState(false);

    useEffect(() => {
        let data = allEmp;
        if (matricule) {
            data = allEmp.filter(emp =>{
                if (emp.matricule){
                    return emp.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter(emp =>
                emp.nom.toLowerCase().includes(nom.toLowerCase()) ||
                emp.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        setFiltered(data)
    }, [matricule,nom,allEmp]);

    useEffect(() => {
        if (nom.length>0 || matricule.length>0){
            setShow(true)
        }else{
            setShow(false)
        }
    }, [nom, matricule]);

    const userProfile=useCallback((user)=>{
        if (user?.profile){
            return (
                <img
                    src={APIURL()+`${user.profile}`}
                    alt=""
                    className="border-dark-light rounded-circle mt-0 mx-2 p-0"
                    width={40} height={40}
                    style={{ objectFit: 'cover'}}
                />
            )
        }else{
            return (
                <span className="cursor-pointer position-relative d-flex justify-content-center bg-secondary mx-2 border-dark-light rounded-circle" style={{width:'42px', height: '42px'}}>
                    <i className={`far icon-20 fa-user-circle  my-auto ${user===null ? 'text-concept': 'text-white'}`}/>
                </span>
            )
        }

    },[])

    return(
        <div className="card w-100 mb-3">
            <div className="card-body pt-1">
                <h3 className="text-center">Liste des Salariés</h3>
                <div className="row m-0 p-0">
                    <div className="col-4">
                        <InputGroup className="my-3">
                            <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                            <Form.Control
                                placeholder="matricule"
                                aria-label="matricule"
                                aria-describedby="basic-addon1"
                                type="search"
                                value={matricule}
                                onChange={(event)=>{
                                    setMatricule(event.target.value.replace(/\D/g, ''))
                                }}
                            />
                        </InputGroup>
                    </div>
                    <div className="col-8">
                        <InputGroup className="my-3">
                            <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                            <Form.Control
                                placeholder="nom ou prénom"
                                aria-label="nom"
                                aria-describedby="nom"
                                type="search"
                                value={nom}
                                onChange={(event) => setNom(event.target.value)}
                            />
                        </InputGroup>
                    </div>
                </div>

                <div className="d-flex justify-content-center w-100">
                    <Dropdown.Menu className="w-75 "  show={show}>
                        {filtered.map((emp)=>(
                            <Dropdown.Item key={emp.idEmp} onClick={()=> {
                                setUser(emp)
                                setMatricule('')
                                setNom('')
                            }} as={"div"} className="w-100 d-inline-flex cursor-pointer mb-2 border-bottom border-2 pb-2">
                                {userProfile(emp)}
                                <strong className="me-3">{emp.nom} {emp.prenom}</strong>
                                <span>{emp.matricule.split('').join(' ')}</span>
                            </Dropdown.Item>
                        ))}
                        {filtered.length===0 && (
                            <Dropdown.Header className="text-center">Aucun Employé</Dropdown.Header>
                        )}
                    </Dropdown.Menu>
                </div>
            </div>
        </div>
    )
}
export default AdminSearch