import React from "react";
import {Card, Modal} from "react-bootstrap";

const ShowNews = ({show,close,objectSet}) => {
    return(
        <>
            <Modal
                show={show}
                onHide={close}
                keyboard={false}
                backdrop="static"
                dialogClassName="modal-dialog-centered modal-W position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center w-100"
            >
                <Modal.Header closeButton>
                    <Modal.Title className="small fw-bolder">{objectSet?.date}</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Card className="m-0 p-0 border-0 w-100 rounded-0">
                        <div className="w-100 rounded-2 position-relative" style={{
                            minHeight: '460px',
                            backgroundImage: `url(${objectSet?.image})`,
                            backgroundSize: 'cover',
                            backgroundPosition: 'center',
                        }}/>
                        <h3 className="mt-3 text-center text-concept pb-2 border-bottom">{objectSet?.titre}</h3>
                        <div dangerouslySetInnerHTML={{ __html: objectSet?.desc }} />
                    </Card>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default ShowNews