import React, {useCallback, useContext, useEffect, useMemo, useRef, useState} from "react";
import {Form, InputGroup, Modal} from "react-bootstrap";
import Pagination from "../Main/Utilitaire/Pagination";
import FicheDePaie from "./FicheDePaie";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import {SalaireBase} from "../../Model/Paie/SalaireBase";
import {UserContext} from "../Main/Utilitaire/UserProvider";
import { createRoot } from "react-dom/client";


const BulletinsPaie = ()=>{
    const [date, setDate] = useState(null);
    const formatMonth = useCallback((dt) => {
        if (!dt) return;

        const df = new Date(dt);
        return `${df.getFullYear().toString().padStart(4, "0")}-${String(df.getMonth() + 1).padStart(2, "0")}`;
    }, []);


    const [paginate, setPaginate] = useState(1);
    const [filtered, setFiltered] = useState([]);

    const [show, setShow] = useState(false);
    const ficheRef = useRef(null)
    const [loadingTl, setLoadingTl] = useState({
        isDebut: false,
        isLoading: false,
        fileTerminate: []
    });

    const generatePDF = (element) => {
        setLoadingTl((prev) => ({ ...prev, isDebut: true, isLoading: true }));

        const tempContainer = document.createElement("div");
        tempContainer.style.position = "absolute";
        tempContainer.style.left = "-9999px";
        tempContainer.style.top = "-9999px";
        document.body.appendChild(tempContainer);

        const root = createRoot(tempContainer);

        const onRenderComplete = (node) => {
            if (node) {
                ficheRef.current = node;
                html2canvas(node, { scale: 1 }).then((canvas) => {
                    const imgData = canvas.toDataURL("image/png");
                    const pdf = new jsPDF("p", "mm", "a4");

                    const imgWidth = 210;
                    const imgHeight = (canvas.height * imgWidth) / canvas.width;

                    const fileName = `Fiche_de_Paie_${new Date(element.dateFin).toLocaleDateString("fr-FR", { month: "long", year: "numeric" })}.pdf`;

                    pdf.addImage(imgData, "PNG", 0, 0, imgWidth, imgHeight);
                    pdf.save(fileName);

                    root.unmount();
                    document.body.removeChild(tempContainer);

                    setLoadingTl((prev) => ({
                        ...prev,
                        isLoading: false,
                        fileTerminate: [...prev.fileTerminate, fileName]
                    }));
                });
            }
        };

        root.render(<FicheDePaie element={element} ref={onRenderComplete} />);
    };

    const [allData, setAllData] = useState([]);
    const { user: contextUser} = useContext(UserContext);

    useEffect(() => {
        SalaireBase.getAllFichesByEmp(contextUser?.idEmp).then((data)=>{
            setAllData(data)
        }).catch(()=>{})
    }, [contextUser]);

    useEffect(() => {
        let data = allData;
        if (date){
            data = allData.filter(({dateFin}) =>{
                const dateG = new Date(dateFin)
                const dateE = new Date(date)
                return dateE.getFullYear()===dateG.getFullYear() && dateE.getMonth()===dateG.getMonth()
            });
        }
        setFiltered(data)
    }, [allData, date]);

    const [clickedElement, setClickedElement] = useState(null);
    const clikedView = useCallback(
        (element) => {
            setClickedElement(element)
            setShow(true)
        },
        [],
    );


    return(
        <>
            <div className="w-100 mb-3 d-inline-flex justify-content-between">
                <span className="fs-4 fw-bolder">Mois du {date ? date.toLocaleDateString("fr-FR",  { month: "short", year: "numeric" }) : '------/----'}</span>
                <InputGroup size={"sm"} className="" style={{width: '16vw'}}>
                    <InputGroup.Text id="basic-addon1">Mois du</InputGroup.Text>
                    <Form.Control
                        aria-label="semaine"
                        aria-describedby="basic-addon1"
                        type="month"
                        size={"sm"}
                        value={formatMonth(date)}
                        onChange={(e) => {
                            const strDt = e.target.value.split("-");
                            let newDate
                            if (date){
                                newDate = new Date(date);
                            }else{
                                newDate = new Date()
                            }
                            newDate.setFullYear(Number(strDt[0]));
                            newDate.setMonth(Number(strDt[1]) - 1);
                            setDate(newDate);
                        }}
                    />
                </InputGroup>
            </div>

            <div className="m-0 w-100 rounded-3 bg-white mb-3">
                <div className="rounded-3 p-1 m-0 w-100">
                    <table className="table mb-0 table-striped table-hover">
                        <thead>
                        <tr className="text-center">
                            <th scope="col" className="text-center">Mois</th>
                            <th  scope="col" colSpan={"2"}>
                                <div className="w-100 d-inline-flex justify-content-evenly">
                                    <span className="fw-bolder">Periode du </span>
                                    <span className="fw-bolder">Au</span>
                                </div>
                            </th>
                            <th scope="col" className="text-end">
                                {loadingTl.isDebut && (
                                    <div className="w-100 d-flex justify-content-end">
                                        <span className={`rounded-circle d-flex align-items-center justify-content-center ${loadingTl.isLoading ? 'loading-border' : 'border border-primary border-2'}`} style={{width: '30px', height: '30px'}}>
                                            <i className="fa fa-download text-concept"/>
                                        </span>
                                    </div>
                                )}
                            </th>
                        </tr>
                        </thead>
                        <tbody>
                        {filtered.slice((paginate-1)*12,(paginate)*12).map((element)=>(
                            <tr key={element.idFicheDePaie}>
                                <td className="text-center">{(new Date(element.dateFin)).toLocaleDateString("fr-FR",{month: 'long', year: 'numeric'})}</td>
                                <td colSpan={"2"}>
                                    <div className="w-100 d-inline-flex justify-content-evenly">
                                        <span className="fw-bolder">{new Date(element.dateDebut).toLocaleDateString()}</span>
                                        <span className="fw-bolder">{new Date(element.dateFin).toLocaleDateString()}</span>
                                    </div>
                                </td>
                                <td className="d-flex justify-content-end">
                                    <div className="d-inline-flex justify-content-between">
                                        <button onClick={()=>clikedView(element)} type="button" className="btn btn-dark btn-sm mx-2 text-warning">Voir</button>
                                        <button type="button" onClick={()=>generatePDF(element)} className="btn btn-info btn-sm text-white">Télecharger</button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
                <div className="d-flex justify-content-end w-100 m-0 p-2">
                    <Pagination length={filtered.length % 12 === 0 ? filtered.length / 12 : Math.floor(filtered.length / 12) + 1} active={paginate} setActive={setPaginate}/>
                </div>
            </div>

            <Modal
                show={show}
                onHide={()=>setShow(false)}
                keyboard={false}
                backdrop="static"
                dialogClassName=" position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center width-max"
            >
                <Modal.Header className="position-relative">
                    <div onClick={()=>setShow(false)} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="pt-1">
                    <FicheDePaie element={clickedElement}/>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default BulletinsPaie