import React, { useEffect, useRef, useState} from "react";
import {APIURL} from "../../../../Model/APIURL";
import {convertirHeureDecimalEnHeureMinute, printHeure} from "../../Component/PointageCalendar";

import { OverlayPanel } from 'primereact/overlaypanel';
import AxeHoraire from "./AxeHoraire";
const getHHMM = (dateString) => {
    if (dateString){
        const date = new Date(dateString);
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");
        return `${hours}:${minutes}`;
    }
    return "20:00"
};


const ViewEmp = ({element})=>{
    const spanRef = useRef(null);
    const [dateActivities, setDateActivities] = useState({
        active: [],
        pause: []
    });

    useEffect(() => {
        if (element.activities) {
            const active = [];
            const pause = [];

            element.activities.forEach((e) => {
                const entry = {
                    start: getHHMM(e.start),
                    end: getHHMM(e.end),
                };
                if (e.active===false) {
                    pause.push(entry);
                } else {
                    active.push(entry);
                }
            });

            setDateActivities({ active, pause });
        }
    }, [element]);


    return(
        <div className="rounded-3 p-2 my-2 w-100 border border-primary-subtle">
            <div className="w-100 d-inline-flex align-items-center border-bottom border-primary-subtle position-relative">
                <div className="">
                    <img
                        src={APIURL()+`${element.pointage.employe.profile}`}
                        alt=""
                        className="border-dark-light rounded-circle mt-0 mx-2 p-0"
                        width={50} height={50}
                        style={{ objectFit: 'cover'}}
                        decoding={"async"}
                    />
                </div>
                <div className="d-flex w-100 justify-content-start flex-column text-print ps-2">
                    <span className="fw-bolder text-uppercase fw-5">{element.pointage.employe.nom} <span className="text-capitalize fs-5">{element.pointage.employe.prenom}</span></span>
                    <span className="fs-4 text-grey fw-bold">{element.pointage.employe.matricule}</span>
                </div>
                {element.pointage.idPointage>0 && (
                    <div className="position-absolute width-max end-0 top-0 mt-2 me-2 cursor-pointer">
                    <span  ref={spanRef} onClick={(e) => spanRef.current.toggle(e)} className="bg-dark bg-opacity-25 text-dark rounded-3 py-1 px-3 hover-span">
                        <i className="fa fa-ellipsis-v"/>
                        <OverlayPanel ref={spanRef}>
                            <div className="d-flex flex-column width-max">
                                <div className="text-print mb-3">
                                    <h3 className="mb-2 text-grey">Matin</h3>
                                    <AxeHoraire
                                        initH={6}
                                        endH={12}
                                        actifs={dateActivities.active}
                                        inactifs={dateActivities.pause}
                                        pointage={{dateDebut: getHHMM(element.pointage.dateDebut), dateFin: getHHMM(element.pointage.dateFin)}}
                                    />
                                </div>
                                <div className="text-print">
                                    <h3 className="mb-2 text-grey">Midi</h3>
                                    <AxeHoraire
                                        initH={12}
                                        endH={18}
                                        actifs={dateActivities.active}
                                        inactifs={dateActivities.pause}
                                        pointage={{dateDebut: getHHMM(element.pointage.dateDebut), dateFin: getHHMM(element.pointage.dateFin)}}
                                    />
                                </div>
                            </div>
                        </OverlayPanel>
                    </span>
                    </div>
                )}
            </div>
            <div className="mt-2 row w-100 mx-0 p-0">
                <div className="col-6">
                    <span className="fw-bolder mb-2 text-grey  fs-5">Pointage</span>
                    <div className="text-print">
                        <span className="mx-2 fw-bolder fs-4">{printHeure(element.pointage.dateDebut)}</span>
                        <i className="fa fa-long-arrow-alt-right me-2"/>
                        <span className="fw-bolder fs-4">{printHeure(element.pointage.dateFin)}</span>
                    </div>
                </div>
                <div className="col-6 d-inline-flex justify-content-between align-items-center">
                    <div className="d-flex flex-column text-success">
                        <span className="fw-bolder pb-1 border-bottom border-success width-max px-1">Active</span>
                        <span className="text-print fw-bolder fs-4">{convertirHeureDecimalEnHeureMinute(element.active)}</span>
                    </div>
                    <div className="d-flex flex-column text-warning">
                        <span className="fw-bolder pb-1 border-bottom border-warning width-max px-1">Passive</span>
                        <span className="text-print fw-bolder fs-4">{convertirHeureDecimalEnHeureMinute(element.passive)}</span>
                    </div>
                    <div className="d-flex flex-column text-danger">
                        <span className="fw-bolder pb-1 border-bottom border-danger width-max px-1">Pause</span>
                        <span className="text-print fw-bolder fs-4">{convertirHeureDecimalEnHeureMinute(element.pause)}</span>
                    </div>
                </div>
            </div>
        </div>
    )
}
export default ViewEmp