import {Dialog} from "primereact/dialog";
import React, {useCallback, useEffect, useRef, useState} from "react";
import './dialog.css'
import {APIURL} from "../../Model/APIURL";
import { IconField } from 'primereact/iconfield';
import { InputIcon } from 'primereact/inputicon';
import {InputText} from "primereact/inputtext";
import { InputTextarea } from 'primereact/inputtextarea';
import Picker from '@emoji-mart/react';
import data from '@emoji-mart/data';
import {Message} from "../../Model/Message";
import Profile from "./Profile";
import MainMessage from "./MainMessage";
import useSendMessage from "../../WS/useSendMessage";
import useWebSocket from "../../WS/useWebSocket";
import {useUserStatus} from "../Main/Salarier/Hook/StatusUserWSContext";
import {iconStatut} from "./MessageText";

const DialogMessage = ({showMessage, hide, user, setStatut})=>{

    const [isMessageView, setIsMessageView] = useState(false);
    const scrollRef = useRef(null);

    //j'attend le message avec: messgae/idUser, de atao instance anak 1 ihany ny ao am'ilay websocket!

    const [messageText, setMessageText] = useState('');
    const [showEmojie, setShowEmojie] = useState(false);
    const addEmoji = (emoji) => {
        setMessageText(prev => prev + emoji.native);
    };

    const [allUserMessages, setAllUserMessages] = useState([])

    useEffect(() => {
        if (user?.idEmp){
            Message.getMyMessages(user.idEmp).then((res)=>{
                setAllUserMessages(res)
                let sta = 0
                res
                    .filter(e => e.messageBody.length > 0)
                    .map((e) => {
                        if (e.messageBody[e.messageBody.length - 1].status==="nonVue"){
                            sta+=1
                        }
                    })
                setStatut(sta)
            }).catch((e)=>{
                console.log(e.message)
            })
        }
    }, [user]);

    const [userCliqued, setUseCliqued] = useState(null);

    const ChangeUserClicked = useCallback(
        (id) => {
            const fil = allUserMessages.find((e)=>e.receiver.idEmp===id)
            setMessageText("")
            if (fil){
                setUseCliqued(fil)
            }else{
                return
            }
            setIsMessageView(true)
        },
        [allUserMessages]
    );
    const { getUserStatus } = useUserStatus();


    const sendMessage = useSendMessage()
    const {body} = useWebSocket(user?.idEmp ? "/message/" + user.idEmp : null)
    const idMessage = useRef(-1)

    const sdM = useCallback(
        () => {
            const id  = idMessage.current - 1
            sendMessage("/app/send/"+userCliqued.receiver.idEmp, {message: messageText.trim(), senderId: user.idEmp, transfert: false, idChat: id})

            setUseCliqued((prev)=>({...prev, messageBody: [...prev.messageBody, {idMessage: id, mine: true, modified: false, status: 'loading', transfert: false, message: messageText.trim(), dateEnvoye: new Date()}]}))
            idMessage.current = id-1
            setMessageText("")
        },
        [sendMessage, userCliqued, messageText, user, idMessage]
    );

    const addMess = useCallback(
        (mes,idSender, idReceiver) => {

            if (userCliqued){
                if (userCliqued.receiver.idEmp === idReceiver) {
                    setUseCliqued(prev => {
                        if (prev){
                            const existingIds = new Set(prev.messageBody.map(m => m.idMessage));
                            const newMessages = mes.filter(m => !existingIds.has(m.idMessage));

                            return {
                                ...prev,
                                messageBody: [...newMessages, ...prev.messageBody],
                            };
                        }
                        return prev
                    });
                }
            }

            setAllUserMessages(prev =>
                prev.map(conversation => {
                    if (conversation.receiver.idEmp === idReceiver) {
                        const existingIds = new Set(conversation.messageBody.map(m => m.idMessage));
                        const newMessages = mes.filter(m => !existingIds.has(m.idMessage));

                        return {
                            ...conversation,
                            messageBody: [...newMessages, ...conversation.messageBody],
                        };
                    }
                    return conversation;
                })
            );
        }, [userCliqued]
    );


    useEffect(() => {
        if (body && user){
            setStatut((prev)=>prev+1)
            const mesData = {idMessage: body.message.idMessage, attachement: body.message.attachement, status: body.message.status, dateEnvoye: body.message.dateEnvoye, mine: user.idEmp===body.message.sender.idEmp, transfert: body.message.transfert, modified: body.message.modified, message: body.message.message}
            if (userCliqued){
                if (userCliqued.receiver.idEmp===body.message.receiver.idEmp){
                    const currentMessageNotSent = userCliqued.messageBody.find((mes)=>mes.idMessage === body.idF && mes.status==="loading")
                    if (currentMessageNotSent){
                        setUseCliqued((prev) => ({
                            ...prev,
                            messageBody: prev.messageBody.map((mes) =>
                                mes.idMessage === body.idF ? mesData : mes
                            ),
                        }));
                    }else{
                        setUseCliqued((prev)=>({...prev, messageBody: [...prev.messageBody, mesData]}))
                    }
                }
                if (userCliqued.receiver.idEmp===body.message.sender.idEmp){
                    setUseCliqued((prev)=>({...prev, messageBody: [...prev.messageBody, mesData]}))
                }
            }

            setAllUserMessages(prev =>
                prev.map(conversation =>
                    conversation.receiver.idEmp === body.message.receiver.idEmp || conversation.receiver.idEmp===body.message.sender.idEmp
                        ? {
                            ...conversation,
                            messageBody: [...conversation.messageBody, mesData],
                        }
                        : conversation
                )
            );
        }
    }, [body, user]);

    return(
        <Dialog
            modal
            closable={false}
            position={'bottom-right'}
            visible={showMessage}
            style={{ width: '28rem', height: '60rem', overflowY: 'auto', backgroundColor: 'white' }}
            onHide={() => { hide()}}
            blockScroll={true}
            header={()=>(
                <>
                    <div onClick={hide} style={{ width: '30px', height: '30px'}} className="position-absolute top-0 end-0 bg-icon-close rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close text-white"/>
                    </div>
                    <div className="d-inline-flex justify-content-between align-items-center">
                        {isMessageView && userCliqued ? (
                            <>
                                <button onClick={()=> {
                                    setIsMessageView(false)
                                    setUseCliqued(null)
                                }}  className="py-0 px-2 btn" aria-label="back">
                                    <i className="fa fa-long-arrow-alt-left fs-6"/>
                                </button>
                                <div className="d-inline-flex justify-content-between align-items-center">
                                    <div className="profile">
                                        <img
                                            src={APIURL()+`${userCliqued?.receiver?.profile}`}
                                            alt=""
                                            className="border-dark-light rounded-circle mt-0 me-1 p-0"
                                            width={50} height={50}
                                            style={{ objectFit: 'cover'}}
                                        />
                                    </div>
                                    <div className="affiche-name-user flex-grow-1">
                                        <span className="text-capitalize">{userCliqued?.receiver?.nom} {userCliqued?.receiver?.prenom}</span>
                                    </div>
                                    <div className="d-inline-flex justify-content-between">
                                        <span><i className="fa fa-video fs-5 color-param cursor-pointer me-3"/></span>
                                        <span><i className="fa fa-square-phone fs-5 color-param cursor-pointer"/></span>
                                    </div>
                                </div>
                            </>
                        ): (
                            <>
                                <div className="profile">
                                    <img
                                        src={APIURL()+`${user.profile}`}
                                        alt=""
                                        className="border-dark-light rounded-circle mt-0 me-1 p-0"
                                        width={50} height={50}
                                        style={{ objectFit: 'cover'}}
                                    />
                                </div>
                                <div className="affiche-name">
                                    <span className="text-capitalize">{user.nom} {user.prenom}</span>
                                </div>
                            </>
                        )}

                    </div>
                </>
            )}
            headerClassName="bg-header shadow py-2 pe-2 ps-1 position-relative"
            contentClassName="p-0 custom-scroll"
            footer={null}>
            {isMessageView ? (
                <div className="d-flex flex-column position-relative h-100 w-100">
                    {userCliqued && (
                        <MainMessage isInsert={idMessage.current} messages={userCliqued.messageBody} user={user} receiver={userCliqued} setMessage={addMess}/>
                    )}
                    {showEmojie && (
                        <div className="d-flex w-100 overflow-y-hidden rounded-0 custom-scroll overflow-x-hidden" style={{ height: '200px', backgroundColor: '#2d2d2d'}}>
                            <Picker
                                searchPosition="none" data={data} onEmojiSelect={addEmoji} previewPosition="none" perLine={12}
                                emojiSize={24} emojiButtonSize={36} skinTonePosition="none" navPosition="none"
                            />
                        </div>
                    )}
                    <div className="position-sticky w-100 d-inline-flex py-2 bg-dark shadow align-items-center">
                        <IconField className="flex-grow-1" iconPosition={"left"}>
                            <InputIcon onClick={(e) => setShowEmojie(prev=>!prev)} className="fa fa-face-smile-beam cursor-pointer pe-1 color-param"> </InputIcon>
                            <InputTextarea value={messageText} onChange={(e)=>setMessageText(e.target.value)} autoResize rows={1} placeholder="ecrire un message..." type="text" className="w-100 no-resize input bg-dark me-0 bg-opacity-75 py-2 rounded-3" />
                        </IconField>
                        {messageText.trim().length===0 ? (
                            <>
                                <span className="me-2 color-param">
                                    <i className="fa fa-microphone fs-4 cursor-pointer"/>
                                </span>
                                <span className="me-2">
                                    <i className="fa fa-paperclip color-param fs-4 cursor-pointer"/>
                                </span>
                            </>
                        ): (
                            <span onClick={sdM}>
                                <i className="fa fa-paper-plane text-primary me-2 fs-4 cursor-pointer"/>
                            </span>
                        )}
                    </div>
                </div>
            ): (
                <div className="bg-body d-flex flex-column">
                    <div className="p-2 w-100 bg-darker-info pb-3 text-white">
                        <IconField className="w-100" iconPosition="right">
                            <InputIcon className="fa fa-magnifying-glass"> </InputIcon>
                            <InputText placeholder="rechercher un contact" type="search" className="w-100 rounded-pill input py-2 bg-dark bg-opacity-25" />
                        </IconField>
                    </div>
                    <div ref={scrollRef}  onWheel={(e) => {
                        // e.preventDefault();
                        scrollRef.current.scrollLeft -= e.deltaY;
                        e.stopPropagation()
                    }} className="d-flex bg-darker-info text-white gap-2 overflow-x-auto overflow-y-hidden px-2 border-bottom pt-1 pb-1 ft" style={{ whiteSpace: "nowrap", scrollbarWidth: 'none', msOverflowStyle: 'none'}}>
                        {allUserMessages.map((e)=>(
                            <div  onClick={()=>ChangeUserClicked(e.receiver.idEmp)} key={e.receiver.idEmp} className="d-flex flex-column cursor-pointer width-max mx-1"  style={{ textAlign: 'center', width: '60px' }}>
                                <Profile element={e.receiver} getStatus={getUserStatus}/>
                                <span className="small text-print text-truncate text-capitalize" style={{width: '60px'}}>{e.receiver.prenom}</span>
                            </div>
                        ))}
                    </div>
                    <div className="flex-grow-1 mt-3 px-2">
                        {/*{allUserMessages.map((e)=>{*/}
                        {/*    if (e.messageBody.length>0){//je veux trier par ordre de e.messageBody[e.messageBody.length -1].dateEnvoye*/}
                        {/*        return(*/}
                        {/*            <div key={e.receiver.idEmp} onClick={()=>ChangeUserClicked(e.receiver.idEmp)} className="w-100 mb-3 d-inline-flex align-items-center justify-content-between cursor-pointer">*/}
                        {/*                <img*/}
                        {/*                    src={APIURL()+`${e.receiver.profile}`}*/}
                        {/*                    alt=""*/}
                        {/*                    className="rounded-circle border me-2"*/}
                        {/*                    style={{ width: "45px", height: "45px", objectFit: "cover" }}*/}
                        {/*                />*/}
                        {/*                <div className="d-flex flex-column affiche-content flex-grow-1">*/}
                        {/*                    <span className="fw-bold text-capitalize affiche-content">{e.receiver.nom} {e.receiver.prenom}</span>*/}
                        {/*                    <span className="small affiche-content">*/}
                        {/*                        {e.messageBody[e.messageBody.length -1].message}*/}
                        {/*                    </span>*/}
                        {/*                </div>*/}
                        {/*                <span className="fs-5 pe-1">{iconStatut(e.messageBody[e.messageBody.length -1].status, 'text-primary')}</span>*/}
                        {/*            </div>*/}
                        {/*        )*/}
                        {/*    }*/}
                        {/*})}*/}
                        {allUserMessages
                            .filter(e => e.messageBody.length > 0) // Filtrer pour ne garder que les messages ayant un corps
                            .sort((a, b) => {
                                // Trier par la date du dernier message (le plus récent en premier)
                                const lastMessageA = new Date(a.messageBody[a.messageBody.length - 1].dateEnvoye);
                                const lastMessageB = new Date(b.messageBody[b.messageBody.length - 1].dateEnvoye);
                                return lastMessageB - lastMessageA; // Tri décroissant (le plus récent en premier)
                            })
                            .map((e) => {
                                return (
                                    <div key={e.receiver.idEmp} onClick={() => ChangeUserClicked(e.receiver.idEmp)} className="w-100 mb-3 d-inline-flex align-items-center justify-content-between cursor-pointer">
                                        <img
                                            src={APIURL() + `${e.receiver.profile}`}
                                            alt=""
                                            className="rounded-circle border me-2"
                                            style={{ width: "45px", height: "45px", objectFit: "cover" }}
                                        />
                                        <div className="d-flex flex-column affiche-content flex-grow-1">
                                            <span className="fw-bold text-capitalize affiche-content">
                                                {e.receiver.nom} {e.receiver.prenom}
                                            </span>
                                            <span className="small affiche-content">
                                                {e.messageBody[e.messageBody.length - 1].message}
                                            </span>
                                        </div>
                                        <span className="fs-5 pe-1">
                                            {iconStatut(e.messageBody[e.messageBody.length - 1].status, 'text-primary')}
                                        </span>
                                    </div>
                                );
                            })}

                    </div>
                </div>
            )}
        </Dialog>
    )
}
export default DialogMessage