import React, {useContext, useState} from "react";
import AllRendu from "./AllRendu";
import {UserContext} from "../Main/Utilitaire/UserProvider";
import AdminSearch from "./AdminSearch";

const MesRendu = () => {
    const {user} = useContext(UserContext);
    const [idUser, setIdUser] = useState(user);
    const [allUser, setAllUser] = useState([]);
    return(
        <>
            {user?.type.idType ===1 && (
                <AdminSearch setUser={setIdUser} setAllUser={setAllUser}/>
            )}
            <AllRendu user={idUser} allUser={allUser} setUser={setIdUser}/>
        </>
    )
}

export default MesRendu