import React, {useEffect, useState} from "react";
import RenduFile from "../../Model/RenduFile";
import ViewFile from "./ViewFile";

const FileWeek = ({debut,fin, user})=>{
    const [files, setFiles] = useState([]);
    useEffect(() => {
        RenduFile.getFileWeek(debut,fin,user?.idEmp).then((resp)=>{
            setFiles(resp)
        }).catch(()=>{})
    }, [user?.idEmp]);
    return(
        <>
            <div className="w-100 p-2">
                {files.map((data)=>(
                    <ViewFile key={data.id} data={data}/>
                ))}
            </div>
        </>
    )
}

export default FileWeek