export default class DepModel {
    titre
    contenue
    dataPublication


    constructor(titre, contenu, dataPublication) {
        this.titre = titre;
        this.contenue = contenu;
        this.dataPublication = dataPublication;
    }

    static async getDepeche(){
        const response = await fetch("https://www.orange.mg/api/getDepechePreviewFr" , {
            method: 'get',
            headers: {
                "Content-Type": 'application/json',
            },
        });

        if (response.ok) {
            return await response.json()
        }else{
            return []
        }
    }
}