import React, {useEffect, useState} from "react";
import {Col, Form, Row, Spinner, Toast} from "react-bootstrap";
import Allinfo from "../../../Model/Allinfo";
import {useNavigate} from "react-router-dom";

const ModifLog = ({setActif,object,close,changeValueUser,isModifier}) => {
    const [login,setLogin]=useState('')
    const [mdp,setMdp]=useState('')
    const [validation,setValidation]=useState('')
    const [showMdp,setShowMdp]=useState(false)
    const [loading,setLoading]=useState(false)
    const [erreur,setErreur]=useState(false)
    const [erreurText,setErreurText]=useState('')

    useEffect(()=>{
        if (object){
            setLogin(object.login)
        }
    },[object])

    const handleSubmit = (event) => {
        event.preventDefault();
        if (validation.trim().length<6){
            return
        }
        setLoading(true)
        Allinfo.modifEmployee({
            ...object,
            login: login,
            mdp: validation
        },mdp ).then((res)=>{
            close()
            isModifier((prev)=>!prev)
        }).catch((e)=>{
            setErreur(true)
            setErreurText(e.message)
        }).finally(()=>{
            setLoading(false)
        })
    };
    return (
        <>
            <Form autoComplete={"off"} onSubmit={handleSubmit}>
                <Row className="mb-3">
                    <Form.Group className="mb-3" as={Col} md="12" controlId="nom">
                        <Form.Label className="fw-bold small text-light-emphasis">Matricule</Form.Label>
                        <Form.Control
                            required
                            type="text"
                            size={"sm"}
                            disabled
                            className="bg-transparent border-dark-light"
                            placeholder="email"
                            value={login.split('').join(' ')}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="6" controlId="mdp">
                        <Form.Label className="fw-bold small text-light-emphasis">Ancien mot de passe</Form.Label>
                        <Form.Control
                            required
                            size={"sm"}
                            type={showMdp ? 'text' : 'password'}
                            className="bg-transparent border-dark-light"
                            value={mdp}
                            onChange={(e)=>setMdp(e.target.value)}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="6" controlId="validation">
                        <Form.Label className="fw-bold small text-light-emphasis">Nouveau mot de passe</Form.Label>
                        <Form.Control
                            required
                            size={"sm"}
                            type={showMdp ? 'text' : 'password'}
                            className="bg-transparent border-dark-light"
                            value={validation}
                            onChange={(e)=>setValidation(e.target.value)}
                            isInvalid={validation.trim().length<6 && validation.trim().length>0}
                        />
                    </Form.Group>

                    <Form.Group className="mb-3" as={Col} md="12">
                        <Form.Check
                            type={'checkbox'}
                            id={`default-${'checkbox'}`}
                            label={`Afficher le mot de passe`}
                            value={showMdp}
                            onClick={()=>setShowMdp(!showMdp)}
                        />
                    </Form.Group>
                </Row>
                <Row className="mb-2">
                    <Col md={6}>
                        <button type="button" onClick={()=>setActif(2)} className="btn btn-lg bg-aris text-white w-100 btn-sm">Précedent</button>
                    </Col>
                    <Col md={6}>
                        <button type={loading ? 'button' : 'submit'} className="btn btn-lg bg-blue text-white w-100 btn-sm">
                            {loading ? (
                                <Spinner size={"sm"} animation="border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </Spinner>
                            ) : ('Terminer')}
                        </button>
                    </Col>
                </Row>
            </Form>
            <div className="position-fixed bottom-0 end-0 width-max p-2">
                <Toast bg={"danger"} show={erreur} onClose={()=>setErreur(false)} autohide delay={5000}>
                    <Toast.Header>
                        <i className="rounded me-2 text-aris icon-30 fas fa-circle-exclamation"/>
                        <strong className="me-auto">Erreur</strong>
                        <small className="text-muted">Maintenant</small>
                    </Toast.Header>
                    <Toast.Body className><strong>{erreurText}</strong></Toast.Body>
                </Toast>
            </div>
        </>
    )
}
export default ModifLog