import React, {useCallback, useEffect, useRef, useState} from "react";
import { Col, Form, Row, Spinner, Toast, Popover, OverlayTrigger} from "react-bootstrap";
import {useLocation, useNavigate} from 'react-router-dom';
import Allinfo from "../Model/Allinfo";

const InfoLogin = ({setText}) => {

    const { search } = useLocation();
    const navigate=useNavigate()
    const queryParams = new URLSearchParams(search);

    useEffect(()=>{
        if (queryParams.size<19){
            navigate("/inscription/")
            return
        }
        setText("Information de Connexion")
    },[queryParams])
    const [login,setLogin]=useState('0 0 0 0')
    const [mdp,setMdp]=useState('')
    const [validation,setValidation]=useState('')
    const [showMdp,setShowMdp]=useState(false)
    const [validated, setValidated] = useState(false);

    const [loading,setLoading]=useState(false)
    const [erreur,setErreur]=useState(false)
    const [erreurText,setErreurText]=useState('')

    const [image, setImage] = useState(null);
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const [stream, setStream] = useState(null);
    // const isCameraActive = async () => {
    //     const devices = await navigator.mediaDevices.enumerateDevices();
    //     const activeCameras = devices.filter(
    //         (device) => device.kind === "videoinput" && device.deviceId
    //     );
    //     return activeCameras.length > 0;
    // };
    const isCameraActive = async () => {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoInputs = devices.filter((device) => device.kind === "videoinput");

        for (const input of videoInputs) {
            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: { deviceId: { exact: input.deviceId } },
            });
            const activeTracks = mediaStream.getTracks().filter((track) => track.readyState === "live");
            mediaStream.getTracks().forEach((track) => track.stop()); // Libère les ressources immédiatement
            if (activeTracks.length > 0) {
                return true; // Une caméra est active
            }
        }
        return false;
    };


    const startCamera = async () => {
        try{
            const active = await isCameraActive();
            if (active) {
                console.warn("Camera already started");
                await stopAllCameras()
            }

            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: true
            });
            setStream(mediaStream);
            if (videoRef.current) {
                videoRef.current.srcObject = mediaStream;
                videoRef.current.play()
            }
        }catch (e) {}
    };

    const capturePhoto = () => {
        if (videoRef.current) {
            const canvas = document.createElement('canvas');
            const context = canvas.getContext('2d');
            canvas.width = videoRef.current.videoWidth;
            canvas.height = videoRef.current.videoHeight;
            context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
            const photo = canvas.toDataURL('image/png');
            setImage(photo);
            stopCamera()
        }
    };
    const captClicked=useCallback(()=>{
        if (image!==null){
            setImage(null)
        }else{
            capturePhoto()
        }
    },[image])

    const stopCamera = () => {
        if (stream) {
            stream.getTracks().forEach((track) => track.stop());
            setStream(null);
        }
        //on coupe ausi la video!!
        if (videoRef.current) {
            videoRef.current.pause(); // Arrêter la lecture
            videoRef.current.srcObject = null; // Dissocier le flux vidéo
        }
    };
    const [showDelete,setShowDelete]=useState(false)
    useEffect(()=>{
        if (image===null){
            startCamera()
            setShowDelete(false)
        }else{
            stopCamera()
            setShowDelete(true)
        }
    },[image])

    const handleFileUpload = (e) => {
        stopCamera();
        const file = e.target.files[0];
        const reader = new FileReader();
        if (file) {
            reader.readAsDataURL(file);
        }
        reader.onloadend = () => {
            setImage(reader.result);
        };
    };
    const fileInputRef = useRef(null);
    const handleDivClick = () => {
        fileInputRef.current.click();
    };
    const popoverRight = (
        <Popover id="popover-positioned-right" title="Popover right">
            <div className="p-2">
                <strong>Contactez le responsable pour vous fournir la matricule</strong>
            </div>
        </Popover>
    );
    const handleSubmit = useCallback(
        (event) => {
            event.preventDefault();
            const form = event.currentTarget;
            if (form.checkValidity() === false) {
                event.stopPropagation();
            }else{
                if (validation!==mdp){
                    return
                }
                else{
                    var blackImage=''
                    if (image===null){
                        const canvas = document.createElement('canvas');
                        const context = canvas.getContext('2d');

                        canvas.width = 230;
                        canvas.height = 230;

                        context.fillStyle = 'black';
                        context.fillRect(0, 0, canvas.width, canvas.height);

                        blackImage = canvas.toDataURL('image/png');
                    }
                    if (mdp.length<6){
                        return;
                    }
                    setLoading(true)
                    const allInfo=new Allinfo(
                        JSON.parse(decodeURIComponent(queryParams.get("type"))),
                        queryParams.get('nom'),
                        queryParams.get('prenom'),
                        new Date(queryParams.get('naissance')),
                        queryParams.get('tel'),
                        queryParams.get('adresse'),
                        queryParams.get('cin'),
                        new Date(queryParams.get('valide')),
                        queryParams.get('nationalite'),
                        JSON.parse(decodeURIComponent(queryParams.get("genre"))),
                        JSON.parse(decodeURIComponent(queryParams.get("statut"))),
                        queryParams.get('enfant'),
                        JSON.parse(decodeURIComponent(queryParams.get("niveau"))),
                        new Date(queryParams.get('entre')),
                        queryParams.get('numCanps'),
                        JSON.parse(decodeURIComponent(queryParams.get("banque"))),
                        queryParams.get('rib'),
                        queryParams.get('contact'),
                        queryParams.get('telContact'),
                        login.replace(/\s/g,''),
                        mdp,
                        -100,
                        image ? image : blackImage
                    )

                    Allinfo.addEmployee(allInfo).then((res)=>{
                        if (res){
                            window.electronStore.set('token', res);
                            navigate("/accueil")
                        }
                    }).catch((e)=>{
                        setErreur(true)
                        setErreurText(e.message)
                    }).finally(()=>{
                        setLoading(false)
                        stopCamera()
                    })
                }
            }

            setValidated(true);
        },
        [image,mdp,validation,login,queryParams],
    );

    // const stopAllCameras = async () => {
    //     stopCamera()
    //     try {
    //         const devices = await navigator.mediaDevices.enumerateDevices();
    //         const videoDevices = devices.filter((device) => device.kind === "videoinput");
    //
    //         for (const device of videoDevices) {
    //             const mediaStream = await navigator.mediaDevices.getUserMedia({
    //                 video: { deviceId: { exact: device.deviceId } },
    //             });
    //             if (mediaStream.getVideoTracks().some((track) => track.readyState === "live")) {
    //                 mediaStream.getTracks().forEach((track) => track.stop());
    //                 return true;
    //             }
    //         }
    //         return false;
    //     } catch (e) {
    //         return false;
    //     }
    // };
    const stopAllCameras = async () => {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoInputs = devices.filter((device) => device.kind === "videoinput");

        const tracksToStop = [];
        for (const input of videoInputs) {
            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: { deviceId: { exact: input.deviceId } },
            });
            tracksToStop.push(...mediaStream.getTracks());
        }

        tracksToStop.forEach((track) => track.stop());
    };

    useEffect(() => {
        const cleanup = async () => {
            console.log("destruction...");
            await stopAllCameras();
        };

        return cleanup;  // On retourne la fonction de nettoyage sans async directement
    }, [search]);
    return(
        <>
            <Form noValidate validated={validated} autoComplete={"off"} onSubmit={handleSubmit}>
                <Row className="mb-1 d-flex justify-content-center">
                    <div className="d-flex position-relative justify-content-center p-2">
                        <input
                            type="file"
                            accept="image/*"
                            ref={fileInputRef}
                            style={{ display: 'none' }}
                            onChange={handleFileUpload}
                        />
                        {image ? (
                            <img
                                src={image}
                                alt="captured or uploaded"
                                className="border-dark-light rounded-circle z-1"
                                width={130} height={130}
                                style={{ objectFit: 'cover' }}
                            />
                        ) : (
                            <>
                                <div className="d-flex justify-content-center">
                                    <video ref={videoRef} className="border-dark-light rounded-circle " width={130} height={130} style={{ objectFit: 'cover', transform: 'scale(1.5)' }} />
                                    <canvas ref={canvasRef} style={{ display: 'none' }} />
                                </div>

                            </>
                        )}
                        <div className={`${showDelete ? 'position-absolute z-3 top-0 bg-opacity-50 ms-7 bg-white width-height-sam rounded-circle d-flex justify-content-center shadow-lg' : 'd-none'}`}>
                            <i className="fa-solid fa-xmark text-danger my-auto cursor-pointer" onClick={()=>setImage(null)} />
                        </div>
                        <div className={`position-absolute z-2 bottom-0 bg-opacity-50  bg-white rounded-pill d-flex justify-content-between shadow-lg`}>
                            <i className="fa-solid fa-image text-info py-2 px-3 cursor-pointer" onClick={handleDivClick}/>
                            <i className="fa fa-camera text-success py-2 px-3 cursor-pointer" onClick={()=>captClicked()}/>
                        </div>
                    </div>
                </Row>
                <Row className="mb-3">
                    <Form.Group className="mb-3" as={Col} md="12" controlId="nom">
                        <Form.Label className="fw-bold d-inline-flex">
                            Matricule
                            <div className="ms-2">
                                <OverlayTrigger trigger={['hover', 'focus']} placement="right" overlay={popoverRight}>
                                    <i onClick={(e)=>e.preventDefault()} className="fa fa-circle-question small text-info cursor-pointer"/>
                                </OverlayTrigger>
                            </div>
                        </Form.Label>
                        <Form.Control
                            required
                            type="text"
                            disabled={loading}
                            className="bg-transparent text-white border-dark-light"
                            value={login}
                            onChange={(e) => {
                                let value = e.target.value.replace(/\D/g, '')
                                if (value.length > 0 && value[0] === '0') {
                                    value = value.substring(1)
                                }
                                if (value.length > 4) {
                                    value = value.slice(0, 4)
                                } else {
                                    value = value.padStart(4, '0')
                                }
                                setLogin(value.split('').join(' '));
                            }}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="6" controlId="mdp">
                        <Form.Label className="fw-bold">Mot de passe</Form.Label>
                        <Form.Control
                            required
                            disabled={loading}
                            type={showMdp ? 'text' : 'password'}
                            className="bg-transparent text-white border-dark-light"
                            value={mdp}
                            onChange={(e)=>setMdp(e.target.value)}
                            isInvalid={mdp.length<6 && mdp.length>0}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="6" controlId="validation">
                        <Form.Label className="fw-bold">Validation mot de passe</Form.Label>
                        <Form.Control
                            required
                            type={showMdp ? 'text' : 'password'}
                            className="bg-transparent text-white border-dark-light"
                            disabled={loading}
                            value={validation}
                            onChange={(e)=>setValidation(e.target.value)}
                            isInvalid={validation!==mdp && validation.length>2}
                        />
                    </Form.Group>

                    <Form.Group className="mb-3" as={Col} md="12">
                        <Form.Check
                            type={'checkbox'}
                            id={`default-${'checkbox'}`}
                            label={`Afficher le mot de passe`}
                            value={showMdp}
                            onClick={()=>setShowMdp(!showMdp)}
                        />
                    </Form.Group>
                </Row>
                <Row>
                    <Col md={6}>
                        <button type="button" disabled={loading} onClick={()=>{navigate(`/inscription/rh-info?${queryParams.toString()}`)}} className="btn btn-lg bg-aris text-white w-100">Précedent</button>
                    </Col>
                    <Col md={6}>
                        <button type={loading ? 'button' : 'submit'} className="btn btn-lg bg-blue text-white w-100">
                            {loading ? (
                                <Spinner size={"sm"} animation="border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </Spinner>
                            ) : ('Terminer')}
                        </button>
                    </Col>
                </Row>
            </Form>
            <div className="position-fixed bottom-0 end-0 width-max p-2">
                <Toast bg={"danger"} show={erreur} onClose={()=>setErreur(false)} autohide delay={5000}>
                    <Toast.Header>
                        <i className="rounded me-2 text-aris icon-30 fas fa-circle-exclamation"/>
                        <strong className="me-auto">Erreur</strong>
                        <small className="text-muted">Maintenant</small>
                    </Toast.Header>
                    <Toast.Body className><strong>{erreurText}</strong></Toast.Body>
                </Toast>
            </div>
        </>
    )
}

export default InfoLogin