import {Galleria} from "primereact/galleria";
import React, {useEffect, useRef, useState} from "react";
import {APIURL} from "../../../Model/APIURL";


const SingleEvent = ({content})=>{

    const [images, setImages] = useState([]);
    const galleria = useRef(null);
    useEffect(()=>{
        const img = content.fileNames
        console.log(content)
        setImages(()=>img.map((e, index)=>{
            return {id: index, itemImageSrc: APIURL()+e, alt: '', thumbnailImageSrc: APIURL()+e}
        }))
    },[content])

    const itemTemplate = (item) => {
        return <img src={item.itemImageSrc} onClick={()=>{
            return  galleria.current.show()
        }} alt={item.alt} style={{ width: '100%', display: 'block', objectFit: 'cover', maxHeight: '300px', height: '300px', cursor: 'pointer' }} />;
    }

    const itemTemplateShow = (item) => {
        if (item){
            return <img src={item.itemImageSrc}  alt={item.alt} style={{ width: '100%', display: 'block', objectFit: 'cover', maxHeight: '500px' }} />;
        }
        return (<></>)
    }

    const thumbnailTemplate = (item) => {
        return <img src={item.thumbnailImageSrc}
                    alt={item.alt}
                    className="rounded-3 mt-0 mx-0 p-0"
                    width={"90px"} height={"70px"}
                    style={{ objectFit: 'cover'}} />;
    }
    return(
        <>
            <div className="w-100 mx-0 mt-0 mb-2 p-0 row bg-dark bg-opacity-75 rounded-3">
                <div className={`p-0 m-0 ${images.length===0 ? 'col-12' : 'col-7'}`}>
                    <div className={`card h-100 ms-0 ${images.length===0 ? 'me-0' : 'me-2'} text-print`}>
                        <div className="w-100 mt-0 mb-1 d-inline-flex justify-content-center">
                            <span>
                                {(new Date(content.date)).toLocaleDateString()}
                            </span>
                        </div>
                        <h4 className="text-concept text-center fw-bold">{content.titre}</h4>
                        <div className="card-body mb-0 overflow-x-hidden py-0 px-2" dangerouslySetInnerHTML={{__html: content.content}}/>
                    </div>
                </div>
                {images.length!==0 && (
                    <Galleria value={images}  numVisible={3}
                              item={itemTemplate} thumbnail={thumbnailTemplate} showThumbnails={images.length>1}
                              thumbnailsPosition={"bottom"} className="col-5 p-0" style={{maxWidth: '38vw'}}/>
                )}
            </div>

            {images.length!==0 && (
                <Galleria numVisible={4} ref={galleria} value={images}  style={{ maxWidth: '80%' }}
                          circular fullScreen  item={itemTemplateShow} showThumbnails={true} thumbnail={thumbnailTemplate} />
            )}
        </>
    )
}
export default SingleEvent