import {APIURL} from "../../../Model/APIURL";
import {Dropdown} from "react-bootstrap";
import React, {useCallback, useEffect, useMemo} from "react";
import {confirmDialog} from "primereact/confirmdialog";
import EtatEmployer from "../../../Model/EtatEmployer";
import {useNavigate} from "react-router-dom";
import {useUserStatus} from "./Hook/StatusUserWSContext";

export const DELAY = 50000;

const ViewListEmp = ({element,user, setAll, clickedPerson, getStatus})=>{
    const navigate=useNavigate()
    const supprimer=useCallback((idEmp)=>{
        confirmDialog({
            message: 'Voulez-vous supprimer cet utilisateur?',
            header: 'Confirmation',
            icon: 'fas fa-triangle-exclamation',
            acceptLabel: 'Valider',
            rejectLabel: 'Annuler',
            acceptClassName: 'p-button-sm p-button-primary py-1',
            rejectClassName: 'p-button-sm p-button-danger me-2 py-1',
            accept: ()=> {
                EtatEmployer.supprimerEmp(idEmp).then((res)=>{
                    setAll((prev)=>prev.filter((item)=>item.idEtat !==idEmp))
                }).catch((e)=>{
                    console.log(e)
                })
            },
            reject: ()=>{}
        });
    },[])
    const empId = element?.emp?.employe?.idEmp;
    const {addUserId} = useUserStatus()
    useEffect(() => {
        addUserId(empId)
    }, [empId]);

    const status = getStatus(empId);
    const userProfile = useMemo(()=>{
        return (
            <div className="width-max position-relative">
                {element?.emp.employe.profile ? (
                    <img
                        src={APIURL()+`${element?.emp.employe.profile}`}
                        alt=""
                        decoding={"async"}
                        className="border-dark-light rounded-circle mt-0 pt-0 z-0"
                        width={40} height={40}
                        style={{ objectFit: 'cover', width: '40px !important', height: '40px !important', overflow: 'hidden' }}
                    />
                ): (
                    <img
                        alt=""
                        className="border-dark-light rounded-circle mt-0 pt-0 z-0"
                        width={40} height={40}
                        style={{ objectFit: 'cover', width: '40px !important', height: '40px !important', overflow: 'hidden' }}
                    />
                )}
                <div className="position-absolute bottom-0 end-0 width-max z-2 d-flex align-bottom">
                    {status==="active" && (
                        <span className="rounded-circle border border-3 border-success bg-success-subtle spanRounded"/>
                    )}
                    {status==="inactive" && (
                        <span className="rounded-circle border border-3 border-warning bg-body spanRounded"/>
                    )}
                    {status==="disconnected" && (
                        <span className="rounded-circle border border-3 border-danger bg-danger bg-opacity-50 spanRounded"/>
                    )}
                    {status==="passive" && (
                        <span className="rounded-circle border border-3 border-dark bg-dark bg-opacity-50 spanRounded"/>
                    )}
                </div>
            </div>
        )
    },[element, status])
    return(
        <tr >
            <td className="align-middle">
                {userProfile}
            </td>
            <th className="align-middle" scope="row">{String(element.emp.employe.matricule).padStart(4, '0')}</th>
            <td className="align-middle">{element.emp.employe.nom}</td>
            <td className="align-middle">{element.emp.employe.prenom}</td>
            <td className="text-print text-nowrap px-0 py-0 align-middle">{element.emp.employe.tel}</td>
            <td className="text-print text-nowrap px-0 py-0 align-middle">{(new Date(element.emp.dateEntre)).toLocaleDateString()}</td>
            <td className="align-middle">{element.emp.employe.type.poste}</td>
            {user.type.idType===1 ? (<td>
                <Dropdown>
                    <Dropdown.Toggle
                        id={`dropdown-${element.idEtat}`}
                        as={"button"}
                        className="btn btn-sm border align-middle"
                    >
                        Option
                    </Dropdown.Toggle>
                    <Dropdown.Menu className=" mb-0 pb-0 rounded-bottom-2">
                        <Dropdown.Item className="text-warning" onClick={()=>{
                            const queryParams = new URLSearchParams({id: element.emp.employe.matricule});
                            navigate(`/employer/pointage/now?${queryParams.toString()}`)
                        }} ><i className="fa fa-calendar-check me-1"/> Voir Présence</Dropdown.Item>
                        <Dropdown.Item className="text-concept" onClick={()=>{
                            const queryParams = new URLSearchParams({id: element.emp.employe.matricule});
                            navigate(`/conge/planning?${queryParams.toString()}`)
                        }}><i className="fa fa-person-through-window me-1"/>Solde de congé</Dropdown.Item>
                        <Dropdown.Item className="color-param" onClick={()=>{clickedPerson(element)}}
                        ><i className="fa fa-user-edit me-1"/>Modifier ses Infos</Dropdown.Item>

                        <Dropdown.Item   onClick={()=>supprimer(element.idEtat)} className="bg-danger rounded-bottom-1 text-white"><i className="fa fa-trash me-1"/>Supprimer</Dropdown.Item>
                    </Dropdown.Menu>
                </Dropdown>
            </td>): ''}
        </tr>
    )
}

export default ViewListEmp