import React, {useCallback, useEffect, useState} from "react";
import {Col, Form, InputGroup, Modal, Row} from "react-bootstrap";
import {userProfile} from "./PersIndView";
import Pagination from "../../Main/Utilitaire/Pagination";
import {formatNumber} from "./ViewSalaireBrute";
import {SalaireBase} from "../../../Model/Paie/SalaireBase";
import {normalizeString} from "../../Rendu/Hebdo";
import {formatDateToInputValue} from "../../InfoPersonel";
import {getNextDateMonth} from "../Paramettre";

const ViewPret = ({show, hide, currentInterval})=>{
    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [post, setPost] = useState('');
    const [filtered, setFiltered] = useState([]);
    const [allData, setAllData] = useState([]);
    useEffect(() => {
        SalaireBase.getAllPret().then((resp)=>{
            setAllData(resp)
        }).catch(()=>{})
    }, []);

    const [paginate, setPaginate] = useState(1);

    const [showModif, setShowModif] = useState(false);
    const [mask, setMask] = useState(false);
    useEffect(() => {
        if (!show){
            setMask(false)
            return
        }
        if (showModif){
            setMask(false)
        }else{
            setMask(true)
        }
    }, [show,showModif]);

    useEffect(() => {
        let data = allData;
        if (matricule) {
            data = allData.filter(({emp}) =>{
                if (emp.matricule){
                    return emp.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter(({emp}) =>
                emp.nom.toLowerCase().includes(nom.toLowerCase()) ||
                emp.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        if (post){
            data = data.filter(({emp})=>normalizeString(emp.type.poste.toLowerCase()).includes(normalizeString(post.toLowerCase())))
        }
        setFiltered(data)
    }, [allData, matricule, nom, post]);


    const [formElement, setFormElement] = useState({
        valeur: 0,
        emp: null,
        date: new Date(),
        isValid: false,
        idPret: -32132454654321
    });
    const clickedTab = useCallback((element) => {
        setShowModif(true)
        setFormElement(()=>({
            valeur: element.valeur,
            emp: element.emp,
            isValid: false,
            date: element.dateInsert ? new Date(element.dateInsert) : new Date(),
            idPret: element.idPret
        }))
    }, [formElement, showModif]);

    const [erreurCheck, setErreurCheck] = useState(false);
    useEffect(() => {
        if (formElement.isValid){
            setErreurCheck(false)
        }
    }, [formElement.isValid]);

    const isCurrentMonth = useCallback((date) => {
        if (!date) return false;
        const inputDate = new Date(date);
        const dateMonthInterval = getNextDateMonth(currentInterval);
        return inputDate >= new Date(dateMonthInterval.firstDay) &&
            inputDate <= new Date(dateMonthInterval.lastDay);

    }, [currentInterval]);


    const submit = useCallback(()=>{
        if (!formElement.isValid){
            setErreurCheck(true)
            return
        }
        if (!isCurrentMonth(formElement.date)){
            return;
        }
        SalaireBase.addPret(formElement.idPret, formElement.emp, formElement.valeur, formElement.date)
            .then((ac)=>{
                setAllData((prev)=>prev.map(e=>e.idPret ===formElement.idPret ? {...e,valeur: formElement.valeur, idPret : ac.idPret} : e))
            }).catch(()=>{})
            .finally(()=>{
                setShowModif(false)
            })
    },[formElement])

    return(
        <>
            <Modal
                show={mask}
                onHide={hide}
                keyboard={false}
                backdrop="static"
                autoFocus={true}
                dialogClassName="modal-dialog-centered modal-W position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center modal-90w"
            >
                <Modal.Header className="position-relative py-2">
                    <strong>Rembourser Prêt</strong>
                    <div onClick={()=>hide()} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="bg-dark bg-opacity-75">
                    <div className="card w-100 mb-2">
                        <div className="card-body pt-1 pb-1">
                            <h3 className="text-center">Liste des Salariés</h3>
                            <div className="row m-0 p-0">
                                <div className="col-3">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                                        <Form.Control
                                            placeholder="matricule"
                                            aria-label="matricule"
                                            aria-describedby="basic-addon1"
                                            type="search"
                                            value={matricule}
                                            onChange={(event)=>{
                                                setMatricule(event.target.value.replace(/\D/g, ''))
                                            }}
                                        />
                                    </InputGroup>
                                </div>
                                <div className="col-5">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                                        <Form.Control
                                            placeholder="nom ou prénom"
                                            aria-label="nom"
                                            aria-describedby="nom"
                                            type="search"
                                            value={nom}
                                            onChange={(event) => setNom(event.target.value)}
                                        />
                                    </InputGroup>
                                </div>
                                <div className="col-4">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">Poste</InputGroup.Text>
                                        <Form.Control
                                            placeholder="nom ou prénom"
                                            aria-label="nom"
                                            aria-describedby="nom"
                                            type="search"
                                            value={post}
                                            onChange={(event) => setPost(event.target.value)}
                                        />
                                    </InputGroup>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="m-0 w-100 rounded-3 bg-white">
                        <div className="rounded-3 p-1 m-0 w-100">
                            <table className="table mb-0 table-striped table-hover">
                                <thead>
                                <tr className="text-center">
                                    <th scope="col"/>
                                    <th scope="col">M°</th>
                                    <th scope="col">Nom</th>
                                    <th scope="col">Prenom</th>
                                    <th scope="col">Poste</th>
                                    <th scope="col">Prêt</th>
                                </tr>
                                </thead>
                                <tbody>
                                {filtered.slice((paginate-1)*10,(paginate)*10).map((element)=>(
                                    <tr onClick={()=>clickedTab(element)} key={element.idPret} className="cursor-pointer" >
                                        <td>
                                            {userProfile(element.emp)}
                                        </td>
                                        <th scope="row">{String(element.emp.matricule).padStart(4, '0')}</th>
                                        <td>{element.emp.nom}</td>
                                        <td>{element.emp.prenom}</td>
                                        <td>{element.emp.type.poste}</td>
                                        <td className="text-center h4-Edit fw-bold">{formatNumber(element.valeur)}</td>
                                    </tr>
                                ))}
                                </tbody>

                            </table>
                        </div>
                        <div className="d-flex justify-content-end w-100 m-0 p-2">
                            <Pagination length={filtered.length % 10 === 0 ? filtered.length / 10 : Math.floor(filtered.length / 10) + 1} active={paginate} setActive={setPaginate}/>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            {showModif && (
                <>
                    <Modal
                        show={showModif}
                        onHide={()=>setShowModif(false)}
                        keyboard={false}
                        backdrop="static"
                        autoFocus={true}
                        dialogClassName="modal-dialog-centered  position-relative d-flex justify-content-center align-items-center"
                        contentClassName="d-flex justify-content-center modal-70w bg-green"
                    >
                        <Modal.Header className="position-relative">
                            <strong className="text-capitalize">{formElement && formElement.emp.nom + " "+ formElement.emp.prenom}</strong>
                            <div onClick={()=>setShowModif(false)} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                                <i className="fa-solid fa-close  text-dark-emphasis"/>
                            </div>
                        </Modal.Header>
                        <Modal.Body className="pt-1">
                            <div className="row mt-0 mx-0 mb-3 p-0 w-100">
                                <h4 className="text-center mb-3 text-primary">{formElement && formElement.idPret>0 ? "Modifier le pret": "Ajout pret à rembourser"}</h4>
                                <hr className="w-75 mx-auto text-primary"/>
                                <Form.Group className="p-0 mt-0 mx-0 mb-2" as={Col} md="12" controlId="pret">
                                    <Form.Label className="fw-bold">Pret</Form.Label>
                                    <div className="position-relative">
                                        <Form.Control
                                            type="text"
                                            className="bg-transparent border-dark-light"
                                            autoFocus={true}
                                            value={formatNumber(formElement.valeur)}
                                            onChange={(e) =>{
                                                const val = e.target.value.replace(/\D/g, '')
                                                setFormElement((prev)=>({...prev, valeur: parseInt(val)}))
                                            }}
                                            placeholder="Valeur"
                                            required
                                        />
                                        <pre className="position-absolute fw-bold top-50 mb-0 mt-0 end-0 translate-middle-y me-3 bg-warning ">
                                            MGA
                                        </pre>
                                    </div>
                                </Form.Group>

                                <Form.Group className="p-0 mt-0 mx-0 mb-2" as={Col} md="12" controlId="date">
                                    <Form.Label className="fw-bold">Date</Form.Label>
                                    <Form.Control
                                        type="date"
                                        className="bg-transparent border-dark-light"
                                        isInvalid={!isCurrentMonth(formElement.date)}
                                        value={formatDateToInputValue(formElement.date)}
                                        onChange={(e) => setFormElement((prev)=>({...prev, date: new Date(e.target.value)}))}
                                        placeholder="description"
                                        required
                                    />
                                </Form.Group>

                                <Form.Check
                                    type="checkbox"
                                    className="bg-transparent"
                                    label="Je valide mon choix"
                                    id="validation"
                                    value={formElement.isValid}
                                    onChange={(e) => setFormElement((prev)=>({...prev, isValid: !prev.isValid}))}
                                    isInvalid={erreurCheck}
                                />

                            </div>
                            <Row>
                                <Col md={6}>
                                    <button type="button" onClick={()=>setShowModif(false)} className="btn btn-sm bg-aris text-white w-100">Annuler</button>
                                </Col>
                                <Col md={6}>
                                    <button type="button" onClick={submit} className="btn btn-sm bg-blue text-white w-100">Valider</button>
                                </Col>
                            </Row>
                        </Modal.Body>
                    </Modal>
                </>
            )}
        </>
    )
}
export default ViewPret