import React, {useCallback, useContext, useEffect, useMemo, useState} from "react";
import Taches from "./Taches";
import {addDays} from 'date-fns'
import {UserContext} from "../Main/Utilitaire/UserProvider";
import RenduDAO from "../../Model/RenduDAO";
import AddFile from "./AddFile";


const Quotidien = ({dateMonday,dateFriday,idUtilisateur}) => {

    const getWeekDates = useCallback(() => {
        const today = new Date();
        const dayOfWeek = today.getDay();

        let monday = new Date(today);
        let friday = new Date(today);

        if (dateMonday instanceof Date && dateFriday instanceof Date) {
            if (dateMonday.toDateString() !== dateFriday.toDateString()) {
                monday = new Date(dateMonday);
                friday = new Date(dateFriday)
            }
        } else {
            monday.setDate(today.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
            friday = new Date(monday);
            friday.setDate(monday.getDate() + 4);
        }

        const optionsFull = { day: "numeric", month: "long", year: "numeric" };
        const optionsDay = { day: "numeric" };

        return {
            monday: monday.toLocaleDateString("fr-FR", optionsDay),
            friday: friday.toLocaleDateString("fr-FR", optionsFull),
        };
    }, []);

    const { monday, friday } = getWeekDates();

    const date=useMemo(()=>{

        if (dateMonday instanceof Date ) {
            return new Date(dateMonday)
        }
        const today = new Date();
        const dayOfWeek = today.getDay();
        const mon = new Date(today);

        mon.setDate(today.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));

        return mon
    },[])

    const { user: userContext }=useContext(UserContext)
    const idViewer=idUtilisateur ? idUtilisateur.idEmp : userContext?.idEmp;
    const [listAll,setListAll]=useState([])

    useEffect(()=>{
        RenduDAO.getWeekRender(idViewer, date, addDays(new Date(date),4)).then((res)=>{
            setListAll(res)
        }).catch((e)=>{
            console.log(e.message)
        })
    },[idViewer])
    const isSameDate = useCallback((date1, date2) => {
        return date1.getFullYear() === date2.getFullYear() &&
            date1.getMonth() === date2.getMonth() &&
            date1.getDate() === date2.getDate();
    },[])

    const isDateBetween = (date, startDate, endDate) => {
        if (!(date instanceof Date) || !(startDate instanceof Date) || !(endDate instanceof Date)) {
            return true
        }

        return date >= startDate && date<= endDate;
    };

    return(
        <>
            <div className="card mb-3">
                <div className="card-header position-relative">
                    <h3 className="text-center">Rapport du {monday} au {friday}</h3>
                    {idUtilisateur && idUtilisateur?.idEmp !== userContext?.idEmp ? (
                        <></>
                    ) :  !isDateBetween(new Date(), dateMonday, dateFriday) ? (<></>) :   (
                        <div className="position-absolute end-3 h-100 top-0 px-3 d-flex justify-content-center align-items-center">
                            <AddFile user={ userContext} dates={[monday,friday]}/>
                        </div>
                    )}
                </div>
                <div className="card-body" >
                    <div className="table-responsive">
                        <table className="table align-middle">
                            <thead>
                                <tr>
                                    <th scope="col">Jour</th>
                                    <th scope="col">Taches</th>
                                    <th scope="col">Commentaire</th>
                                    <th scope="col" className="text-end">Status</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr className="border-0 border-bottom border-3">
                                    <td className="text-center" style={{ width: '12%' }}>Lundi <strong>{monday}</strong></td>
                                    <td colSpan="3">
                                        <Taches id={idViewer} setAll={setListAll} date={addDays(new Date(date),0)}  rendu={listAll.filter((e)=>isSameDate(new Date(e.dateDebut),addDays(new Date(date),0)))} />
                                    </td>
                                </tr>
                                <tr className="border-0 border-bottom border-3">
                                    <td className="text-center">Mardi <strong>{parseInt(monday)+1}</strong></td>
                                    <td colSpan="3">
                                        <Taches id={idViewer} setAll={setListAll} date={addDays(new Date(date),1)} rendu={listAll.filter((e)=>isSameDate(new Date(e.dateDebut),addDays(new Date(date),1)))}/>
                                    </td>
                                </tr>
                                <tr className="border-0 border-bottom border-3">
                                    <td className="text-center">Mercredi <strong>{parseInt(monday)+2}</strong></td>
                                    <td colSpan="3">
                                        <Taches id={idViewer} setAll={setListAll} date={addDays(new Date(date),2)} rendu={listAll.filter((e)=>isSameDate(new Date(e.dateDebut),addDays(new Date(date),2)))}/>
                                    </td>
                                </tr>
                                <tr  className="border-0 border-bottom border-3">
                                    <td className="text-center">Jeudi <strong>{parseInt(monday)+3}</strong></td>
                                    <td colSpan="3">
                                        <Taches id={idViewer} setAll={setListAll} date={addDays(new Date(date),3)} rendu={listAll.filter((e)=>isSameDate(new Date(e.dateDebut),addDays(new Date(date),3)))}/>
                                    </td>
                                </tr>
                                <tr  className="border-0 border-bottom border-3">
                                    <td className="text-center">Vendredi <strong>{parseInt(monday)+4}</strong></td>
                                    <td colSpan="3">
                                        <Taches id={idViewer} setAll={setListAll} date={addDays(new Date(date),4)} rendu={listAll.filter((e)=>isSameDate(new Date(e.dateDebut),addDays(new Date(date),4)))}/>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </>
    )
}

export default Quotidien