import { createStore } from 'redux';

const initialState = {
    etat: 1
};

function etatReducer(state = initialState, action) {
    switch (action.type) {
        case "SET_ETAT":
            return { etat: action.payload };
        default:
            return state;
    }
}

const LinkState = createStore(etatReducer);

export default LinkState;
