import React, { useContext, useEffect} from "react";
import {Routes} from "../Route/Route";
import {UserContext} from "../Component/Main/Utilitaire/UserProvider";
import { useNavigate} from "react-router-dom";

const RelLink = ({nextValue, currentValue,setNonValider =()=>{}})=>{
    const { user} = useContext(UserContext);
    const navigate = useNavigate();

    const isNavigationAllowed = () => {
        if (user){
            const nexElement = Routes.find((element)=>element.id ===nextValue)
            if (nexElement){
                if (!nexElement.allUser && user?.type.idType !==1){
                    return false
                }
            }
        }
        return true
    }

    useEffect(() => {
        if (!isNavigationAllowed()) {
            alert("⛔ Vous n'avez pas l'autorisation d'accéder à cette page !");
            setNonValider(currentValue)
            navigate(-1, { replace: true })
        }else{
            setNonValider(nextValue)
        }
    }, [nextValue,user]);

    return null
}
export default React.memo(RelLink)