import React, {useContext, useEffect} from "react";
import useWebSocket from "./useWebSocket";
import {UserContext} from "../Component/Main/Utilitaire/UserProvider";
import { useNavigate } from "react-router-dom";


const ReloadAll = ({setActive = ()=>{}})=>{
    const { user, setIsModif} = useContext(UserContext);
    const navigate=useNavigate()
    const { body } = useWebSocket(user ? `/notif/modification/${user.idEmp}` : null)

    useEffect(() => {
        if (body) {
            setIsModif(prev => !prev);
            navigate("/accueil");
            setActive(1)
        }
    }, [body]);

    return null
}

export default React.memo(ReloadAll)