import React, {useEffect, useState} from "react";
import {Col, Form, Row} from "react-bootstrap";
import Allinfo from "../../../Model/Allinfo";
import {allBanque} from "../../InfoBanque";
import {handleTelChange} from "../Salarier/VoirInfo";

const ModifRh = ({setActif,object,changeValueUser,isModifier, close}) => {

    const [numCanps,setCnaps]=useState('')
    const [banque,setBanque]=useState(null)
    const [rib,setRib]=useState('')
    const [contact,setContact]=useState('')
    const [telContact,setTelContact]=useState('')
    useEffect(()=>{
        if (object){
            setCnaps(object.numCanps)
            setBanque(object.banque)
            setRib(object.rib)
            setContact(object.contact)
            setTelContact(object.telContact)
        }
    },[object])


    const changeValue = () => {
        changeValueUser({
            ...object,
            numCanps:numCanps,
            banque:banque,
            rib:rib,
            contact:contact,
            telContact:telContact
        })
    }
    const [navigate,setNavigate]=useState(0)
    const [validationErrors, setValidationErrors] = useState({
        validatedNom: true,
        validatedTel: true,
    });
    const handleSubmit = (event) => {
        event.preventDefault();

        const errors = {
            validatedNom: contact.trim().length>0,
            validatedTel: telContact.length >= 17,
        };

        setValidationErrors(errors);
        const isValid = Object.values(errors).every(Boolean);

        if (!isValid) {
            return;
        }

        if (navigate===1){
            Allinfo.modifEmployee({...object,
                numCanps:numCanps,
                banque:banque,
                rib:rib,
                contact:contact,
                telContact:telContact
            },object.mdp).finally(()=>{
                close()
                isModifier((prev)=>!prev)
            })
        }else if (navigate===2){
            setActif(3)
            changeValue()
        }else{
            return
        }
    };

    return (
        <>
            <Form  autoComplete={"off"} onSubmit={handleSubmit}>
                <Row className="mb-3 border-bottom">
                    <Form.Group className="mb-3" as={Col} md="4" controlId="cnaps">
                        <Form.Label className="fw-bold small text-light-emphasis">Numeros CNAPS</Form.Label>
                        <Form.Control
                            type="text"
                            className="bg-transparent border-dark-light"
                            size={"sm"}
                            value={numCanps}
                            onChange={(e)=>{
                                let value=e.target.value
                                value = value.replace(/\D/g, '')
                                setCnaps(value.replace(/(.{4})/g, '$1 ').trim())
                            }}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="4" controlId="banque">
                        <Form.Label className="fw-bold small text-light-emphasis">Banque</Form.Label>
                        <Form.Select size={"sm"} value={banque?.id} onChange={(html)=>setBanque(allBanque.find((element)=>element.id===parseInt(html.target.value,10)))} className="bg-transparent border-dark-light" required>
                            {allBanque.map((e)=>(
                                <option key={e.id} className="text-dark" value={e.id}>{e.value}</option>
                            ))}
                        </Form.Select>
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="4" controlId="rib">
                        <Form.Label className="fw-bold small text-light-emphasis">Numeros RIB</Form.Label>
                        <Form.Control
                            type="text"
                            className="bg-transparent border-dark-light"
                            value={rib}
                            size={"sm"}
                            onChange={(e)=>{
                                let value=e.target.value
                                value = value.replace(/\D/g, '')
                                setRib(value.replace(/(.{4})/g, '$1 ').trim())
                            }}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="6" controlId="nom">
                        <Form.Label className="fw-bold small text-light-emphasis">Nom (Contact en cas d'urgence)</Form.Label>
                        <Form.Control
                            required
                            size={"sm"}
                            type="text"
                            className="bg-transparent border-dark-light"
                            value={contact}
                            isInvalid={!validationErrors.validatedNom}
                            onChange={(e)=>setContact(e.target.value)}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="6" controlId="tel">
                        <Form.Label className="fw-bold small text-light-emphasis">Tél (Contact en cas d'urgence)</Form.Label>
                        <Form.Control
                            size={"sm"}
                            required
                            type="text"
                            className="bg-transparent border-dark-light"
                            value={telContact}
                            isInvalid={!validationErrors.validatedTel}
                            onChange={(e)=>{setTelContact(handleTelChange(e.target.value))}}
                        />
                    </Form.Group>
                </Row>
                <Row className="mb-2">
                    <Col md={4}>
                        <button type="button"  onClick={()=>setActif(1)} className="btn btn-warning btn-sm text-white w-100">Précedent</button>
                    </Col>
                    <Col md={4}>
                        <button type="submit" onClick={()=>setNavigate(1)} className="btn btn-sm bg-blue text-white w-100">Terminé</button>
                    </Col>
                    <Col md={4}>
                        <button type="submit" onClick={()=>setNavigate(2)} className="btn btn-info btn-sm text-white w-100">Suivant</button>
                    </Col>
                </Row>
            </Form>
        </>
    )
}

export default ModifRh