import React, {forwardRef, useCallback} from "react";
import icon from '../../img/logoA.png'
import {formatNumber, formatNumberDouble} from "./Parameter/ViewSalaireBrute";
import {apaye} from "./ValidationPaie";

const FicheDePaie = forwardRef (({element},ref)=>{
    const printInfo = useCallback(
        (refer, id) => {
            if (element) {
                return (
                    <tr>
                        <th scope="row" className="text-center align-middle">{id}</th>
                        <td>{element[refer].label}</td>
                        <td className="text-print">{element[refer].taux === 0 ? '' : formatNumber(element[refer].taux)}</td>
                        <td className="text-print">{element[refer].base===0 ? '' : formatNumberDouble(element[refer].base)}</td>
                        <td className="text-print">{element[refer].apaye===0 ? '' : formatNumberDouble(element[refer].apaye)}</td>
                        <td className="text-print">{element[refer].adeduire===0 ? '' : formatNumberDouble(element[refer].adeduire)}</td>
                    </tr>
                )
            }
        },
        [element]
    );

    const totalIrsa = useCallback(()=>{
        if (element){
            let a = 0
            element.irsa.map((irsa)=>{
                a+=irsa.adeduire
            })
            return a
        }
        return 0
    },[element])
    const totalAdeduire = useCallback(
        () => {
            if (element){
                let a = 0
                element.irsa.map((irsa)=>{
                    a+=irsa.adeduire
                })
                a+=(element.acompte.adeduire+element.pret.adeduire+element.ostie.adeduire+element.cnaps.adeduire)
                return a
            }
            return 0
        },
        [element],
    );
    const totalApaye = useCallback(
        () => {
            if (element) {
                return element?.salaireBase.apaye + element?.indemnite.apaye + element?.prime.apaye
            }
        },
        [element],
    );

    return(
        <>
            <div ref={ref} className="position-relative" style={{ width: "210mm", height: "297mm",  }}>
                <div className="position-absolute top-0 z-0 m-0 p-0 bottom-0 w-100 start-0 end-0 bg-interface h-100"/>
                <div className="m-0 px-2 py-0 w-100 position-relative z-3">
                    <div className="mt-1 mx-0 p-0 mb-1 w-100 d-flex border-bottom justify-content-center">
                        <ul className="list-group list-group-flush m-0 p-0 bg-transparent gap-0">
                            <li className="list-group-item m-0 p-0 gap-0 bg-transparent border-0 text-center">
                                <img src={icon} className="m" width="35" alt="icon"/>
                            </li>
                            <li className="list-group-item m-0 p-0 gap-0 bg-transparent border-0 text-center">
                                <h4 className="text-uppercase fw-bolder h4-Edit mb-0 text-center text-white pt-1">Bulletin de paie du</h4>
                            </li>
                            <li className="list-group-item m-0 p-0 gap-0 bg-transparent border-0 text-center">
                                <span className="fw-bolder" style={{fontFamily: 'monospace', fontSize: '1rem', textWrap: 'nowrap'}}>{(new Date(element?.dateDebut)).toLocaleDateString('fr-FR',{day: 'numeric', month: 'numeric', year: 'numeric'})}</span>
                                <span className="mx-1 fw-bold small">au</span>
                                <span className="fw-bold" style={{fontFamily: 'monospace', fontSize: '1rem', textWrap: 'nowrap'}}>{(new Date(element?.dateFin)).toLocaleDateString('fr-FR',{day: 'numeric', month: 'numeric', year: 'numeric'})}</span>
                            </li>
                        </ul>
                    </div>
                    <div className="w-100 mx-0 mb-2 mt-1 row p-0">
                        <div className="text-center border rounded-3 me-2" style={{flex: "0 0 auto", width: 'calc(50% - 0.25rem)'}}>
                            <div className="w-100 mb-1 d-inline-flex justify-content-center">
                                <span className="display-6 fw-bolder text-aris me-2">Aris</span>
                                <span className="display-6 fw-bolder text-concept">Concept</span>
                            </div>
                            <div className="w-100 text-break">
                                <span className="text-primary">Traitement de données informatique</span>
                            </div>
                            <ul className="list-group list-group-flush m-0 p-0 bg-transparent">
                                <li className="list-group-item m-0 pb-1  pt-0 px-0 bg-transparent border-0">Lot II T 104 A Iavoloha Ambohibao</li>
                                <li className="list-group-item m-0 pb-1 pt-0 px-0 bg-transparent border-0">Commune Bongatsara</li>
                                <li className="list-group-item m-0 pb-0 pt-0 px-0 bg-transparent border-0">Antananarivo 102 - MADAGASCAR</li>
                            </ul>
                        </div>
                        <div className="text-dark text-center border rounded-3  d-flex flex-column justify-content-center align-items-center" style={{flex: "0 0 auto", width: 'calc(50% - 0.25rem)'}}>
                            <div className="w-100 mb-1 mt-1">
                                <h6 className="h4-Edit fw-bolder text-capitalize text-center">{element?.emp.employe.nom}</h6>
                                <h6 className="text-print fw-bolder text-capitalize text-center text-break fs-6">{element?.emp.employe.prenom}</h6>
                            </div>
                            <ul className="list-group list-group-flush m-0 p-0 bg-transparent">
                                <li className="list-group-item m-0 pb-1  pt-0 px-0 bg-transparent text-center border-0">{element?.emp.employe.adresse}</li>
                            </ul>
                        </div>
                    </div>
                    <div className="row m-0 p-0 w-100 border-bottom pb-1">
                        <div className="col-4 d-flex flex-column align-items-center justify-content-center ps-0 pe-1 pb-0" style={{letterSpacing: '0.055rem'}}>
                            <span className="fw-bolder d-block small text-white mb-2 text-break">Date paiement: {element?.datePaiement ? (new Date(element?.datePaiement)).toLocaleDateString('fr-FR', {day: 'numeric', month: 'long', year: 'numeric'}): '----'}</span>
                            <span className="fw-bolder text-white mb-2 small text-break text-center">Mode de paiement : {element?.emp.banque.id ===6 ? 'Espèce' : element?.emp.banque.value}</span>
                        </div>

                        <div className="col-4 p-0 m-0">
                            <table className="table w-100 m-0 p-0 rounded-3 table-sm-custom">
                                <tbody>
                                <tr>
                                    <th scope="row">N° CNAPS :</th>
                                    <td colSpan="2">{element?.emp.numCnaps.split(" ").join("")}</td>
                                </tr>
                                <tr>
                                    <th scope="row">Embauche :</th>
                                    <td colSpan="2">{(new Date(element?.emp.dateEntre)).toLocaleDateString('fr-FR', {day: 'numeric', month: 'numeric', year: 'numeric'})}</td>
                                </tr>
                                <tr>
                                    <th scope="row">Congé :</th>
                                    <td>{element?.totalConge} jour(s)</td>
                                </tr>
                                <tr>
                                    <th scope="row">Nb Enfant :</th>
                                    <td colSpan="2" className="small">{element?.emp.employe.enfant}</td>
                                </tr>
                                </tbody>
                            </table>

                        </div>
                        <div className="col-4 d-flex flex-column align-items-center justify-content-center ps-1 pe-0">
                            <table className="table w-100 m-0 p-0 rounded-3 table-sm table-sm-custom">
                                <tbody>
                                <tr className="bg-transparent ">
                                    <th scope="row">Matricule :</th>
                                    <td colSpan="2" className="small">{element?.emp.employe.matricule}</td>
                                </tr>
                                <tr>
                                    <th scope="row">CIN :</th>
                                    <td colSpan="2" className="small">{element?.emp.employe.cin.split(" ").join('')}</td>
                                </tr>
                                <tr>
                                    <th scope="row">Fonction :</th>
                                    <td colSpan="2">{element?.emp.employe.type.poste}</td>
                                </tr>
                                <tr>
                                    <th scope="row">Nb Absent :</th>
                                    <td colSpan="2">{element?.nbAbsence} jour(s)</td>
                                </tr>
                                </tbody>
                            </table>
                        </div>
                    </div>
                    <div className="row mx-0 mt-2 p-0 ">
                        <div className="w-100 p-0 mx-0 mt-1">
                            <table className="table table-bordered table-sm table-warning table-sm-custom">
                                <thead>
                                <tr className="text-center">
                                    <th className="w-8 text-center align-middle">Code</th>
                                    <th className="w-30 text-center align-middle">Libellé</th>
                                    <th className="w-10 text-center align-middle">Nb ou taux</th>
                                    <th className="w-20 text-center align-middle">Base</th>
                                    <th className="w-15 text-center align-middle">À PAYER</th>
                                    <th className="w-15 text-center align-middle">À DÉDUIRE</th>
                                </tr>
                                </thead>
                                <tbody>

                                <tr className="table-success">
                                    <th scope="row" colSpan={6} className="text-center">Rénumération brute</th>
                                </tr>
                                {printInfo("salaireBase",1)}
                                {printInfo("indemnite",2)}
                                {printInfo("prime",3)}

                                <tr>
                                    <th scope="row" colSpan={4} className="text-center">Total Rénumération : </th>
                                    <th scope="row" colSpan={1} className="text-center text-print">{formatNumberDouble(totalApaye())}</th>
                                    <th scope="row" colSpan={1} className="text-center"/>
                                </tr>
                                <tr className="table-success">
                                    <th scope="row" colSpan={6} className="text-center">Cotisations</th>
                                </tr>
                                {printInfo("cnaps",3)}
                                {printInfo("ostie",3)}
                                <tr>
                                    <th scope="row" colSpan={4} className="text-center">Total Cotisations : </th>
                                    <th scope="row" colSpan={1} className="text-center"/>
                                    <th scope="row" colSpan={1} className="text-center text-print">{formatNumberDouble(element?.ostie.adeduire+element?.cnaps.adeduire)}</th>
                                </tr>
                                <tr className="table-success">
                                    <th scope="row" colSpan={6} className="text-center">Retenu</th>
                                </tr>
                                {element?.irsa.length > 0 &&(
                                    <tr>
                                        <th scope="row" className="text-center align-middle">6</th>
                                        <td colSpan="5" className="p-0 m-0">
                                            <table className="table m-0 table-warning table-borderless w-100 p-0">
                                                <tbody>
                                                <tr>
                                                    <td className="small w-32  fst-italic"><span className="h4-Edit fw-bold">IRSA</span></td>
                                                    <td className="w-12 border border-warning border-top-0 text-print"></td>
                                                    <td className="w-22 border border-warning border-top-0 text-print fw-bold">{formatNumberDouble(-(element?.ostie.adeduire+element?.cnaps.adeduire)+totalApaye())}</td>
                                                    <td className="w-17 border border-warning border-top-0"></td>
                                                    <td className="w-17 border border-warning border-top-0 text-print border-end-0"></td>
                                                </tr>
                                                {element?.irsa.map((e,index)=>(
                                                    <tr key={index}>
                                                        <td className="small w-32 border border-warning border-start-0 border-top-0 fst-italic"><i className="fa fa-dot-circle text-very-small text-aris ms-1"/>{e.label}</td>
                                                        <td className="w-12 border border-warning border-top-0 text-print">{formatNumberDouble(e.taux)}</td>
                                                        <td className="w-22 border border-warning border-top-0 text-print">{formatNumberDouble(e.base)}</td>
                                                        <td className="w-17 border border-warning border-top-0"></td>
                                                        <td className="w-17 border border-warning border-top-0 text-print border-end-0">{formatNumberDouble(e.adeduire)}</td>
                                                    </tr>
                                                ))}
                                                <tr>
                                                    <td colSpan={4} className="fw-bold w-32 border border-warning border-start-0 border-bottom-0 fst-italic h4-Edit">Total IRSA</td>
                                                    <td className="w-17 border border-warning border-bottom-0 text-print border-end-0 fw-bold">{formatNumberDouble(totalIrsa())}</td>
                                                </tr>
                                                </tbody>
                                            </table>
                                        </td>
                                    </tr>
                                )}

                                {printInfo("acompte",7)}
                                {printInfo("pret",8)}
                                <tr>
                                    <th scope="row" colSpan={4} className="text-center">Total Retenu : </th>
                                    <th scope="row" colSpan={1} className="text-center"/>
                                    <th scope="row" colSpan={1} className="text-center text-print">{formatNumberDouble(totalAdeduire() - (element?.ostie.adeduire+element?.cnaps.adeduire))}</th>
                                </tr>
                                <tr className="table-info">
                                    <th scope="row" colSpan={4} className="text-center">Total</th>
                                    <th scope="row" colSpan={1} className="text-center text-print">{formatNumberDouble(totalApaye())}</th>
                                    <th scope="row" colSpan={1} className="text-center text-print">{formatNumberDouble(totalAdeduire())}</th>
                                </tr>
                                <tr className="table-primary">
                                    <th scope="row" colSpan={4} className="text-center text-success">Total NET À PAYER : </th>
                                    <th scope="row" colSpan={2} className="text-center"><pre className="fs-5 h-100 w-100 overflow-y-hidden m-0 p-0 text-print">{formatNumberDouble(apaye(element))}</pre></th>
                                </tr>
                                </tbody>
                            </table>
                        </div>

                        <div className="w-100 mx-0 mt-1 border border-danger p-2 rounded-3">
                            <div className="text-white fs-6 text-center">
                                Pour vous aider à faire valoir vos droits, conservez ce bulletin de paie sans limitation de durée.
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </>
    )
})

export default FicheDePaie