import React, {useCallback, useState} from "react";
import {Card, Placeholder} from "react-bootstrap";
import ShowNews from "./ShowNews";

const Optimisation=({pol,load})=>{
    const [show,setShow]=useState(false)
    const close=useCallback(()=>{
        setShow(false)
    },[])
    const [objectSet,setObjectSet]=useState(null)
    const clicked=useCallback((image,titre,desc,date)=>{
        setShow(true)
        setObjectSet({image,titre,desc,date})
    },[])
    return(
        <>
            <div className="row w-100 m-0 p-0">
                {load ? (
                    <>
                        <div className="col-6 ps-0 pe-1">
                            <Card  className="mb-2 mt-0 mx-0 p-0 border-0">
                                <div className="row w-100 m-0 p-0">
                                    <Placeholder as={"div"} className="col-7 rounded-start-2 pla" style={{
                                        minHeight: '250px',
                                        backgroundSize: 'cover',
                                        backgroundPosition: 'center',
                                    }}>
                                    </Placeholder>
                                    <div className="col-5">
                                        <Placeholder as={Card.Title} className="mb-3" animation="glow">
                                            <Placeholder xs={8} />
                                        </Placeholder>
                                        <Placeholder as={Card.Text} className="mt-4" animation="glow">
                                            <Placeholder xs={7} /> <Placeholder xs={4} /> <Placeholder xs={4} />{' '}
                                            <Placeholder xs={6} /> <Placeholder xs={8} />
                                        </Placeholder>
                                    </div>
                                </div>
                            </Card>
                        </div>
                        <div className="col-6 pe-0 ps-1">
                            <Card  className="mb-2 mt-0 mx-0 p-0 border-0">
                                <div className="row w-100 m-0 p-0">
                                    <Placeholder as={"div"} className="col-7 rounded-start-2 pla" style={{
                                        minHeight: '250px',
                                        backgroundSize: 'cover',
                                        backgroundPosition: 'center',
                                    }}>
                                    </Placeholder>
                                    <div className="col-5">
                                        <Placeholder as={Card.Title} className="mb-3" animation="glow">
                                            <Placeholder xs={8} />
                                        </Placeholder>
                                        <Placeholder as={Card.Text} className="mt-4" animation="glow">
                                            <Placeholder xs={7} /> <Placeholder xs={4} /> <Placeholder xs={4} />{' '}
                                            <Placeholder xs={6} /> <Placeholder xs={8} />
                                        </Placeholder>
                                    </div>
                                </div>
                            </Card>
                        </div>
                        <div className="col-6 ps-0 pe-1">
                            <Card  className="mb-2 mt-0 mx-0 p-0 border-0">
                                <div className="row w-100 m-0 p-0">
                                    <Placeholder as={"div"} className="col-7 rounded-start-2 pla" style={{
                                        minHeight: '250px',
                                        backgroundSize: 'cover',
                                        backgroundPosition: 'center',
                                    }}>
                                    </Placeholder>
                                    <div className="col-5">
                                        <Placeholder as={Card.Title} className="mb-3" animation="glow">
                                            <Placeholder xs={8} />
                                        </Placeholder>
                                        <Placeholder as={Card.Text} className="mt-4" animation="glow">
                                            <Placeholder xs={7} /> <Placeholder xs={4} /> <Placeholder xs={4} />{' '}
                                            <Placeholder xs={6} /> <Placeholder xs={8} />
                                        </Placeholder>
                                    </div>
                                </div>
                            </Card>
                        </div>
                        <div className="col-6 pe-0 ps-1">
                            <Card  className="mb-2 mt-0 mx-0 p-0 border-0">
                                <div className="row w-100 m-0 p-0">
                                    <Placeholder as={"div"} className="col-7 rounded-start-2 pla" style={{
                                        minHeight: '250px',
                                        backgroundSize: 'cover',
                                        backgroundPosition: 'center',
                                    }}>
                                    </Placeholder>
                                    <div className="col-5">
                                        <Placeholder as={Card.Title} className="mb-3" animation="glow">
                                            <Placeholder xs={8} />
                                        </Placeholder>
                                        <Placeholder as={Card.Text} className="mt-4" animation="glow">
                                            <Placeholder xs={7} /> <Placeholder xs={4} /> <Placeholder xs={4} />{' '}
                                            <Placeholder xs={6} /> <Placeholder xs={8} />
                                        </Placeholder>
                                    </div>
                                </div>
                            </Card>
                        </div>
                    </>
                ): pol.map(({linkIMage, date, demiTitre, demiDesc,titre,desc},index)=>(
                    <div key={index} className={`col-6 ${(index+1)%2===0 ? 'pe-0 ps-1': 'ps-0 pe-1'}`}>
                        <Card  className="mb-2 mt-0 mx-0 p-0 border-0 cursor-pointer" onClick={()=>clicked(linkIMage,titre,desc,date)}>
                            <div className="row w-100 m-0 p-0">
                                <div className="col-7 rounded-start-2 position-relative" style={{
                                    minHeight: '250px',
                                    backgroundImage: `url(${linkIMage})`,
                                    backgroundSize: 'cover',
                                    backgroundPosition: 'center',
                                }}>
                            <pre className="position-absolute bottom-0 p-2 text-white">
                                {date}
                            </pre>
                                </div>
                                <div className="col-5">
                                    <h5 className="text-aris mb-1 p-1 fw-bolder">{demiTitre}</h5>
                                    <p className="p-0 m-0">
                                        {demiDesc}
                                    </p>
                                </div>
                            </div>
                        </Card>
                    </div>
                ))}
            </div>
            <ShowNews show={show} close={close} objectSet={objectSet}/>
        </>
    )
}

export default Optimisation