import {useConnectWS} from "./WSContext";
import {useEffect, useState} from "react";

const useWebSocket = (destination)=>{
    const {ws, isConnected} = useConnectWS()
    const [body,setBody]= useState(null)

    useEffect(()=>{
        if (!ws || !isConnected || destination===null) {
            return
        }
        const sub = ws.subscribe(destination,(obj)=>{
            setBody(JSON.parse(obj.body))
        })

        return ()=>{
            if(sub){
                sub.unsubscribe()
            }
        }
    },[isConnected,destination,ws])

    return {body}
}

export default useWebSocket
