import {useStatus} from "./useStatus";
import useWebSocket from "../../../../WS/useWebSocket";
import {useEffect, useRef} from "react";
import {DELAY} from "../ViewListEmp";

const UserStatus = ({id, setStatesStatus})=>{
    const {
        status,
        setActive,
        setPassive,
        setInactive,
        setDisconnected,
        is
    } = useStatus();

    const {body} = useWebSocket(id ? "/activity/" + id : null)

    const timeoutRef = useRef(null);
    useEffect(() => {
        if (body){
            clearTimeout(timeoutRef.current);
            if (body.active){
                setActive()
            }else{
                setInactive()
            }
            timeoutRef.current = setTimeout(() => {
                setPassive();
            }, DELAY);
        }else{
            setDisconnected()
        }
        return () => {
            clearTimeout(timeoutRef.current);
        };
    }, [body, id]);

    useEffect(() => {
        setStatesStatus(prev =>
            prev.map(user =>
                user.id === id ? { ...user, status } : user
            )
        );

    }, [status,id]);

    return null
}

export default UserStatus