    emp
    valeur


    constructor(dateActive, emp, valeur) {
        this.dateActive = dateActive;
        this.emp = emp;
        this.valeur = valeur;
    }

    static async addSalaireBase(idEmp, valeur) {
        const response = await fetch(APIURL() + "paie/salaire/" , {
            method: 'post',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": 'Bearer '+ await window.electronStore.get('token'),
            },
            body: JSON.stringify({idEmp: idEmp, valeur: valeur })
        });

        if (response.ok) {
            return await response.text();
        }else{
            throw new Error(await response.text());
        }
    }

