import {APIURL} from "./APIURL";
import axios from 'axios';

export default class RenduDAO {
    idRendu
    employe
    dateDebut
    tache
    comment
    statut


    constructor(idRendu, employe, dateDebut, tache, comment, statut) {
        this.idRendu = idRendu;
        this.employe = employe;
        this.dateDebut = dateDebut;
        this.tache = tache;
        this.comment = comment;
        this.statut = statut;
    }

    static async addRendu(rendu) {
        try {
            const token = await window.electronStore.get('token');

            const response = await axios.post(APIURL() + "rendu/save", rendu, {
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${token}`,
                },
            });

            return response.data;
        } catch (error) {
            if (error.response) {
                console.error(`Erreur ${error.response.status}: ${error.response.data}`);
                throw new Error(`Erreur ${error.response.status}: ${error.response.data}`);
            } else if (error.request) {
                console.error("Aucune réponse reçue du serveur", error.request);
                throw new Error("Aucune réponse reçue du serveur");
            } else {
                console.error("Erreur lors de la requête:", error.message);
                throw new Error(error.message);
            }
        }
    }

    static formatDateInput(date){
        const monday=new Date(date)
        const year = monday.getFullYear();
        const month = String(monday.getMonth() + 1).padStart(2, '0');
        const day = String(monday.getDate()).padStart(2, '0');

        return `${year}-${month}-${day}`;
    }
    static async getWeekRender(idEmp,dateDebut,dateFin) {
        const response = await fetch(APIURL() + `rendu/${idEmp}?debut=${this.formatDateInput(dateDebut)}&fin=${this.formatDateInput(dateFin)}` , {
            method: 'get',
            headers: {
                "Content-Type": 'application/json'
            }
        })
        if (response.ok){
            return await response.json()
        }else{
            throw new Error('des erreurs se sont survenus')
        }
    }
    static async deleteS(rendu) {
        const response = await fetch(APIURL() + "rendu/"+rendu , {
            method: 'delete',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": 'Bearer '+ await window.electronStore.get('token'),
            }
        });

        if (response.ok) {
            return true
        }else{
            throw new Error("erreur de connexion");
        }
    }

    static async modifRendu(rendu) {
        const response = await fetch(APIURL() + "rendu/" , {
            method: 'put',
            headers: {
                "Content-Type": 'application/json'
            },
            body: JSON.stringify(rendu)
        });

        if (response.ok){
            return true
        }else{
            throw new Error('On ne peut pas faire cette requête pour le moment!');
        }
    }
}