import React, {useRef} from "react";
import {OverlayPanel} from "primereact/overlaypanel";

const TDOverlay = ({id, comp})=>{
    const tdref = useRef(null)

    return(
        <>
            {id ? comp.comprise ? (
                <td ref={tdref} onMouseEnter={(e)=>tdref.current.toggle(e)} onMouseLeave={(e)=>tdref.current.toggle(e)} className={`date-cell ${id ? 'cursor-pointer' : 'empty-cell'}`}>
                    <OverlayPanel className="p-0 m-0" ref={tdref}>
                        <div className="width-max">
                            <div className="text-break text-print mb-2" style={{maxWidth: '12rem'}}>
                                <span className="text-grey small pb-1 px-1 border-bottom">Cause :</span>
                                <span>{comp.cause.trim()==='' ? '----' : comp.cause.trim()}</span>
                            </div>
                            <div className="text-break text-print">
                                <span className="text-grey small pb-1 px-1 border-bottom">Date Demande :</span>
                                <span>{new Date(comp.dateDemande).toLocaleDateString()}</span>
                            </div>
                        </div>
                    </OverlayPanel>
                    <div  className={`date-content shadow bg-info`}>
                        <pre className="m-0 p-0">{id || ''}</pre>
                    </div>
                </td>
            ) : (
                <td className={`date-cell empty-cell`}>
                    <div  className={`date-content shadow`}>
                        <pre className="m-0 p-0">{id || ''}</pre>
                    </div>
                </td>
            ): (
                <td/>
            )}
        </>
    )
}
export default TDOverlay