import React, {useCallback, useEffect, useState} from "react";
import {Form, Modal, Spinner} from "react-bootstrap";
import Dropzone from "react-dropzone";
import FileView from "./FileView";
import RenduFile from "../../Model/RenduFile";


const AddFile = ({user,dates=[]})=>{
    const [show, setShow] = useState(false);
    const [files, setFiles] = useState([]);
    const [ref, setRef] = useState(`${dates[0]}_${dates[1]}`);
    const [tailles, setTailles] = useState({
        minim: false,
        maxim: false,
        normal: true
    });
    const [loading, setLoading] = useState({
        file: false,
        send: false
    });
    const onFileDrop = useCallback(
        (acceptedFiles) => {
            setFiles((prev) => {
                const newFiles = acceptedFiles.filter(
                    (file) => !prev.some((existingFile) => existingFile.name === file.name && existingFile.size === file.size)
                );

                return [...prev, ...newFiles];
            });
            setTailles((prev)=>({...prev, maxim : false}))
        },
        [],
    );
    useEffect(()=>{
        setFiles([])
    },[show])

    const upload = useCallback(
        () => {
            if (files.length<1 || ref.trim().length<1){
                return
            }
            setLoading((prev=>({...prev, send: true})))
            RenduFile.uploadFiles(ref,files,user?.idEmp).then((e)=>{
                setShow(false)
                console.log(e)
            }).catch((error)=>{
                console.log(error)})
                .finally(()=>{
                    setLoading(prev=>({...prev, send: false}))
                })
        },
        [files,ref]
    );

    return(
        <>
            <i className="fa fa-plus-circle text-plus" onClick={()=>setShow(true)} />
            <Modal
                show={show}
                onHide={()=>setShow(false)}
                keyboard={false}
                backdrop="static"
                dialogClassName="modal-dialog-centered modal-70w position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center w-100 mt-0"
            >
                <Modal.Header closeButton>
                    <Modal.Title className="fs-5">Rendu du {dates[0]} au {[dates[1]]}</Modal.Title>
                </Modal.Header>
                <Modal.Body className={`text-print ${tailles.maxim ? 'position-relative height-200' : ''}`}
                    onDragEnter={()=>{
                        setTailles((prev)=>({...prev, maxim : true}))
                    }}>
                    <div className={`w-100 text-center text-info ${tailles.maxim ? 'opacity-0' : ''}`}>
                        <h5>Ajout de fichier</h5>
                        <hr className="mx-2"/>
                    </div>
                    <div className={`w-100 mt-2`}>
                        <Form.Group className={`${tailles.maxim ? 'opacity-0' : ''}`} controlId="tache">
                            <Form.Label>Ref</Form.Label>
                            <Form.Control  type="text" value={ref} onChange={(event)=>setRef(event.target.value)} placeholder="Nom de la tâche" />
                        </Form.Group>
                        <Form.Group  controlId="fichier">
                            <Form.Label className={`mt-2 ${tailles.maxim ? 'opacity-0' : ''}`}>Fichier</Form.Label>
                            <div className="row m-0 p-0 w-100 ">
                                {files.map((file,index)=>(
                                    <FileView opacity={tailles.maxim} setAllFiles={setFiles} key={index} fichier={file}/>
                                ))}
                                <Dropzone onDragEnter={()=>{
                                    console.log("drage enter")
                                }} onDrop={acceptedFiles => onFileDrop(acceptedFiles)} accept={
                                    {
                                        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": [],
                                        "application/msword": [],
                                        "application/vnd.ms-excel": [],
                                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": [],
                                        "application/vnd.ms-powerpoint": [],
                                        "application/vnd.openxmlformats-officedocument.presentationml.presentation": [],
                                        "application/x-rar-compressed": [],
                                        "application/zip": [],
                                        "text/plain": [],
                                        "image/jpeg": [],
                                        "image/png": [],
                                        "image/gif": [],
                                        "image/webp": [],
                                        "application/pdf": [],
                                    }}>
                                    {({getRootProps, getInputProps}) => (
                                        <section className={`border-is-null rounded-3 ${tailles.maxim ? 'position-absolute top-0 start-0 w-100 z-3 opacity-1 bg-danger bg-opacity-50 height-200' : files.length >0 ? 'col-4 align-items-stretch mb-2 height-80' : 'height-100 w-100'}`}>
                                            <div className="h-100 w-100 d-flex justify-content-center align-items-center" {...getRootProps()}>
                                                <input {...getInputProps()} />
                                                {files.length >0 ? (<i className="fa fa-plus-circle text-plus"/>) : (<p className="pb-0 m-0">Glissez ou cliquez ici pour ajouter vos fichiers</p>)}

                                            </div>
                                        </section>
                                    )}
                                </Dropzone>
                            </div>
                        </Form.Group>
                    </div>
                </Modal.Body>
                <Modal.Footer>
                    <button type="button" className="btn btn-secondary" onClick={()=>setShow(false)}>Annuler</button>
                    {loading.send ? (
                        <button type="button" className="btn btn-primary">
                            <Spinner animation="border" size={"sm"} role="status"  aria-hidden="true"/>
                            chargement...
                        </button>
                    ): (
                        <button type="button" className="btn btn-primary" onClick={upload}>Envoyer</button>
                    )}
                </Modal.Footer>
            </Modal>
        </>
    )
}
export default AddFile