import React, {useCallback, useEffect, useMemo, useState} from "react";
import {Card, CardBody, CardTitle, Dropdown} from "react-bootstrap";
import ModifCotisation from "./ModifCotisation";

const ViewCotisation = ({object})=>{
    const [showMenu, setShowMenu] = useState(false);
    const [modif, setModif] = useState(false);

    const [changeValue, setChangeValue] = useState({
        valeur: object.valeur,
        type: object.type
    });

    const symbole = useMemo(
        () => {
            if (changeValue.type ==="MGA"){
                return "MGA"
            }else{
                return <i className="fas fa-percent"/>
            }
        }, [changeValue]
    );

    return(
        <>
            <Card className="bg-blue-darker h-100">
                <CardTitle className="text-center text-white pt-1 mb-0 mt-0 position-relative">
                    <img src={`https://logo.clearbit.com/${object.nom.nomCotisation}.mg`} alt="" className="me-1 rounded-circle bg-primary" height="25" width="25"/>
                     {object.nom.nomCotisation}
                    <div onClick={()=>setShowMenu(true)} className="position-absolute end-0 d-flex  align-items-center top-0 h-100 pe-2 bg-transparent bg-opacity-25 rounded-3 cursor-pointer w-100 justify-content-end">
                        <Dropdown drop={"end"} show={showMenu}  onToggle={()=>setShowMenu(false)}>
                            <Dropdown.Toggle as={"i"} className="fa fa-ellipsis-v"/>
                            <Dropdown.Menu  align={'start'}>
                                <Dropdown.Item onClick={()=>setModif(true)} eventKey="2">Modifier la valeur</Dropdown.Item>
                            </Dropdown.Menu>
                        </Dropdown>
                    </div>
                </CardTitle>
                <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                    <pre className="p-0 m-0 fw-bold" style={{fontFamily: 'monospace', fontSize: '1.1rem'}}>{changeValue.valeur}</pre><pre className="m-0 p-0 h6 fw-bold">{symbole}</pre>
                </CardBody>
            </Card>
            {modif && (
                <ModifCotisation  setCurrentValue={setChangeValue} type={{nom: object.nom.nomCotisation, id: object.nom.idTypeCotisation}}  show={modif} hide={()=>setModif(false)}/>
            )}
        </>
    )
}

export default ViewCotisation