import React, {useEffect, useState} from "react";
import {Form, InputGroup} from "react-bootstrap";
import {formatDateToInputValue} from "../../InfoPersonel";
import Pagination from "../Utilitaire/Pagination";
import {normalizeString} from "../../Rendu/Hebdo";
import Pointage from "../../../Model/Pointage";
import ViewEmp from "./Component/ViewEmp";
import {useLocation} from "react-router-dom";
import {useDispatch, useSelector} from "react-redux";

const VueEnsemble =()=>{

    const [date, setDate] = useState(new Date())
    const [paginate, setPaginate] = useState(1);
    const [filtered, setFiltered] = useState([]);

    const [allEmp, setAllEmp] = useState([]);
    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [post, setPost] = useState('');

    useEffect(()=>{
        Pointage.getActivityByDate(date.toLocaleDateString()).then((rep)=>{
            setAllEmp(rep)
        }).catch((error)=>{
            console.log(error)
        })
    },[date])
    useEffect(() => {
        let data = allEmp;
        if (matricule) {
            data = data.filter(rep =>{
                if (rep.pointage.employe.matricule){
                    return rep.pointage.employe.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter(rep =>
                rep.pointage.employe.nom.toLowerCase().includes(nom.toLowerCase()) ||
                rep.pointage.employe.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        if (post){
            data = data.filter(rep=>normalizeString(rep.pointage.employe.type.poste.toLowerCase()).includes(normalizeString(post.toLowerCase())))
        }
        setFiltered(data)
    }, [matricule,nom,allEmp,post]);

    const { search } = useLocation();
    useEffect(() => {
        const queryParams = new URLSearchParams(search);
        if (queryParams.size>0){
            setMatricule(queryParams.get("id"))
        }
    }, [search]);
    const dispatch = useDispatch();

    useEffect(() => {
        dispatch({ type: "SET_ETAT", payload: 8 });
    }, []);


    return(
        <>
            <div className="card w-100 mb-2">
                <div className="card-body pt-1 pb-1">
                    <h3 className="text-center">Liste des Salariés</h3>
                    <div className="row m-0 p-0">
                        <div className="col-3">
                            <InputGroup size={"sm"} className="my-2">
                                <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                                <Form.Control
                                    placeholder="matricule"
                                    aria-label="matricule"
                                    aria-describedby="basic-addon1"
                                    type="search"
                                    size={"sm"}
                                    value={matricule}
                                    onChange={(event)=>{
                                        setMatricule(event.target.value.replace(/\D/g, ''))
                                    }}
                                />
                            </InputGroup>
                        </div>
                        <div className="col-5">
                            <InputGroup size={"sm"} className="my-2">
                                <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                                <Form.Control
                                    placeholder="nom ou prénom"
                                    aria-label="nom"
                                    aria-describedby="nom"
                                    type="search"
                                    size={"sm"}
                                    value={nom}
                                    onChange={(event) => setNom(event.target.value)}
                                />
                            </InputGroup>
                        </div>
                        <div className="col-4">
                            <InputGroup size={"sm"} className="my-2">
                                <InputGroup.Text id="basic-addon1">Poste</InputGroup.Text>
                                <Form.Control
                                    placeholder="nom ou prénom"
                                    aria-label="nom"
                                    aria-describedby="nom"
                                    type="search"
                                    size={"sm"}
                                    value={post}
                                    onChange={(event) => setPost(event.target.value)}
                                />
                            </InputGroup>
                        </div>
                    </div>
                </div>
            </div>
            <div className="w-100 py-2 d-inline-flex justify-content-between mb-2">
                <span className="fs-4 fw-bolder">Date du {date.toLocaleDateString("fr-FR",  { day: "numeric", month: "short", year: "numeric" })}</span>
                <InputGroup size={"sm"} className="" style={{width: '16vw'}}>
                    <InputGroup.Text id="basic-addon1">Date</InputGroup.Text>
                    <Form.Control
                        aria-label="Date"
                        aria-describedby="basic-addon1"
                        type="date"
                        size={"sm"}
                        value={formatDateToInputValue(date)}
                        onChange={(e) => {
                            const dt = new Date(e.target.value);
                            const today = new Date();

                            today.setHours(0, 0, 0, 0);
                            dt.setHours(0, 0, 0, 0);

                            if (dt.getTime() > today.getTime()) {
                                setDate((prev) => prev);
                            } else {
                                setDate(dt);
                            }
                        }}

                    />
                </InputGroup>
            </div>
            <div className="m-0 w-100 rounded-3 bg-white mb-3 p-2">
                {filtered.length===0 && (
                    <div className="w-100 d-flex flex-column justify-content-center align-items-center opacity-25 fs-4" style={{height: '400px'}}>
                        <i className="fa fa-table"/>
                        <span className="fs-5">Aucune donnée</span>
                    </div>
                )}
                {filtered.slice((paginate-1)*6,paginate*6).map((element)=>(
                    <ViewEmp element={element} key={element.pointage.idPointage}/>
                ))}
                <div className="d-flex justify-content-end w-100 m-0 p-2">
                    <Pagination length={filtered.length % 6 === 0 ? filtered.length / 6 : Math.floor(filtered.length / 6) + 1} active={paginate} setActive={setPaginate}/>
                </div>
            </div>
        </>
    )
}
export default VueEnsemble