import {APIURL} from "./APIURL";

export default class TopInfo {
    linkImage
    date
    desc
    linkDetail

    constructor(linkImage, date, desc, linkDetail) {
        this.linkImage = linkImage;
        this.date = date;
        this.desc = desc;
        this.linkDetail = linkDetail;
    }
    static async getTopInfo(){
        const response = await fetch(APIURL() + `horoscope/orangeInfo` , {
            method: 'get',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": 'Bearer '+ await window.electronStore.get('token'),
            },
        });

        if (response.ok) {
            return await response.json()
        }else{
            return []
        }
    }
}