import React, {createContext, useState, useEffect, useRef, useContext} from 'react';
import SockJS from "sockjs-client";
import { Stomp } from "@stomp/stompjs";
import {APIURL} from "../Model/APIURL";
import {UserContext} from "../Component/Main/Utilitaire/UserProvider";
import {Modal} from "react-bootstrap";

const WSContext = createContext(null)

export const WSProvider = ({url,children})=>{
    const {reconnectInterval = 3000, maxRetries = Infinity} ={}
    const [isConnected,setIsConnected] = useState(false)
    const { user, } = useContext(UserContext);
    const stompClientRef = useRef(null)
    const retriesRef = useRef(0)

    const [isLogOut,setIsLogOut] = useState(false)

    const [block, setBlock] = useState(false);

    const connect = ()=>{
        if (user){
            const socket = new SockJS(APIURL() + "ws")
            const stompClient = Stomp.over(socket)
            stompClient.debug = ()=>{}
            stompClient.heartbeatOutgoing=10000
            stompClient.heartbeatIncoming=10000
            stompClient.onConnect = () =>{
                setIsConnected(true)
                setBlock(false)
                setIsLogOut(false)
                retriesRef.current = 0
            }

            stompClient.onStompError = () => {
                handleDisconnect();
            };


            stompClient.onWebSocketClose = () => {
                console.warn("WebSocket connection closed");
                handleDisconnect();
            };

            stompClient.onWebSocketError = () => {
                handleDisconnect();
            };

            stompClient.activate();

            socket.onclose = ()=>{
                handleDisconnect();
            }
            socket.onerror = (error)=>{
                console.log("eroor....")
                handleDisconnect();
            }
            stompClientRef.current = stompClient
        }
    }

    const disconnect = () => {
        if (stompClientRef.current) {
            stompClientRef.current.disconnect(() => {
                setIsConnected(false)
                setIsConnected(false);
            });
        }
        stompClientRef.current=null
    };
    useEffect(() => {
        if (!isConnected){
            stompClientRef.current=null
        }
    }, [isConnected]);

    const handleDisconnect = () => {
        setIsConnected(false);
        if (retriesRef.current < maxRetries) {
            if (retriesRef.current>2){
                setBlock(true)
                setIsLogOut(true)
            }
            retriesRef.current += 1;
            console.log(`Retrying connection (${retriesRef.current}/${maxRetries})...`);
            setTimeout(connect, reconnectInterval);
        }
    };

    useEffect(()=>{
        if (user){
            connect()
        }
        return () => {
            disconnect();
        };
    },[user,url])


    return(
        <WSContext.Provider value={{ws : stompClientRef.current, isConnected}}>
            {isLogOut && (
                <div
                    className="modal show position-fixed height-max width-max mx-auto top-0 pt-5 end-0 start-0"
                    style={{ display: 'block', position: 'initial', transform: 'translateX(50%)' }}
                >
                    <Modal.Dialog className="border-0 p-2 bg-transparent bg-rip">
                        <Modal.Body  className="z-1 py-1 px-3 border-0 bg-warning-subtle rounded-3">
                            <pre className="fs-4 m-0 p-0 text-danger ">Serveur deconnecté</pre>
                        </Modal.Body>
                    </Modal.Dialog>
                </div>
            )}
            {children}
            {block && (
                <div className="bg-dark bg-opacity-10 h-100 w-100 position-fixed top-0 z-3"/>
            )}
        </WSContext.Provider>
    )
}
export const useConnectWS = ()=>{
    return useContext(WSContext)
}