import React, {useEffect, useMemo} from "react";
import {APIURL} from "../../Model/APIURL";
import {useUserStatus} from "../Main/Salarier/Hook/StatusUserWSContext";

const Profile = ({element, getStatus})=>{
    const {addUserId} = useUserStatus()
    useEffect(() => {
        addUserId(element.idEmp)
    }, [element.idEmp]);
    const status = getStatus(element.idEmp)
    const userProfile = useMemo(()=>{
        return (
            <div className="width-max position-relative">
                {element?.profile ? (
                    <img
                        src={APIURL()+`${element.profile}`}
                        alt=""
                        decoding={"async"}
                        className="border-dark-light rounded-circle mt-0 pt-0 z-0"
                        width={55} height={55}
                        style={{ objectFit: 'cover', width: '40px !important', height: '40px !important', overflow: 'hidden' }}
                    />
                ): (
                    <img
                        alt=""
                        className="border-dark-light rounded-circle mt-0 pt-0 z-0"
                        width={55} height={55}
                        style={{ objectFit: 'cover', width: '40px !important', height: '40px !important', overflow: 'hidden' }}
                    />
                )}
                <div className="position-absolute bottom-0 end-0 width-max z-2 d-flex align-bottom">
                    {status === "active" && (
                        <span className="rounded-circle border border-3 border-success bg-success-subtle spanRounded"/>
                    )}
                    {status === "inactive" && (
                        <span className="rounded-circle border border-3 border-warning bg-body spanRounded"/>
                    )}
                    {status === "disconnected" && (
                        <span className="rounded-circle border border-3 border-danger bg-danger bg-opacity-50 spanRounded"/>
                    )}
                    {status === "passive" && (
                        <span className="rounded-circle border border-3 border-dark bg-dark bg-opacity-50 spanRounded"/>
                    )}
                </div>
            </div>
        )
    },[element, status])


    return userProfile
}
export default Profile