import React, {useCallback, useEffect, useMemo, useState} from "react";
import ViewTitleRendu from "./ViewTitleRendu";
import ViewFile from "./ViewFile";
import RenduFile from "../../Model/RenduFile";
import Quotidien from "./Quotidien";


export function getWeeklyIntervals(year, month) {
    const currentDate = new Date();
    const currentYear = currentDate.getFullYear();
    const currentMonth = currentDate.getMonth() + 1;

    if (year > currentYear || (year === currentYear && month > currentMonth)) {
        return [];
    }
    const weeks = [];
    const firstDayOfMonth = new Date(year, month - 1, 1);
    const lastDayOfMonth = new Date(year, month, 0);

    let start = new Date(firstDayOfMonth);
    start.setDate(start.getDate() - (start.getDay() === 0 ? 6 : start.getDay() - 1));

    let end = new Date(lastDayOfMonth);
    end.setDate(end.getDate() + (end.getDay() === 5 ? 0 : (5 - end.getDay())));

    let current = new Date(start);

    const mondayCurrentDate = new Date(currentDate);
    const dayOfWeek = currentDate.getDay();
    mondayCurrentDate.setDate(currentDate.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
    const fridayCurrentDate = new Date(currentDate);
    fridayCurrentDate.setDate(mondayCurrentDate.getDate() + 4);

    while (current <= end ) {
        let monday = new Date(current);
        let friday = new Date(monday);
        friday.setDate(friday.getDate() + (5 - monday.getDay()));

        if (!(monday.getMonth() + 1 !== month && friday.getMonth() + 1 !== month)) {
            weeks.push({
                Monday: new Date(monday),
                Friday: new Date(friday)
            });
        }
        if (friday.toDateString() === fridayCurrentDate.toDateString()){
            break
        }
        current.setDate(current.getDate() + 7);
    }
    return weeks;
}
const AllRendu = ({user, allUser,setUser})=>{

    const [currentDate] = useState(new Date());
    const [year, setYear] = useState(currentDate.getFullYear());
    const [month, setMonth] = useState(currentDate.getMonth());
    useEffect(() => {
        setYear(currentDate.getFullYear())
        setMonth(currentDate.getMonth())
    }, [user?.idEmp]);

    const yearClicked =useCallback((value) => {
        setYear(prev => prev +value)
    },[])
    const monthYear = useMemo(()=>["Jan", "Fev", "Mar", "Avr", "Mai", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],[])

    const [dates, setDates] = useState(getWeeklyIntervals(year,month+1));

    useEffect(() => {
       setDates(getWeeklyIntervals(year,month+1))
    }, [year,month]);

    const [files, setFiles] = useState([]);

    useEffect(() => {
        RenduFile.getAllByUser(month+1,year,user?.idEmp).then((resp)=>{
            setFiles(resp)
        }).catch(()=>{})
    }, [user?.idEmp,year,month]);

    const nextClicked = useCallback(() => {
        if (!allUser || allUser.length === 0 || !user) return;

        const sortedUsers = [...allUser].sort((a, b) => parseInt(a.matricule) - parseInt(b.matricule));

        const nextUser = sortedUsers.find(e => parseInt(e.matricule) > parseInt(user.matricule));

        if (nextUser) {
            setUser(nextUser);
        }
    }, [user, allUser, setUser]);

    const prevClicked = useCallback(() => {
        if (!allUser || allUser.length === 0 || !user) return;

        const sortedUsers = [...allUser].sort((a, b) => parseInt(b.matricule) - parseInt(a.matricule));

        const nextUser = sortedUsers.find(e => parseInt(e.matricule) < parseInt(user.matricule));

        if (nextUser) {
            setUser(nextUser);
        }
    }, [user, allUser, setUser]);

    const [dateClicked, setDateClicked] = useState({
        monday: new Date(),
        friday: new Date()
    });
    const [showRapport, setShowRapport] = useState(false);
    useEffect(() => {
        setDateClicked(()=>({
            monday: new Date(), friday: new Date()
        }))
        setShowRapport(false)
    }, [user,month,year]);

    useEffect(() => {
        if (dateClicked.monday.toDateString() !== dateClicked.friday.toDateString()){
            setShowRapport(true)
        }
    }, [dateClicked]);


    const views = useMemo(() => {
        if (showRapport){
            return (
                <Quotidien dateFriday={dateClicked.friday} dateMonday={dateClicked.monday} idUtilisateur={user}/>
            )
        }
        return (
            <div className="row mt-0 mb-2 mx-0 p-0">
                <div className="col-8 p-0 m-0">
                    <div className="row m-0 p-0">
                        {dates.map((date,key)=>(
                            <ViewTitleRendu setDateClicked={setDateClicked} key={key} date={date}/>
                        ))}
                        {dates.length===0 && (
                            <div className="w-100 p-2 bg-semi-dark text-center text-white">
                                Pas de Rendu pour le moment
                            </div>
                        )}
                    </div>
                </div>
                <div className="col-4 rounded-2 border">
                    <h3 className="text-center py-2">Fichiers envoyés</h3>
                    {files.map((data)=>(
                        <ViewFile key={data.id} data={data}/>
                    ))}

                </div>
            </div>
        )
    }, [showRapport,dates, files,dateClicked,user]);

    return(
        <>
            <div className="card mb-2 rounded-bottom-0">
                <div className="card-body ps-0 pe-1 pb-1 position-relative">
                    {allUser && allUser.length>0 && (
                        <div className="position-absolute top-3 d-inline-flex justify-content-start">
                            <button onClick={prevClicked} type="button" className="btn btn-light btn-sm mx-2 shadow text-warning">
                                <i className="fa fa-arrow-left"/>
                            </button>
                            <button onClick={nextClicked} type="button" className="btn btn-sm btn-light shadow text-info">
                                <i className="fa fa-arrow-right"/>
                            </button>
                        </div>
                    )}
                    <div className="w-100 text-center mb-3">
                        <span className="fs-4 fw-bolder">{user?.nom} {user?.prenom}</span>
                    </div>
                    <div className="row m-0 p-0  w-100">
                        <div className="w-100 mb-2">
                            <div className="w-50 mx-auto">
                                <div className="centered-year-container my-2">
                                    <div>
                                        <i onClick={() =>yearClicked(-1)} className="fas fa-chevron-left fs-5 cursor-pointer"/>
                                    </div>
                                    <div className="year">
                                        <pre className="text-dark fs-5 m-0 p-0">{year}</pre>
                                    </div>
                                    <div>
                                        <i onClick={() => yearClicked(+1)} className="fa fa-chevron-right fs-5 cursor-pointer"/>
                                    </div>
                                </div>
                            </div>
                            <div className="month-content my-2">
                                <table className="w-100 small text-center">
                                    <tbody>
                                    <tr className="months-row">
                                        {monthYear.map((value, index) => (
                                            <td
                                                onClick={() => setMonth(index)}
                                                className={`month cursor-pointer ${index === month ? 'fw-bolder' : ''}`}
                                                key={index}
                                            >
                                                {value}
                                            </td>
                                        ))}
                                    </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div className="w-100 mb-3 d-inline-flex justify-content-end">
                <button onClick={()=>setShowRapport(false)} disabled={dateClicked.monday.toDateString() === dateClicked.friday.toDateString()} type="button" className="btn btn-dark btn-sm mx-2 shadow text-warning">
                    Liste Rendu
                </button>
                <button onClick={()=>setShowRapport(true)} type="button" disabled={dateClicked.monday.toDateString() === dateClicked.friday.toDateString()} className="btn btn-sm btn-primary shadow text-white">
                    Detail Rendu
                </button>
            </div>
            {views}
        </>
    )
}

export default AllRendu