import {APIURL} from "./APIURL";
import axios from "axios";

export default class Notification {
    notification
    open


    constructor(notification, open) {
        this.notification = notification;
        this.open = open;
    }

    static async allNotif(idUser) {
        const response = await fetch(APIURL() + "notification/allbyuser/"+idUser, {
            method: 'get',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": 'Bearer '+ await window.electronStore.get('token'),
            },
        });

        if (response.ok) {
            return await response.json();
        }else{
            throw new Error("on ne peut pas faire cette requete pour le moment");
        }
    }

    static async openNotif(idUser){
        const response = await axios.put(APIURL()+"notification/open/"+idUser)
        if (response.status===200){
            return true
        }else{
            throw new Error("Problème de connexion...")
        }
    }
    static async setVue(idNotification){
        const response = await axios.put(APIURL()+"notification/vue/"+idNotification)
        if (response.status===200){
            return true
        }else{
            throw new Error("Problème de connexion...")
        }
    }

    static async deleteNotif(idNotification){
        const response = await axios.put(APIURL()+"notification/delete/"+idNotification)
        if (response.status===200){
            return true
        }else{
            throw new Error("Problème de connexion...")
        }
    }
}