import Login from "./Page/Login";
// import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import Bg from "./Component/Bg";
import Home from "./Page/Home";
import Inscription from "./Page/Inscription";
import InfoPersonel from "./Component/InfoPersonel";
import InfoBanque from "./Component/InfoBanque";
import InfoLogin from "./Component/InfoLogin";
import {useEffect, useState} from "react";
import Content from "./Component/Content";
import ValiderSalarie from "./Component/Main/Salarier/ValiderSalarie";
import AttendanceCalendar from "./Component/Main/Presence/AttendanceCalendar";
import ListSalarier from "./Component/Main/Salarier/ListSalarier";
import Solde from "./Component/Conge/Solde";
import Demande from "./Component/Conge/Demande";
import Validation from "./Component/Conge/Validation";
import MesRendu from "./Component/Rendu/MesRendu";
import Quotidien from "./Component/Rendu/Quotidien";
import Hebdo from "./Component/Rendu/Hebdo";
import BulletinsPaie from "./Component/Paie/BulletinsPaie";
import Paramettre from "./Component/Paie/Paramettre";
import ValidationPaie from "./Component/Paie/ValidationPaie";
import VueEnsemble from "./Component/Main/Presence/VueEnsemble";
import PlanningConge from "./Component/Conge/PlanningConge";
import VidePage from "./Page/Vide";

function App() {
    const [textInscription,setText]=useState('inscription')
    useEffect(() => {
        const handleLinkClick = (e) => {
            const target = e.target;

            if (target.tagName === 'A' && target.href.startsWith('http')) {
                const url = new URL(target.href);

                const isExternal = url.origin !== window.location.origin;

                if (isExternal) {
                    e.preventDefault();
                    window.navigate.defaultNavigateur(target.href);
                }
            }
        };

        document.addEventListener('click', handleLinkClick);

        return () => {
            document.removeEventListener('click', handleLinkClick);
        };
    }, []);

    return (
        <>
            <Router>
                <Routes>
                    <Route path="/" element={<Bg />}>
                        <Route path="" element={<Login />} />
                        <Route path="/inscription" element={<Inscription text={textInscription} />}>
                            <Route path="" element={<InfoPersonel setText={setText}/>} />
                            <Route path="rh-info" element={<InfoBanque setText={setText}/>} />
                            <Route path="login-info" element={<InfoLogin setText={setText} />} />
                        </Route>
                        <Route path="/*" element={<Home />} >
                            <Route path="accueil" element={<Content />} />
                            <Route path="employer/list" element={<ListSalarier />} />
                            {/*<Route path="employer/validation/:emp" element={<ValiderSalarie />} />*/}
                            <Route path="employer/validation" element={<ValiderSalarie />} />
                            <Route path="employer/precence" element={<AttendanceCalendar />} />
                            <Route path="employer/pointage/now" element={<VueEnsemble />} />
                            <Route path="conge/solde" element={<Solde />} />
                            <Route path="conge/demande" element={<Demande />} />
                            <Route path="conge/validation" element={<Validation />} />
                            <Route path="conge/planning" element={<PlanningConge />} />
                            <Route path="rendu/MesRendu" element={<MesRendu />} />
                            <Route path="rendu/quotidien" element={<Quotidien />} />
                            <Route path="rendu/hebdo" element={<Hebdo />} />
                            <Route path="paie/bulletin" element={<BulletinsPaie />} />
                            <Route path="paie/paramettre" element={<Paramettre />} />
                            <Route path="paie/validation" element={<ValidationPaie />} />
                        </Route>
                        <Route path="/vide" element={<VidePage />} />
                    </Route>
                </Routes>
            </Router>
        </>
    );
}

export default App;
