import React, {useMemo, useState} from "react";
import Detail from "./Detail";
import {Col, Form, Modal, Spinner} from "react-bootstrap";
import {addDays} from "date-fns";
import {differenceEnJours, formatNumberDay} from "./Demande";
import {formatDateToInputValue} from "../InfoPersonel";

const EditerConger = ({conge,show,close})=>{
    const [dateDebut,setDateDebut]=useState(new Date())
    const [dateFin,setDateFin]=useState(new Date())
    const [isMatinDebut,setMatinDebut]=useState(true)
    const [isMatinFin,setMatinFin]=useState(false)
    const [cause,setCause]=useState('')
    const [dateRetour,setDateRetour]=useState('')
    // const [isModi,setIsModif]=useState(true)
    const [erreur,setErreur]=useState(false)
    const [errorMessage,setErrorMessage]=useState('')
    const [loading,setLoading]=useState(false)
    const dure = useMemo( () => {
        let diffDays = differenceEnJours(dateFin, dateDebut);
        if (isMatinDebut && isMatinFin){
            diffDays+=0.5;
        }else if(isMatinDebut && !isMatinFin){
            diffDays+=1;
        }else if(!isMatinDebut && !isMatinFin){
            diffDays+=0.5;
        }
        const valiny=Math.max(diffDays, 0)
        setDateRetour( ()=>{
            if (valiny===0){
                return "--/--/---- : --"
            }
            const format=formatDateToInputValue(addDays(dateDebut, formatNumberDay(valiny, isMatinDebut,isMatinFin))).split("-")
            return format[2]+"/"+format[1]+"/"+format[0]+`${isMatinFin ? ' : Midi' : ' : Matin'}`
        });
        return valiny;
    },[dateDebut, dateFin, isMatinDebut, isMatinFin])
    return(
        <Modal
            show={show}
            onHide={close}
            keyboard={false}
            backdrop="static"
            dialogClassName="modal-dialog-centered modal-W position-relative d-flex justify-content-center align-items-center"
            contentClassName="d-flex justify-content-center w-100"
            animation
            autoFocus={true}>
            <Modal.Header closeButton>
                <Modal.Title className={`${conge.statut==="ENCOURS" ? 'text-warning' : conge.statut=== "REFUSER" ? 'text-danger' : 'text-concept'} fs-5`}>Detail du Congé ({conge.statut})</Modal.Title>
            </Modal.Header>
            <Modal.Body>
                <h4 className="text-center">Nouvelle demande</h4>
                <Form
                    // onSubmit={(event)=>submit(event)}
                >
                    <Form.Group className="mb-1" controlId="edit-dateDebut">
                        <Form.Label>Date debut</Form.Label>
                        <Form.Control autoFocus type="date" value={formatDateToInputValue(dateDebut)} onChange={(e)=>{
                            const dt = new Date(e.target.value);
                            const today = new Date();

                            today.setHours(0, 0, 0, 0);
                            dt.setHours(0, 0, 0, 0);

                            if (dt.getTime() < today.getTime()) {
                                return
                            } else {
                                setDateDebut(dt)
                            }
                        }} placeholder="Date debut" />
                    </Form.Group>
                    <Form.Group className="mb-3" controlId="dateDebutEdit">
                        <Form.Check
                            inline
                            label="Matin"
                            name="group3"
                            type={"radio"}
                            checked={isMatinDebut===true}
                            onChange={()=>setMatinDebut(true)}
                            id="radio-3"
                        />
                        <Form.Check
                            inline
                            label="Après-midi"
                            name="group3"
                            type={"radio"}
                            checked={isMatinDebut===false}
                            onChange={()=>setMatinDebut(false)}
                            id="radio-4"
                        />
                    </Form.Group>

                    <Form.Group className="mb-1" controlId="editDateFin">
                        <Form.Label>Date fin</Form.Label>
                        <Form.Control type="date" value={formatDateToInputValue(dateFin)} onChange={(e)=>{
                            const dt = new Date(e.target.value);
                            const today = new Date();

                            today.setHours(0, 0, 0, 0);
                            dt.setHours(0, 0, 0, 0);

                            if (dt.getTime() < today.getTime()) {
                                return
                            } else {
                                setDateFin(dt)
                            }
                        }} placeholder="Date fin" />
                    </Form.Group>
                    <Form.Group className="mb-2" controlId="DateFinRadio-Edit">
                        <Form.Check
                            inline
                            name={"groupe4"}
                            label="Matin"
                            type={"radio"}
                            checked={isMatinFin===true}
                            onChange={()=>setMatinFin(true)}
                            id="radio-25"
                        />
                        <Form.Check
                            inline
                            name={"groupe4"}
                            label="Après-midi"
                            type={"radio"}
                            checked={isMatinFin===false}
                            onChange={()=>setMatinFin(false)}
                            id="radio-29"
                        />
                    </Form.Group>
                    <div className="row m-0 p-0 w-100">
                        <Form.Group as={Col} sm={4} className="ps-0 mb-3" controlId="NombreJour">
                            <Form.Label>Durée</Form.Label>
                            <Form.Control type="text" disabled value={`${dure}j`}  placeholder="Nombre de jours" />
                        </Form.Group>
                        <Form.Group as={Col} sm={8} className="pe-0 mb-3" controlId="dateRetour">
                            <Form.Label>Date retour</Form.Label>
                            <Form.Control type="text" disabled value={dateRetour}  placeholder="Date retour au travail" />
                        </Form.Group>
                    </div>

                    <Form.Group className="mb-3" controlId="Cause">
                        <Form.Label>Cause (Optionnel)</Form.Label>
                        <Form.Control value={cause} onChange={(e)=>setCause(e.target.value)} as={"textarea"} rows={3} placeholder="Cause" />
                    </Form.Group>
                    <div className="row m-0 p-0 w-100 d-flex justify-content-end">
                        <button type={loading ? 'button' : 'submit'} className="btn bg-blue text-white w-100">
                            {loading ? (
                                <Spinner size={"sm"} animation="border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </Spinner>
                            ) : ('Envoyer')}
                        </button>
                    </div>
                </Form>
            </Modal.Body>
        </Modal>
    )
}

export default EditerConger