import React, {useCallback, useEffect, useState} from "react";
import {Col, Form, InputGroup, Modal, Row} from "react-bootstrap";
import Pagination from "../../Main/Utilitaire/Pagination";
import PersIndView from "./PersIndView";
import {SalaireBase} from "../../../Model/Paie/SalaireBase";
import {normalizeString} from "../../Rendu/Hebdo";
import {formatNumber} from "./ViewSalaireBrute";

const ViewIndemnite = ({show,hide})=>{

    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [post, setPost] = useState('');
    const [filtered, setFiltered] = useState([]);
    const [allData, setAllData] = useState([]);
    useEffect(() => {
        SalaireBase.getAllIndemnite().then((resp)=>{
            setAllData(resp)
        }).catch(()=>{})
    }, []);
    const [paginate, setPaginate] = useState(1);

    const [squareClicked, setSquareClicked] = useState(false);

    const [clickedTab, setClickedTab] = useState([]);

    const [modifValue, setModifValue] = useState(false);

    useEffect(() => {
        let data = allData;
        if (matricule) {
            data = allData.filter(({emp}) =>{
                if (emp.matricule){
                    return emp.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter(({emp}) =>
                emp.nom.toLowerCase().includes(nom.toLowerCase()) ||
                emp.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        if (post){
            data = data.filter(({emp})=>normalizeString(emp.type.poste.toLowerCase()).includes(normalizeString(post.toLowerCase())))
        }
        setFiltered(data)
    }, [allData, matricule, nom, post]);

    const [valeur, setValeur] = useState(0);
    const [periode, setPeriode] = useState(1);

    useEffect(() => {
        if (!modifValue){
            setValeur(0)
            setPeriode(1)
        }
    }, [modifValue]);
    const [pers, ] = useState(["mensuel", "journalier"]);

    const submit = useCallback(()=>{
        SalaireBase.addindemnite(clickedTab,valeur,periode).catch(()=>{})
            .finally(()=>{

                setAllData((prevAllData) =>
                    prevAllData.map((item) =>
                        clickedTab.includes(item.emp.idEmp)
                            ? { ...item, valeur: valeur, periode: pers[periode-1] } : item
                    )
                );
                setClickedTab([])
                setModifValue(false)
            })
    },[clickedTab, valeur, periode])

    return(
        <>
            <Modal
                show={show}
                onHide={hide}
                keyboard={false}
                backdrop="static"
                autoFocus={true}
                dialogClassName="modal-dialog-centered modal-W position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center"
                animation={false}
            >
                <Modal.Header className="position-relative py-2">
                    <strong> Indemnité des employés</strong>
                    <div onClick={()=>hide()} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="bg-dark bg-opacity-75">
                    <div className="card w-100 mb-2">
                        <div className="card-body pt-1 pb-1">
                            <h3 className="text-center">Liste des Salariés</h3>
                            <div className="row m-0 p-0">
                                <div className="col-3">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                                        <Form.Control
                                            placeholder="matricule"
                                            aria-label="matricule"
                                            aria-describedby="basic-addon1"
                                            type="search"
                                            value={matricule}
                                            onChange={(event)=>{
                                                setMatricule(event.target.value.replace(/\D/g, ''))
                                            }}
                                        />
                                    </InputGroup>
                                </div>
                                <div className="col-5">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                                        <Form.Control
                                            placeholder="nom ou prénom"
                                            aria-label="nom"
                                            aria-describedby="nom"
                                            type="search"
                                            value={nom}
                                            onChange={(event) => setNom(event.target.value)}
                                        />
                                    </InputGroup>
                                </div>
                                <div className="col-4">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">Poste</InputGroup.Text>
                                        <Form.Control
                                            placeholder="nom ou prénom"
                                            aria-label="nom"
                                            aria-describedby="nom"
                                            type="search"
                                            value={post}
                                            onChange={(event) => setPost(event.target.value)}
                                        />
                                    </InputGroup>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="m-0 w-100 rounded-3 bg-white">
                        <div className="rounded-3 p-1 m-0 w-100">
                            <table className="table mb-0 table-striped table-hover">
                                <thead>
                                <tr className="text-center">
                                    <th className="cursor-pointer" scope="col" onClick={()=>setSquareClicked((prev)=> {
                                        if (!prev){
                                            setClickedTab(filtered.map(e=>e.emp.idEmp))
                                        }else{
                                            setClickedTab([])
                                        }
                                        return !prev
                                    })}>{squareClicked ? (<i className="fa-regular fa-square-check"/>) : (<i className="fa-regular fa-square"/>)}</th>
                                    <th scope="col"/>
                                    <th scope="col">M°</th>
                                    <th scope="col">Nom</th>
                                    <th scope="col">Prenom</th>
                                    <th scope="col">Poste</th>
                                    <th scope="col">Indemnité</th>
                                    <th scope="col">Periode</th>
                                </tr>
                                </thead>
                                <tbody>
                                {filtered.slice((paginate-1)*10,(paginate)*10).map((element)=>(
                                    <PersIndView key={element.emp.idEmp} element={element} idChecked={clickedTab} setIdChecked={setClickedTab} />
                                ))}
                                </tbody>

                            </table>
                        </div>
                        <div className="d-flex justify-content-end w-100 m-0 p-2">
                            <Pagination length={filtered.length % 10 === 0 ? filtered.length / 10 : Math.floor(filtered.length / 10) + 1} active={paginate} setActive={setPaginate}/>
                        </div>
                    </div>
                </Modal.Body>

                <div onClick={()=>setModifValue(true)} className={`${clickedTab.length>0 && !modifValue ? 'position-fixed bg-primary text-white cursor-pointer py-3 px-3 shadow rounded-3 pulse small' : 'd-none'}`} style={{right: '30px', bottom: '20px', lineHeight: '1.3'}}>
                    Modifier l'indemnité des employés selectionés
                </div>
            </Modal>

            <Modal
                show={modifValue}
                onHide={()=>setModifValue(false)}
                keyboard={false}
                backdrop="static"
                autoFocus={true}
                dialogClassName="modal-dialog-centered  position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center modal-70w"
            >
                <Modal.Header className="position-relative">
                    <strong>  Modifier l'indemnité des employés selectionés</strong>
                    <div onClick={()=>setModifValue(false)} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="pt-1">
                    <div className="row mt-0 mx-0 mb-3 p-0 w-100">
                        <Form.Group className="p-0 m-0" as={Col} md="8" controlId="valeur">
                            <Form.Label className="fw-bold">Valeur</Form.Label>
                            <Form.Control
                                type="text"
                                className="bg-transparent border-dark-light"
                                autoFocus={true}
                                value={formatNumber(valeur)}
                                onChange={(e) => {
                                    const val = e.target.value.replace(/\D/g, '')
                                    setValeur(parseInt(val))
                                }}
                                // isInvalid={!validationErrors.validPrenom}
                                placeholder="valeur"
                                required
                            />
                        </Form.Group>
                        <Form.Group className="m-0 ps-2 pe-0 py-0" as={Col} md="4" controlId="genre">
                            <Form.Label className="fw-bold">Periode</Form.Label>
                            <Form.Select
                                value={periode}
                                onChange={(e) =>{
                                    setPeriode(()=>parseInt(e.target.value))
                                }}
                                className="bg-transparent border-dark-light"
                                required
                            >
                                <option className="text-dark" value={1}>par mois</option>
                                <option className="text-dark" value={2}>par jour</option>
                            </Form.Select>
                        </Form.Group>
                    </div>
                    <Row>
                        <Col md={6}>
                            <button type="button" onClick={()=>setModifValue(false)} className="btn btn-sm bg-aris text-white w-100">Annuler</button>
                        </Col>
                        <Col md={6}>
                            <button type="button" onClick={submit} className="btn btn-sm bg-blue text-white w-100">Valider</button>
                        </Col>
                    </Row>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default ViewIndemnite