import React, {useContext, useEffect, useState} from "react";
import {Modal, Row} from "react-bootstrap";
import logo from "../../img/logoA.png";
import LiElement from "./LiElement";
import {useNavigate} from "react-router-dom";
import {UserContext} from "../Main/Utilitaire/UserProvider";
import SockJS from "sockjs-client";
import {APIURL} from "../../Model/APIURL";
import {Stomp} from "@stomp/stompjs";
import ArisEvent from "../Accueil/Event/ArisEvent";

const SlideBar = React.memo(({idActive,setActive}) => {
    const navigate=useNavigate()
    const { user: contextUser, isModif, setIsModif} = useContext(UserContext);
    const [loading,setLoading]=useState(true)
    const [message,setMessage]=useState(" En attente d'approbation! . . .")


    useEffect(() => {
        let stompClient;

        if (contextUser) {
            if (contextUser?.validation === "VALIDER") {
                setLoading(false);
            } else {
                const socket = new SockJS(APIURL() + "ws");
                stompClient = Stomp.over(socket);

                stompClient.debug = () => {};

                stompClient.connect({}, () => {
                    stompClient.subscribe(
                        "/notif/validation/" + contextUser.idEmp,
                        (mes) => {
                            setMessage(mes.body);
                            setLoading(false)
                            setIsModif(!isModif)
                            stompClient.disconnect();
                        }
                    );
                });
            }
        }

        return () => {
            if (stompClient) {
                stompClient.disconnect();
            }
        };
    }, [contextUser]);

    return (
        <>
            <div className="position-fixed w-202 min-vh-100 p-3 start-0 top-0 float-start">
                <div className="bg-dark bg-opacity-50 w-100 vh-pB custom-scroll rounded-4 p-1">
                    <Row className="p-1 mt-1 d-inline-flex justify-content-center m-0 w-100 border-bottom">
                        <h4 className="text-center"><img className="card-img me-2 p-1" src={logo} alt=""/><span className="text-aris">Aris</span> <span className="text-concept">Concept</span></h4>
                    </Row>
                    <Row className="my-1 mx-0 w-100 mt-2">
                        <ul className="list-group list-group-flush px-3 pt-2">
                            <LiElement isActive={idActive===1 || idActive===1001} text={'Accueil'} icon={'fa-tents color-param'}>
                                <ul className="list-group list-group-flush ps-3 pe-1">
                                    <li onClick={()=> {
                                        setActive(1)
                                        navigate("/accueil")
                                    }} className={`list-group-item ${idActive===1 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===1 ? 'link-primary-in' : ''}`}>Top Info</span>
                                        </div>
                                    </li>
                                    {contextUser?.type.idType===1 &&(
                                        <>
                                            <li onClick={()=> {
                                                setActive(1001)
                                            }} className={`list-group-item ${idActive===1001 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===1001 ? 'link-primary-in' : ''}`}>Nouveau Evenement</span>
                                                </div>
                                            </li>
                                        </>
                                    )}

                                </ul>
                            </LiElement>

                            <span className="py-3 text-light text-uppercase small fw-bold">
                                Travailleur
                            </span>

                            <LiElement isActive={idActive>3 && idActive<10} text={'Présence'} icon={'fa-calendar-check text-warning'}>
                                <ul className="list-group list-group-flush ps-3 pe-1">
                                    <li onClick={()=> {
                                        setActive(7)
                                        navigate("/employer/precence")
                                    }} className={`list-group-item ${idActive===7 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===7 ? 'link-primary-in' : ''}`}>Pointage</span>
                                        </div>
                                    </li>
                                    {contextUser?.type.idType===1 &&(
                                        <>
                                            <li onClick={()=> {
                                                setActive(8)
                                                navigate("/employer/pointage/now")
                                            }} className={`list-group-item ${idActive===8 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===8 ? 'link-primary-in' : ''}`}>Vue d'ensemble</span>
                                                </div>
                                            </li>
                                        </>
                                    )}

                                </ul>
                            </LiElement>
                            <LiElement isActive={idActive>=2 && idActive<=3 } text={'Salarié'} icon={'fa-user-tie text-aris'}>
                                <div className="">
                                    <ul className="list-group list-group-flush ps-3 pe-1">
                                        {contextUser?.type.idType===1 && (
                                            <li onClick={()=>{
                                                setActive(2)
                                                navigate("/employer/validation")
                                            }} className={`list-group-item ${idActive===2 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===2 ? 'link-primary-in' : ''}`}>Valider un Salarié</span>
                                                </div>
                                            </li>
                                        )}
                                        <li onClick={()=>{
                                            setActive(3)
                                            navigate("/employer/list")
                                        }} className={`list-group-item ${idActive===3 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                            <div className="w-100 text-center">
                                                <span className={`fs-6 fw-bold ${idActive===3 ? 'link-primary-in' : ''}`}>Liste de Salariés</span>
                                            </div>
                                        </li>
                                    </ul>
                                </div>
                            </LiElement>

                            <LiElement isActive={idActive>=10 && idActive<=13} text={'Congés'} icon={'fa-person-through-window text-concept'}>
                                <ul className="list-group list-group-flush ps-3 pe-1">
                                    <li onClick={()=>{
                                        navigate("/conge/solde")
                                        setActive(13)
                                    }} className={`list-group-item ${idActive===13 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===13 ? 'link-primary-in' : ''}`}>Mes Soldes de Congé</span>
                                        </div>
                                    </li>

                                    {contextUser?.type.idType===1 ? (
                                        <>
                                            <li onClick={()=> {
                                                navigate("conge/validation")
                                                setActive(10)
                                            }} className={`list-group-item ${idActive===10 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===10 ? 'link-primary-in' : ''}`}>Mes Demandes</span>
                                                </div>
                                            </li>

                                            <li onClick={()=> {
                                                setActive(12)
                                                navigate("/conge/planning")
                                            }} className={`list-group-item ${idActive===12 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===12 ? 'link-primary-in' : ''}`}>Planning de Congés</span>
                                                </div>
                                            </li>
                                        </>
                                    ): (
                                        ''
                                    )}
                                    <li onClick={()=>{
                                        navigate("/conge/demande")
                                        setActive(11)
                                    }} className={`list-group-item ${idActive===11 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===11 ? 'link-primary-in' : ''}`}>Faire une demande</span>
                                        </div>
                                    </li>
                                </ul>
                            </LiElement>
                            <LiElement isActive={idActive>=30 && idActive<35} text={'Paie'} icon={'fa-money-check-alt text-info-emphasis'}>
                                <ul className="list-group list-group-flush ps-3 pe-1">
                                    <li onClick={()=>{
                                        navigate("paie/bulletin")
                                        setActive(30)
                                    }} className={`list-group-item ${idActive===30 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===30 ? 'link-primary-in' : ''}`}>Mes Bulletins de Paie</span>
                                        </div>
                                    </li>

                                    {contextUser?.type.idType===1 ? (
                                        <>
                                            <li onClick={()=> {
                                                navigate("paie/validation")
                                                setActive(31)
                                            }} className={`list-group-item ${idActive===31 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===31 ? 'link-primary-in' : ''}`}>Validation de Paie</span>
                                                </div>
                                            </li>

                                            <li onClick={()=> {
                                                navigate("paie/paramettre")
                                                setActive(32)
                                            }} className={`list-group-item ${idActive===32 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                                <div className="w-100 text-center">
                                                    <span className={`fs-6 fw-bold ${idActive===32 ? 'link-primary-in' : ''}`}>Paramétre</span>
                                                </div>
                                            </li>

                                        </>
                                    ): (
                                        ''
                                    )}
                                </ul>
                            </LiElement>

                            <span className="py-3 text-light text-uppercase small fw-bold ">
                                Emploi
                            </span>
                            <LiElement isActive={idActive>=15 && idActive<18} text={'Rendu'} icon={'fa-book-open-reader text-white'}>
                                <ul className="list-group list-group-flush ps-3 pe-1">
                                    <li onClick={()=> {
                                        setActive(16)
                                        navigate("/rendu/quotidien")
                                    }} className={`list-group-item ${idActive===16 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===16 ? 'link-primary-in' : ''}`}>Rapport Quotidien</span>
                                        </div>
                                    </li>
                                    <li onClick={()=> {
                                        setActive(15)
                                        navigate("/rendu/MesRendu")
                                    }} className={`list-group-item ${idActive===15 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                        <div className="w-100 text-center">
                                            <span className={`fs-6 fw-bold ${idActive===15 ? 'link-primary-in' : ''}`}>Mes Rendus</span>
                                        </div>
                                    </li>
                                    {contextUser?.type.idType===1 && (
                                        <li onClick={()=> {
                                            setActive(17)
                                            navigate("/rendu/hebdo")
                                        }} className={`list-group-item ${idActive===17 ? 'opacity-100' : 'opacity-50'} li list-group-item-active border-0 my-1 p-0 py-2 rounded-2 cursor-pointer d-flex align-items-center`}>
                                            <div className="w-100 text-center">
                                                <span className={`fs-6 fw-bold ${idActive===17 ? 'link-primary-in' : ''}`}>Rendu Hebdo</span>
                                            </div>
                                        </li>
                                    )}

                                </ul>
                            </LiElement>
                        </ul>
                    </Row>
                </div>
            </div>
            {loading && (
                <Modal show={loading} dialogClassName="rounded-3 width-max" centered  >
                    <Modal.Body className="p-1 mb-0 rounded-3 ">
                        <div className="p-3">
                            <pre className="fs-4 m-0 p-0 ripple-text">{message}</pre>
                        </div>
                    </Modal.Body>
                </Modal>
            )}
            {contextUser?.type.idType===1 && (
                <ArisEvent show={idActive===1001} setActive={setActive}/>
            )}
        </>
    )
})
export default SlideBar