import React, {useEffect, useState} from "react";
import {Card, CardBody, CardTitle} from "react-bootstrap";
import DepModel from "../../Model/DepModel";
import { format } from 'date-fns';

const Depeche = () => {
    const [dep,setDep]=useState([])
    const [load,setLoad]=useState(true)
    useEffect(()=>{
        DepModel.getDepeche().then((res)=>{
            setDep(res)
        }).catch((e)=>{
            console.log(e.message)
        }).finally(()=>{
            setLoad(false)
        })
    },[])
    return(
        <>
            <div className="w-100 m-0 p-0 row">
                {load ? (
                    <>
                        <Card className="mb-2 mt-0 mx-0 p-0 border-0">
                            <CardTitle className="m-0 rounded-top-2 p-2 border-bottom">
                                <div className="skeleton skeleton-heading mb-0"/>
                            </CardTitle>
                            <CardBody className="rounded-bottom-2">
                                <div className="skeleton skeleton-text w-50" />
                                <div className="skeleton skeleton-text" style={{width: '100%'}}/>
                                <div className="skeleton skeleton-text" style={{width: '90%'}}/>
                            </CardBody>
                        </Card>
                        <Card className="mb-2 mt-0 mx-0 p-0 border-0">
                            <CardTitle className="m-0 rounded-top-2 p-2 border-bottom">
                                <div className="skeleton skeleton-heading mb-0"/>
                            </CardTitle>
                            <CardBody className="rounded-bottom-2">
                                <div className="skeleton skeleton-text w-50" />
                                <div className="skeleton skeleton-text" style={{width: '100%'}}/>
                                <div className="skeleton skeleton-text" style={{width: '90%'}}/>
                            </CardBody>
                        </Card>
                    </>
                ): dep.reverse().map(({ titre, contenue, dataPublication}, index)=>(
                    <Card key={index} className="mb-2 mt-0 mx-0 p-0 border-0">
                        <CardTitle className="d-flex justify-content-between m-0 rounded-top-2 p-2 border-bottom">
                        <pre className="py-0 px-2 m-0 flex-grow-1">
                            <span className="text-concept fs-5">{format(new Date(dataPublication),'HH:mm')}</span>
                            <span className="text-uppercase fw-bold fs-4"> - {titre}</span>
                        </pre>
                            <pre className="small m-0 py-0 px-2 opacity-75 fw-bolder">{format(new Date(dataPublication),'dd/MM/yyyy')}</pre>
                        </CardTitle>
                        <CardBody className="rounded-bottom-2">
                            <p className="m-0 p-0">{contenue}</p>
                        </CardBody>
                    </Card>
                ))}
            </div>
        </>
    )
}
export default Depeche