export const ViewNotifInscriptionAdmin = ({notif,close,setActive,setIdNotifClicked,setIdDeleted})=>{
    // const [show,setShow]= useState(false)
    const userProfile=useMemo(()=>{
        if (notif.notification.empResp?.profile){
            return (
                <img
                    src={APIURL()+`${notif.notification.empResp.profile}`}
                    alt=""
                    className="border-dark-light rounded-circle mt-0 ms-2 p-0"
                    width={50} height={50}
                    style={{ objectFit: 'cover'}}
                    decoding={"async"}
                    // onClick={handleClick}
                />
            )
        }else{
            return (<i  className={`far ms-2 icon-20 fa-user-circle  text-concept`}/>)
        }
    },[notif.notification.empResp])
    const navigate = useNavigate()

    const send = useCallback(
        () => {
            setActive(2)
            navigate(`/employer/validation#${notif.notification.empResp.idEmp}`)
            close()
            if (notif.notification.dateVue ===null){
                setIdNotifClicked(notif.notification.id)
                Notification.setVue(notif.notification.id)
                    .then(()=>{setIdNotifClicked(notif.notification.id)})
                    .catch(()=>{setIdNotifClicked(-100)})
            }
        },
        [notif.notification],
    );

    const deleteNotif = useCallback(
        () => {
            setIdDeleted(notif.idTuteurNotif)
            Notification.deleteNotif(notif.idTuteurNotif)
                .then(()=>{
                    setIdDeleted(notif.idTuteurNotif)
                })
                .catch(()=>{
                    setIdDeleted(-100)
                })
        },
        [notif.notification],
    );

    return(
        <>
            {/*<div onMouseEnter={()=>setShow(true)} onMouseLeave={()=>setShow(false)} className={`card ${notif.notification.dateVue ? 'bg-body' : 'bg-grey'} mb-2 p-0 border-1 border-primary`}>*/}
            <div className={`card ${notif.notification.dateVue ? 'bg-body' : 'bg-grey'} mb-2 p-0 border-1 border-primary position-relative`}>
                <div onClick={()=>deleteNotif()} className="position-absolute end-0 top-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer" style={{transform: 'translate(0.3rem,-0.5rem)', width: '25px', height: '25px'}}>
                    <i className="fa-solid fa-xmark  text-dark-emphasis"/>
                </div>
                <div onClick={send} className={`card-body ${notif.notification.dateVue ? 'bg-body' : 'bg-grey'} rounded-2 cursor-pointer`}>
                    <div className="w-100 d-inline-flex justify-content-between pb-2 border-bottom border-1 mb-2">
                        <strong>{notif.notification.titreNotif.titre}</strong>
                        <small className="small text-print">{formatDate(notif.notification.dateInsert)}</small>
                    </div>
                    <div className="d-inline-flex justify-content-around">
                        <div className="d-flex align-items-center me-2">
                            {userProfile}
                        </div>
                        <div className="flex-grow-1">
                            {notif.notification.messageFinal}
                        </div>
                    </div>
                </div>
                {/*<div className={`card-footer d-inline-flex justify-content-between ${show? 'd-block' : 'd-none'}`} >*/}
                {/*    <button type="button" className="btn btn-outline-success border-0" style={{letterSpacing: '0.07rem'}}><strong className="p-3">Accepter</strong></button>*/}
                {/*    <button type="button" className="btn btn-outline-danger border-0" style={{letterSpacing: '0.07rem'}}><strong className="p-3">Supprimer</strong></button>*/}
                {/*</div>*/}
            </div>
        </>
    )
}

export const ViewNotifPaieEmp = ({setActive,close,setIdNotifClicked,setIdDeleted,notif})=>{
    const deleteNotif = useCallback(
        () => {
            setIdDeleted(notif.idTuteurNotif)
            Notification.deleteNotif(notif.idTuteurNotif)
                .then(()=>{
                    setIdDeleted(notif.idTuteurNotif)
                })
                .catch(()=>{
                    setIdDeleted(-100)
                })
        },
        [notif.notification],
    );
    const navigate = useNavigate()
    const send = useCallback(
        () => {
            setActive(30)
            navigate(`/paie/bulletin#${notif.notification.empResp.idEmp}`)
            close()
            if (notif.notification.dateVue ===null){
                setIdNotifClicked(notif.notification.id)
                Notification.setVue(notif.notification.id)
                    .then(()=>{setIdNotifClicked(notif.notification.id)})
                    .catch(()=>{setIdNotifClicked(-100)})
            }
        },
        [notif.notification],
    );
    return(
        <>
            <div className={`card ${notif?.notification.dateVue ? 'bg-body' : 'bg-grey'} mb-2 p-0 border-1 border-success position-relative`}>
                <div onClick={()=>deleteNotif()} className="position-absolute end-0 top-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer" style={{transform: 'translate(0.3rem,-0.5rem)', width: '25px', height: '25px'}}>
                    <i className="fa-solid fa-xmark  text-dark-emphasis"/>
                </div>
                <div onClick={send} className={`card-body ${notif.notification.dateVue ? 'bg-body' : 'bg-grey'} rounded-2 cursor-pointer`}>
                    <div className="w-100 d-inline-flex justify-content-between pb-2 border-bottom border-1">
                        <strong>Bulletin de Paie</strong>
                        <small className="small text-print">{new Date(notif?.notification.dateInsert).toLocaleDateString()}</small>
                    </div>
                    <div className="d-inline-flex justify-content-around">
                        <div className="d-flex align-items-center me-2">
                            <i className="fa ms-2 icon-30 fa-money-bill text-success"/>
                        </div>
                        <div className="flex-grow-1">
                            {notif?.notification.messageFinal}
                        </div>
                    </div>
                </div>
            </div>
        </>
    )
}

