import {APIURL} from "./APIURL";
import axios from "axios";

export default class RenduFile {
    id
    reference;
    fileNames;

    static uploadFiles = async (reference, files, idUser) => {
        const formData = new FormData();

        files.forEach(file => {
            formData.append("files", file);
        });

        formData.append("reference", reference);
        formData.append("idUser", idUser);
        const token = await window.electronStore.get('token');
        const response = await fetch(APIURL()+"renduFile/upload", {
            method: "POST",
            headers: {
                "Authorization": `Bearer ${token}`,
            },
            body: formData,
        });

        if (response.ok) {
            const result = await response.text();
            return result;
        } else {
            throw new Error("Erreur lors de l'upload des fichiers");
        }
    }

    static getAllByUser = async (month,year,idEmp) => {

        const token = await window.electronStore.get('token');
        const response = await fetch(APIURL()+`renduFile/${idEmp}/${month}/${year}`, {
            method: "get",
            headers: {
                "Authorization": `Bearer ${token}`,
            },
        });

        if (response.ok) {
            const result = await response.json();
            return result;
        } else {
            throw new Error("Erreurs lors de l'initialisation des données");
        }
    };


    static getFileWeek = async (start,end,idEmp) => {
        const token = await window.electronStore.get('token');
        const response = await fetch(`${APIURL()}renduFile/week?idEmploye=${idEmp}&startDate=${start}&endDate=${end}`, {
            method: "get",
            headers: {
                "Authorization": `Bearer ${token}`,
            },
        });

        if (response.ok) {
            const result = await response.json();
            return result;
        } else {
            throw new Error("Erreurs lors de l'initialisation des données");
        }
    }


    static downloadFileWithAxios = async ( fileName) => {

        const response = await axios.get(APIURL()+fileName, {
            responseType: 'blob',
        });

        const blob = response.data;
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

}