import React, {useCallback, useEffect, useState} from "react";
import {Dropdown, Form, InputGroup, Modal, Toast} from "react-bootstrap";
import {userProfile} from "./Parameter/PersIndView";
import Pagination from "../Main/Utilitaire/Pagination";
import {SalaireBase} from "../../Model/Paie/SalaireBase";
import {normalizeString} from "../Rendu/Hebdo";
import {formatNumber, formatNumberDouble} from "./Parameter/ViewSalaireBrute";
import FicheDePaie from "./FicheDePaie";

export const apaye=(element)=>{
    if (element){
        let a = 0
        a=-(element.acompte.adeduire+element.pret.adeduire+element.ostie.adeduire+element.cnaps.adeduire)+(element.salaireBase.apaye+element.prime.apaye+element.indemnite.apaye)
        element.irsa.map((irsa)=>{
            a-=irsa.adeduire
        })
        if (a<0){
            return 0
        }
        return a
    }
    return 0

}

const ValidationPaie = ()=>{
    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [post, setPost] = useState('');
    const [filtered, setFiltered] = useState([]);
    const [allData, setAllData] = useState([]);
    useEffect(() => {

        SalaireBase.getAllFiches().then((res)=>{
            // console.log(res)
            setAllData(res)
        }).catch(()=>{})
    }, []);

    const [paginate, setPaginate] = useState(1);
    // const [date, setDate] = useState(new Date());
    // const formatMonth = useCallback((dt) => {
    //     if (!dt) return;
    //
    //     const df = new Date(dt);
    //     return `${df.getFullYear().toString().padStart(4, "0")}-${String(df.getMonth() + 1).padStart(2, "0")}`;
    // }, []);
    useEffect(() => {
        let data = allData;
        if (matricule) {
            data = allData.filter(({emp}) =>{
                if (emp.employe.matricule){
                    return emp.employe.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter(({emp}) =>
                emp.employe.nom.toLowerCase().includes(nom.toLowerCase()) ||
                emp.employe.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        if (post){
            data = data.filter(({emp})=>normalizeString(emp.employe.type.poste.toLowerCase()).includes(normalizeString(post.toLowerCase())))
        }
        setFiltered(data)
    }, [allData, matricule, nom, post]);

    const [show, setShow] = useState(false);
    const [elementClicked, setElementClicked] = useState(null);
    const viewDetail = useCallback(
        (element) => {
            setShow(true)
            setElementClicked(element)
        },
        []
    );
    const [erreur, setErreur] = useState(false);
    const [errorMessage, setErrorMessage] = useState('');
    const validation = useCallback(
        (element) => {
            SalaireBase.addFichePaie(element).then(()=>{
                setAllData((prev)=>prev.map((e)=>e.emp.idRh===element.emp.idRh ? ({...e, valider: true}) : e))
            }).catch((error)=>{
                console.log(error.message)
                setErreur(true)
                setErrorMessage(error.message)
            })
        },
        []
    );


    return(
        <>
            <div className="card w-100 mb-2">
                <div className="card-body pt-1 pb-1">
                    <h3 className="text-center">Liste des Salariés</h3>
                    <div className="row m-0 p-0">
                        <div className="col-3">
                            <InputGroup className="my-3">
                                <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                                <Form.Control
                                    placeholder="matricule"
                                    aria-label="matricule"
                                    aria-describedby="basic-addon1"
                                    type="search"
                                    value={matricule}
                                    onChange={(event)=>{
                                        setMatricule(event.target.value.replace(/\D/g, ''))
                                    }}
                                />
                            </InputGroup>
                        </div>
                        <div className="col-5">
                            <InputGroup className="my-3">
                                <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                                <Form.Control
                                    placeholder="nom ou prénom"
                                    aria-label="nom"
                                    aria-describedby="nom"
                                    type="search"
                                    value={nom}
                                    onChange={(event) => setNom(event.target.value)}
                                />
                            </InputGroup>
                        </div>
                        <div className="col-4">
                            <InputGroup className="my-3">
                                <InputGroup.Text id="basic-addon1">Poste</InputGroup.Text>
                                <Form.Control
                                    placeholder="nom ou prénom"
                                    aria-label="nom"
                                    aria-describedby="nom"
                                    type="search"
                                    value={post}
                                    onChange={(event) => setPost(event.target.value)}
                                />
                            </InputGroup>
                        </div>
                    </div>
                </div>
            </div>

            {/*<div className="w-100 mb-3 d-inline-flex justify-content-between">*/}
            {/*    <span className="fs-4 fw-bolder">Mois du {date ? date.toLocaleDateString("fr-FR",  { month: "short", year: "numeric" }) : '------/----'}</span>*/}
            {/*    <InputGroup size={"sm"} className="" style={{width: '16vw'}}>*/}
            {/*        <InputGroup.Text id="basic-addon1">Mois du</InputGroup.Text>*/}
            {/*        <Form.Control*/}
            {/*            aria-label="semaine"*/}
            {/*            aria-describedby="basic-addon1"*/}
            {/*            type="month"*/}
            {/*            size={"sm"}*/}
            {/*            value={formatMonth(date)}*/}
            {/*            onChange={(e) => {*/}
            {/*                const strDt = e.target.value.split("-");*/}
            {/*                let newDate*/}
            {/*                if (date){*/}
            {/*                    newDate = new Date(date);*/}
            {/*                }else{*/}
            {/*                    newDate = new Date()*/}
            {/*                }*/}
            {/*                newDate.setFullYear(Number(strDt[0]));*/}
            {/*                newDate.setMonth(Number(strDt[1]) - 1);*/}
            {/*                setDate(newDate);*/}
            {/*            }}*/}
            {/*        />*/}
            {/*    </InputGroup>*/}
            {/*</div>*/}

            <div className="m-0 w-100 rounded-3 bg-white">
                <div className="rounded-3 p-1 m-0 w-100">
                    <table className="table mb-0 table-striped table-hover table-sm">
                        <thead>
                        <tr className="text-center">
                            <th scope="col"/>
                            <th scope="col">M°</th>
                            <th scope="col">Nom</th>
                            <th scope="col">Prenom</th>
                            <th scope="col">Poste</th>
                            <th scope="col">Status</th>
                            <th scope="col" className="text-center">À PAYER</th>
                            <th scope="col"/>

                        </tr>
                        </thead>
                        <tbody>
                        {filtered.slice((paginate-1)*10,(paginate)*10).map((element)=>(
                            <tr key={element.idFicheDePaie} className="cursor-pointer" >
                                <td>
                                    {userProfile(element.emp.employe)}
                                </td>
                                <th scope="row">{String(element.emp.employe.matricule).padStart(4, '0')}</th>
                                <td>{element.emp.employe.nom}</td>
                                <td>{element.emp.employe.prenom}</td>
                                <td>{element.emp.employe.type.poste}</td>
                                <td style={{height: '40px'}}>
                                    {element.valider ? (
                                        <div className="bg-success text-white d-flex w-100 h-100 m-0 justify-content-center align-items-center rounded-3">
                                            VALIDER
                                        </div>
                                    ): (
                                        <div className="bg-dark text-danger d-flex w-100 h-100 m-0 justify-content-center align-items-center rounded-3">
                                            NON_VALIDER
                                        </div>
                                    )}
                                </td>
                                <td className="text-center text-print fw-bold">{formatNumberDouble(apaye(element))}</td>
                                <td className="text-end">
                                    <Dropdown>
                                        <Dropdown.Toggle
                                            id={`dropdown-${1}`}
                                            as={"span"}
                                            className="py-2 px-3 rounded-3 bg-secondary-subtle d-inline-flex hover-span cursor-pointer"
                                            style={{zIndex: '1'}}
                                        >
                                            <i className="fa fa-ellipsis-v"/>
                                        </Dropdown.Toggle>
                                        {!element.valider && (
                                            <Dropdown.Menu style={{zIndex: '3'}}>
                                                <Dropdown.Item className="bg-success text-white text-center mb-2 hover-span" onClick={()=>validation(element)}>
                                                    <i className="fa fa-check-to-slot me-1"/>Valider
                                                </Dropdown.Item>
                                                <Dropdown.Item className="text-white bg-primary text-center hover-span" onClick={()=>viewDetail(element)}>
                                                    <i className="fa fa-user-edit me-1"/>Detail
                                                </Dropdown.Item>
                                            </Dropdown.Menu>
                                        )}

                                    </Dropdown>
                                </td>
                            </tr>
                        ))}
                        </tbody>

                    </table>
                </div>
                <div className="d-flex justify-content-end w-100 m-0 p-2">
                    <Pagination length={filtered.length % 10 === 0 ? filtered.length / 10 : Math.floor(filtered.length / 10) + 1} active={paginate} setActive={setPaginate}/>
                </div>
            </div>

            <Modal
                show={show}
                onHide={()=>setShow(false)}
                keyboard={false}
                backdrop="static"
                dialogClassName=" position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center width-max"
            >
                <Modal.Header className="position-relative">
                    <div onClick={()=>setShow(false)} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="pt-1">
                    <FicheDePaie element={elementClicked} />
                </Modal.Body>
            </Modal>
            {erreur && (
                <div className="position-fixed bottom-0 end-0 width-max p-2">
                    <Toast bg={"danger"} show={erreur} onClose={()=>setErreur(false)} autohide delay={5000}>
                        <Toast.Header>
                            <i className="rounded me-2 text-aris icon-30 fas fa-circle-exclamation"/>
                            <strong className="me-auto">Erreur</strong>
                            <small className="text-muted">Maintenant</small>
                        </Toast.Header>
                        <Toast.Body className><strong>{errorMessage}</strong></Toast.Body>
                    </Toast>
                </div>
            )}
        </>
    )
}

export default ValidationPaie