import {APIURL} from "./APIURL";
import axios from "axios";

export class Message {
    static async getMyMessages(idEmp){
        const response = await fetch(APIURL() + "message/"+idEmp , {
            method: 'get',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": 'Bearer '+ await window.electronStore.get('token'),
            },
        });

        if (response.ok) {
            return await response.json()
        }else{
            throw new Error('On ne peut pas faire cette requête pour le moment!');
        }
    }

    static async getPrevMessage(idSender, idReceiver, dateLast) {
        try {
            const response = await axios.get(APIURL() + "message/prev", {
                params: {
                    senderId: idSender,
                    receiverId: idReceiver,
                    lastDate: dateLast,
                },
                headers: {
                    Authorization: `Bearer ${await window.electronStore.get('token')}`,
                }
            });

            if (response.status === 200) {
                return response.data;
            } else {
                throw new Error("Échec de la récupération des messages précédents");
            }
        } catch (error) {
            console.error("Erreur lors du chargement des messages :", error);
            throw new Error("Problème de connexion au serveur");
        }
    }

}