import React, {Fragment, useCallback, useContext, useEffect, useMemo, useRef, useState} from "react";
import {
    Badge,
    Modal,
    Offcanvas,
    Overlay,
    Popover,
    PopoverBody, ProgressBar,
    Toast
} from "react-bootstrap";
import {Routes} from "../../Route/Route";
import {useNavigate} from "react-router-dom";
import LoginMD from "../../Model/LoginMD";
import Modif from "./Utilitaire/Modif";
import {UserContext} from "./Utilitaire/UserProvider";
import {APIURL} from "../../Model/APIURL";
import {
    ViewNotifCongeAdmin,
    ViewNotifCongeEmp,
    ViewNotifInscriptionAdmin,
    ViewNotifPaieEmp, ViewNotifRenduAdmin, ViewNotifRenduNonFait
} from "../Notification/Viewnotif";
import useWebSocket from "../../WS/useWebSocket";
import Notification from "../../Model/Notification";
import DialogMessage from "../Message/DialogMessage";

const Header = React.memo(({idActive,setActive}) => {
    const { user, setUser, setIsModif } = useContext(UserContext);
    const [show, setShow] = useState(false);
    const handleClose = () => setShow(false);


    const [showMessage, setShowMessage] = useState(false);
    const handleCloseMessage = () => setShowMessage(false);
    const handleShowMessage = () => setShowMessage(true);

    const [showUser, setShowUser] = useState(false);
    const [target, setTarget] = useState(null);

    const handleClick = useCallback((event) => {
        setShowUser(!showUser);
        setTarget(event.target);
    },[])

    const [icon,setIcon]=useState('')
    const [labels,setLabels]=useState([])

    useEffect(()=>{
        const route = Routes.find((e)=>e.id === idActive)
        if (route){
            setIcon(route?.icon)
            setLabels(route?.labels)
        }
    },[idActive])
    const scrollToTop = () => {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    };

    const [hasShadow, setHasShadow] = useState(false);

    const handleScroll = () => {
        if (window.scrollY > 0) {
            setHasShadow(true);
        } else {
            setHasShadow(false);
        }
    };
    const navigate=useNavigate()
    useEffect(() => {
        window.addEventListener('scroll', handleScroll);
        return () => {
            window.removeEventListener('scroll', handleScroll);
        };
    }, []);
    const [erreur,setErreur]=useState(false)
    const [erreurText,setErreurText]=useState('')
    const logOut = () => {
        console.log("open log out...")
        LoginMD.logout().then((res)=>{
            if (res){
                localStorage.clear()
                window.electronStore.clear()
                navigate("/")
            }
        }).catch((e)=>{
            setErreur(true)
            setErreurText(e.message)
            navigate("/")
        })
    }



    const getAllNotif = useCallback(
        () => {
            if (user){
                Notification.allNotif(user?.idEmp)
                    .then((resp)=>{
                        //on compte les resp non open
                        const unreadNotifications = resp.filter(({open}) => !open);
                        setNbNewNotif(unreadNotifications.length)
                        setNotifs(resp)
                    })
                    .catch((e)=>{
                        console.log(e)
                        console.log("erreur lors de initialisation du notification")
                    })
            }
        },
        [user],
    );

    useEffect(() => {
        getAllNotif()
    }, [user]);


    const [showModif,setShowModif]=useState(false)

    const [showUpdate,setShowUpdate]=useState(false)
    const [status,setStatus]=useState(0)
    const [message,setMessage]=useState('')
    const handleCheckUpdate = () => {
        setShowUpdate(true)
        window.checkUpdate.update()
        setShowUser(false)
    }
    useEffect(() => {
        window.checkUpdate.onUpdateStatus((event, message) => {
           setMessage(message)
        });
        return () => {
            window.checkUpdate.removeStatusListener();
        };
    }, []);

    useEffect(() => {
        window.checkUpdate.statusUpdate((event, status) => {
            setStatus(status)
        });
        return () => {
            window.checkUpdate.removeStatusUpdateListener();
        };
    }, []);
    useEffect(()=>{
        if (status < 0) {
            const timer = setTimeout(() => {
                setShowUpdate(false);
            }, 3000);
            return () => clearTimeout(timer);
        }
    },[status])
    useEffect(()=>{
        if(showUser && showModif){
            setShowUser(false)
        }
    },[showModif])

    const userProfile=useMemo(()=>{
        if (user?.profile){
            return (
                <img
                    src={APIURL()+`${user.profile}`}
                    alt=""
                    className="border-dark-light rounded-circle mt-0 mx-2 p-0"
                    width={40} height={40}
                    style={{ objectFit: 'cover'}}
                    onClick={handleClick}
                />
            )
        }else{
            return (
                <span className="cursor-pointer position-relative d-flex justify-content-center bg-secondary mx-2 border-dark-light rounded-circle" style={{width:'42px', height: '42px'}} onClick={handleClick}>
                    <i className={`far icon-20 fa-user-circle  my-auto ${user===null ? 'text-concept': 'text-white'}`}/>
                </span>
                // <i onClick={handleClick} className={`far ms-2 icon-20 fa-user-circle ${user===null ? '': 'text-concept'}`}/>
            )
        }

    },[user])
    const spanRef = useRef(null);

    const [notifs,setNotifs]=useState([])
    const [nbNewNotif,setNbNewNotif]=useState(0)


    const {body} = useWebSocket(user ? "/notif/all/" + user?.idEmp : null)
    useEffect(()=>{
        if (body){
            setNbNewNotif(prevState => prevState+1)
            setNotifs(prevState => [body,...prevState])
            window.notification.showNotification(body.notification?.titreNotif?.titre, body.notification?.messageFinal,new Date())
        }
    },[body])
    useEffect(() => {
        window.badge.setBadge(nbNewNotif)
    }, [nbNewNotif]);


    const handleShow = useCallback(
        () => {
            setShow(true)
            if (user && nbNewNotif>0){
                Notification.openNotif(user.idEmp)
                    .then(()=>{
                        setNbNewNotif(0)
                        setNotifs((prev) =>
                            prev.map((notif) => ({
                                ...notif,
                                open: true,
                            }))
                        );
                    })
                    .catch((e)=>{
                        console.log(e)})
            }
        },
        [user,nbNewNotif],
    );

    const [isAll, setIsAll] = useState(true);
    const [dataShow, setDataShow] = useState([]);
    const [idNotifClicked, setIdNotifClicked] = useState(-100);
    const [idDeleted, setIdDeleted] = useState(-100);

    useEffect(() => {
        if (idDeleted>0){
            setNotifs((prevNotifs) => prevNotifs.filter(element => element.idTuteurNotif !== idDeleted));
        }
    }, [idDeleted]);

    const scroll = useCallback(
        () => {
            const element = document.getElementById("bodyScroll")
            if (element) {
                setTimeout(() => {
                    const firstChild = element.querySelector(":scope > *")
                    if (firstChild) {
                        firstChild.scrollIntoView({ behavior: "smooth", block: "start" })
                    }
                }, 100)
            }
        },
        [],
    );


    useEffect(() => {
        if (!isAll){
            setDataShow(notifs.filter((data)=>data.notification.dateVue ===null))
        }else{
            setDataShow([...notifs])
        }
       scroll()
    }, [isAll,notifs]);

    useEffect(()=>{
        if (idNotifClicked>0){
            setNotifs((prev) =>
                prev.map((notif) =>
                    notif.notification.id === idNotifClicked
                        ? {
                            ...notif,
                            notification: {
                                ...notif.notification,
                                dateVue: new Date().toISOString()
                            }
                        }
                        : notif
                )
            );
        }
    },[idNotifClicked])

    const [statut, setStatut] = useState(0);

    return(
        <>
            <div className={`p-2 top-2 start-2 ${hasShadow ? 'bg-grey text-white' : 'bg-white bg-opacity-50'} shadow-lg rounded-3 position-fixed z-3 fw-bolder small d-inline-flex justify-content-between w-rest-p align-content-stretch align-items-center`} style={{minHeight: '70px'}}>
                <ul className="list-group list-group-horizontal d-inline-flex align-items-center h-100 bg-transparent">
                    <li className="list-group-item border-0 pe-0 bg-transparent"> <i className={`fas px-1 ${icon}`}/></li>
                    <li className="list-group-item border-0 pe-0 bg-transparent">/</li>
                    {labels.map((string,index)=>(
                        index<(labels.length - 1) ? (
                            <Fragment key={`${index}-fragment`}>
                                <li key={index} onClick={scrollToTop} className="list-group-item border-0 pe-0 bg-transparent cursor-pointer text-light-emphasis">{string}</li>
                                <li key={`${index}-slash`} className="list-group-item border-0 pe-0 bg-transparent">/</li>
                            </Fragment>
                        ) : (
                            <li key={index} className="list-group-item border-0 pe-0 bg-transparent cursor-pointer text-uppercase fw-bolder">{string}</li>
                        )
                    ))}
                </ul>
                <div className="h-100 d-inline-flex justify-content-between align-items-center">
                    <span className="cursor-pointer position-relative d-flex justify-content-center align-items-center bg-secondary me-2 border-dark-light rounded-circle" style={{width:'42px', height: '42px'}} onClick={handleShowMessage}>
                        {statut>0 && (
                            <Badge className="position-absolute top-0 end-3" bg="danger">{statut}</Badge>
                        )}
                        <i className="far icon-20 my-auto fa-message text-white"/>
                    </span>
                    <span className="cursor-pointer position-relative d-flex justify-content-center bg-secondary align-items-center mx-2 border-dark-light rounded-circle" style={{width:'42px', height: '42px'}} onClick={handleShow}>
                        {nbNewNotif !==0 && (
                            <Badge className="position-absolute top-0 end-3" bg="danger">{nbNewNotif}</Badge>
                        )}
                        <i className="far icon-20 fa-bell text-white my-auto"/>
                    </span>
                    <span className="h-100 cursor-pointer position-relative " ref={spanRef}>
                        {userProfile}
                        <Overlay show={showUser} target={target} placement="bottom" container={spanRef} containerPadding={20} rootClose={true} transition={false} onHide={()=>setShowUser(false)}>
                            <Popover  id="popover-basic" className="bg-transparent rounded-2 border-0">
                                <PopoverBody className="p-0 m-0 width-max bg-transparent border border-1 rounded-3" as="div">
                                    <h5 className="p-3 pb-2 bg-light rounded-top-3 mb-0 fs-6 text-center">
                                        <span className="text-uppercase text-lowercase">
                                             {user?.nom}
                                        </span>
                                        <p className="m-0 p-0 pt-1 text-center text-capitalize">{user?.prenom}</p>
                                    </h5>
                                    <ul className="list-group list-group-flush rounded-bottom-3 w-100 m-0">
                                        <li className="list-group-item fw-bolder link-primary-in" onClick={()=>setShowModif(true)}>Modifier mes Infos</li>
                                        <li className="list-group-item fw-bolder link-primary-in">Régles interne</li>
                                        <li className="list-group-item fw-bolder link-primary-in" onClick={()=>logOut()}>Déconnexion</li>
                                        <li className="list-group-item fw-bolder link-primary-in" onClick={handleCheckUpdate}>Mise à jour du logiciel</li>
                                    </ul>
                                </PopoverBody >
                            </Popover>
                        </Overlay>
                    </span>
                </div>
            </div>

            <Offcanvas show={show} onHide={handleClose} placement={'end'}>
                <Offcanvas.Header closeButton>
                    <Offcanvas.Title>Notification</Offcanvas.Title>
                </Offcanvas.Header>
                <div className="w-100 d-inline-flex mb-2">
                    <span onClick={()=> {
                        scroll()
                        setIsAll(true)
                    }} className={`mx-2 cursor-pointer px-3 py-2 rounded-pill border bg-dark text-white btn shadow ${isAll ? 'scale-2 border-2' : 'scale-1 border-1'}`}>Tout</span>
                    <span onClick={()=> {
                        scroll()
                        setIsAll(false)
                    }} className={`mx-2 cursor-pointer px-3 py-2 rounded-pill border  bg-grey  text-concept btn shadow ${isAll ? 'scale-1 border-1': 'scale-2 border-2'}`}>Non lu</span>
                </div>
                <Offcanvas.Body id="bodyScroll" className="px-1 rounded-start-4 rounded-end-4 overflow-x-hidden">
                    {dataShow.map((obj)=>{
                        if (obj.notification.titreNotif.id ===1){
                            return(
                                <ViewNotifCongeAdmin key={obj.notification.id} notif={obj} close={handleClose}/>
                            )
                        }else if(obj.notification.titreNotif.id ===2){
                            return (
                                 <ViewNotifInscriptionAdmin setIdDeleted={setIdDeleted} setIdNotifClicked={setIdNotifClicked} key={obj.notification.id} notif={obj} close={handleClose} setActive={setActive}/>
                            )
                        } else if(obj.notification.titreNotif.id ===3 || obj.notification.titreNotif.id ===4){
                            return (
                                 <ViewNotifCongeEmp key={obj.notification.id} notif={obj} close={handleClose}/>
                            )
                        }else if(obj.notification.titreNotif.id ===5){
                            return (
                                 <ViewNotifPaieEmp key={obj.notification.id} notif={obj} setIdDeleted={setIdDeleted} setIdNotifClicked={setIdNotifClicked} close={handleClose} setActive={setActive}/>
                            )
                        }
                        else if(obj.notification.titreNotif.id ===6){
                            return (
                                 <ViewNotifRenduNonFait key={obj.notification.id} notif={obj} close={handleClose}/>
                            )
                        }else{
                            return (
                                 <ViewNotifRenduAdmin key={obj.notification.id} notif={obj} close={handleClose}/>
                            )
                        }

                    })}
                   {/*<ViewNotifCongeAdmin/>*/}
                   {/* <ViewNotifInscriptionAdmin/>*/}
                   {/* <ViewNotifCongeEmp/>*/}
                   {/* <ViewNotifPaieEmp/>*/}
                   {/* <ViewNotifRenduNonFait/>*/}
                   {/* <ViewNotifRenduAdmin/>*/}
                </Offcanvas.Body>
            </Offcanvas>

            <DialogMessage showMessage={showMessage} hide={handleCloseMessage} user={user} setStatut={setStatut}/>
            <Modal
                show={showUpdate}
                onHide={()=>setShowUpdate(false)}
                keyboard={false}
                size={"lg"}
            >
                <Modal.Header closeButton>
                    <Modal.Title>Mise à jour du logiciel</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    {status===2 ? (
                        <ProgressBar now={message} label={`${message} %`} />
                    ): (message)}
                </Modal.Body>
            </Modal>
            {showModif && (
                <Modif show={showModif} close={()=>setShowModif(false)} object={user} isModifier={setIsModif}/>
            )}
            <div className="position-fixed bottom-0 end-0 width-max p-2">
                <Toast bg={"danger"} show={erreur} onClose={()=>setErreur(false)} autohide delay={5000}>
                    <Toast.Header>
                        <i className="rounded me-2 text-aris icon-30 fas fa-circle-exclamation"/>
                        <strong className="me-auto">Erreur</strong>
                        <small className="text-muted">Maintenant</small>
                    </Toast.Header>
                    <Toast.Body className><strong>{erreurText}</strong></Toast.Body>
                </Toast>
            </div>
        </>
    )
})

export default Header