import React, {useEffect, useState} from "react";
import Optimisation from "./Optimisation";
import PolModel from "../../Model/PolModel";

const Economie = () => {
    const [load,setLoad]=useState(true)
    const [pol,setPol]=useState([])
    useEffect(()=>{
        setLoad(true)
        PolModel.getEconomie().then((res)=>{
            setPol(res)
        }).catch((e)=>{
            console.log(e.message)
        }).finally(()=>{
            setLoad(false)
        })
    },[])
    return(
        <Optimisation load={load} pol={pol}/>
    )
}
export default Economie