import {useCallback, useState} from "react";

const timeLabels = (initH, endH) => {
    const start = new Date();
    start.setHours(initH, 0, 0, 0);
    const end = new Date();
    end.setHours(endH, 0, 0, 0);
    const labels=[];
    while (start <= end) {
        labels.push(start.toTimeString().slice(0, 5));
        start.setMinutes(start.getMinutes() + 30);
    }
    return labels;
};
const toMinutes = (time) => {
    const [h, m] = time.split(":").map(Number);
    return h * 60 + m;
};


const AxeHoraire = ({ actifs, inactifs, initH, endH, pointage })=>{
    const labels = timeLabels(initH, endH);
    const segmentWidth = 55;
    const height = 10;
    const tickHeight = 6;

    const conf= useCallback((start, end)=>{
        const minStart = toMinutes(start)
        const minEnd = toMinutes(end)

        const xInit = toMinutes(`${initH}:00`)

        const w = ((minEnd - minStart)/30)*segmentWidth
        return {x: (((minStart - xInit)/30)*segmentWidth)+(segmentWidth / 2), w: w>0 ? w : 0}
    }, [segmentWidth, initH]);

    const [startPointage, setStartPointage] = useState({
        st: conf(`${initH}:00`, pointage.dateDebut),
        ed: conf(pointage.dateFin, `${endH}:00`)
    });
    return (
        <svg width={(labels.length) * segmentWidth} height={height + 20}>
            {labels.map((time, index) => {
                const x = index * segmentWidth;
                const centerX = x + segmentWidth / 2;
                return (
                    <g className="" key={time}>
                        {index===0 ? (
                            <rect x={x} y={0} width={segmentWidth/2} height={height} fill={"#f3f1ee"} />
                        ): index===1 ? (
                            <rect x={x-segmentWidth / 2} y={0} width={segmentWidth+segmentWidth / 2} height={height} fill={"#fd7e14"} />
                        ): index===labels.length-1 ? (
                            <rect x={x+segmentWidth / 2} y={0} width={segmentWidth/2} height={height} fill={"#f3f1ee"} />
                        ): index===labels.length-2 ? (
                            <rect x={x} y={0} width={segmentWidth+segmentWidth / 2} height={height} fill={"#fd7e14"} />
                        ): (
                            <rect x={x} y={0} width={segmentWidth} height={height} fill={"#fd7e14"} />
                        )}
                        <line
                            x1={centerX}
                            y1={height}
                            x2={centerX}
                            y2={height + tickHeight}
                            stroke="#000"
                            strokeWidth="0.5"
                        />
                        <text x={x + segmentWidth / 2} y={height + 12} fontSize={10} textAnchor="middle" fill="#000">
                            {time}
                        </text>
                        {index < labels.length - 1 && (
                            <line
                                x1={x + segmentWidth}
                                y1={height}
                                x2={x + segmentWidth}
                                y2={height +( tickHeight+3) / 2}
                                stroke="#000"
                                strokeWidth="0.6"
                            />
                        )}
                    </g>
                );
            })}
            {inactifs.map(({start, end}, index) => {
                const param = conf(start,end)
                return (
                    <g className="" key={index}>
                        <rect x={param.x} y={0} width={param.w} height={height} fill={"#a73728"} />
                    </g>
                );
            })}
            {actifs.map(({start, end}, index) => {
                const param = conf(start,end)
                return (
                    <g className="" key={index}>
                        <rect x={param.x} y={0} width={param.w} height={height} fill={"#28a745"} />
                    </g>
                );
            })}
            {pointage &&  (
                <g className="">
                    <rect x={startPointage.st.x} y={0} width={startPointage.st.w} height={height} fill={"#0e0202"} />
                    <rect x={startPointage.ed.x} y={0} width={startPointage.ed.w} height={height} fill={"#0e0202"} />
                </g>
            )}
        </svg>
    );
}
export default AxeHoraire;