import React, {useMemo} from "react";

const ViewTitleRendu = ({date, setDateClicked})=>{
    const title=useMemo(() => {
        const options = { day: 'numeric', month: 'long', year: 'numeric' };
        return {
            monday: date.Monday.toLocaleDateString('fr-FR', {day: 'numeric'}),
            friday: date.Friday.toLocaleDateString('fr-FR', options),
        };
    }, [date]);
    return (
        <div className="col-4 mb-3 ps-0 ms-0 ">
            <div onClick={()=>{setDateClicked(()=>({monday: date.Monday, friday: date.Friday}))}} className="card rounded-4 h-100 cursor-pointer shadow-lg btn">
                <div className="card-body d-flex justify-content-center align-items-center">
                    <h5>Rendu du {title.monday} au {title.friday}</h5>
                </div>
            </div>
        </div>
    )
}

export default ViewTitleRendu