import React, {useCallback, useContext, useEffect, useLayoutEffect, useMemo, useState} from "react";
import {Dropdown} from "react-bootstrap";
import EtatEmployer from "../../../Model/EtatEmployer";
import VoirInfo from "./VoirInfo";
import {APIURL} from "../../../Model/APIURL";
import {useLocation, useNavigate } from "react-router-dom";
import useWebSocket from "../../../WS/useWebSocket";
import {UserContext} from "../Utilitaire/UserProvider";
import { ConfirmDialog, confirmDialog } from 'primereact/confirmdialog';

const formatDateToInputValue = (date) => {
    const year = String(date.getFullYear()).padStart(4, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
};

const ValiderSalarie = () => {

    const [nonValidate,setNonValidate]=useState([])
    const [personClicked,setPersonClicked]=useState(null)
    const [show,setShow]=useState(false)

    const [isDataReady, setIsDataReady] = useState(false);

    useEffect(()=>{
        setIsDataReady(false);
        EtatEmployer.getEmpNonValidate().then((res)=>{
            setNonValidate(res)
        }).catch((er)=>{
            console.log(er.message)
        }).finally(()=>{
            setTimeout(()=> setIsDataReady(true),100)
        })
        //
    },[])
    const close=useCallback(()=>{
        setShow(false)
        setPersonClicked(null)
    },[])
    useEffect(()=>{
        if (personClicked){
            setShow(true)
        }
    },[personClicked])
    const clickedPerson=useCallback((e)=>{
        setPersonClicked(e)
    },[])

    const validateEmp=useCallback((idEmp)=>{
        EtatEmployer.validate(idEmp).then((res)=>{
            setNonValidate((prev)=>prev.filter((item)=>item.emp.employe.idEmp !==idEmp))
        }).catch((e)=>{
            console.log(e)
        })
    },[])



    const supprimer=useCallback((idEmp)=>{
        confirmDialog({
            message: 'Voulez-vous supprimer cet utilisateur?',
            header: 'Confirmation',
            icon: 'fas fa-triangle-exclamation',
            acceptLabel: 'Valider',
            rejectLabel: 'Annuler',
            acceptClassName: 'p-button-sm p-button-primary py-1',
            rejectClassName: 'p-button-sm p-button-danger me-2 py-1',
            accept: ()=> {
                EtatEmployer.supprimerEmp(idEmp).then((res)=>{
                    setNonValidate((prev)=>prev.filter((item)=>item.idEtat !==idEmp))
                }).catch((e)=>{
                    console.log(e)
                })
            },
            reject: ()=> {}
        });
    },[])

    const location = useLocation()
    const navigate = useNavigate()
    const [clickedEmp, setClickedEmp] = useState(false);
    const idEmpClicked= useMemo(() => {
        setClickedEmp(false)
        return location.hash.substring(1);
    }, [location]);
    useLayoutEffect (() => {
        if (idEmpClicked && isDataReady){
            const element = document.getElementById(idEmpClicked)
            if (element){
                const headerOffset = document.querySelector('#head')?.offsetHeight || 0;
                const elementPosition = element.getBoundingClientRect().top + window.scrollY;
                const offsetPosition = elementPosition - headerOffset -100;
                window.scrollTo({
                    top: offsetPosition,
                    behavior: 'smooth'
                });
            }else {
                window.scrollTo({ top: 0, behavior: 'smooth' });
            }
        } else {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
    }, [idEmpClicked,isDataReady]);

    const [blink, setBlink] = useState(1);
    useEffect(()=>{
        if (isDataReady && idEmpClicked){
            const values = [0.96, 1.03];
            let currentIndex = 0;
            const interval = 600;
            const duration = 7000;

            const intervalId = setInterval(() => {
                setBlink(values[currentIndex]);
                currentIndex = (currentIndex + 1) % values.length;
            }, interval);

            const timeoutId = setTimeout(() => {
                setClickedEmp(true)
                clearInterval(intervalId);
                setBlink(1)
            }, duration);

            return () => {
                clearInterval(intervalId);
                clearTimeout(timeoutId);
            };
        }
    },[isDataReady,idEmpClicked])

    const cl = useCallback(
        (idEmp) => {
            if (idEmp===parseInt(idEmpClicked)){
                setClickedEmp(true)
            }
        },
        [idEmpClicked,clickedEmp]
    );
    const { user } = useContext(UserContext);
    const {body} = useWebSocket("/notif/validerSalarier/"+user?.idEmp)
    useEffect(()=>{
        if (body){
            setNonValidate(prevState => [body,...prevState])
            navigate(`#${body.emp.employe.idEmp}`, { replace: true });
        }
    },[body])
    const [newPerson, setNewPerson] = useState(null);

    useEffect(() => {
        if (newPerson){
            setPersonClicked(newPerson)
            setNonValidate((item)=>item.map(g=>g.idEtat===newPerson.idEtat ? newPerson : g))
        }
    }, [newPerson]);

    return (
        <>
            <div>
                <table className="table">
                    <thead>
                        <tr>
                            <th scope="col"/>
                            <th scope="col">ID</th>
                            <th scope="col">Nom</th>
                            <th scope="col">Prenom</th>
                            <th scope="col">Poste</th>
                            <th scope="col">Date d'entrée</th>
                            <th scope="col"/>
                        </tr>
                    </thead>
                    <tbody>
                    {nonValidate.map((e)=>(
                        <tr  style={{
                            transform: idEmpClicked && parseInt(idEmpClicked) === e.emp.employe.idEmp
                                ? clickedEmp ? 'none' : `scale(${blink})`
                                : 'none',
                            transition: 'all 0.7s ease-in'
                        }} id={e.emp.employe.idEmp} key={e.idEtat} onClick={()=>cl(e.emp.employe.idEmp)} className={`${idEmpClicked && parseInt(idEmpClicked) ===e.emp.employe.idEmp ? 'table-primary' : ''}`}>
                            <td>
                                {e?.emp.employe.profile && (
                                    <img
                                        src={APIURL()+`${e?.emp.employe.profile}`}
                                        alt="captured or uploaded"
                                        className="border-dark-light rounded-circle mt-0 pt-0"
                                        width={40} height={40}
                                        style={{ objectFit: 'cover' }}
                                        decoding={"async"}
                                    />
                                )}
                            </td>
                            <th scope="row">{String(e.emp.employe.matricule).padStart(4, '0')}</th>
                            <td>{e.emp.employe.nom}</td>
                            <td>{e.emp.employe.prenom}</td>
                            <td>{e.emp.employe.type.poste}</td>
                            <td>{formatDateToInputValue(new Date(e.emp.dateEntre))}</td>
                            <td>
                                <Dropdown>
                                    <Dropdown.Toggle
                                        id={`dropdown-${1}`}
                                        as={"button"}
                                        className="btn btn-sm border"
                                        style={{zIndex: '1'}}
                                    >
                                        Option
                                    </Dropdown.Toggle>
                                    <Dropdown.Menu style={{zIndex: '3'}}>
                                        <Dropdown.Item className="text-concept" onClick={()=>{clickedPerson(e)}}>
                                            <i className="fa fa-user-edit me-1"/>Modifier ses Infos
                                        </Dropdown.Item>
                                        <Dropdown.Item className="text-success-emphasis" onClick={()=>validateEmp(e.emp.employe.idEmp)}>
                                            <i className="fa fa-check-to-slot me-1"/>Valider
                                        </Dropdown.Item>
                                        <Dropdown.Item className="bg-danger text-white"
                                            onClick={()=>supprimer(e.idEtat)}
                                        ><i className="fa fa-trash-alt me-1"/> Supprimer</Dropdown.Item>
                                    </Dropdown.Menu>
                                </Dropdown>
                            </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            </div>
            {personClicked && (
                <VoirInfo show={show} close={close} person={personClicked} setNewPerson={setNewPerson} valider={validateEmp} location={1} supprimer={supprimer}/>
            )}
            <ConfirmDialog/>
        </>
    )
}

export default ValiderSalarie