import {Form, Modal} from "react-bootstrap";
import React, {useCallback, useEffect, useState} from "react";
import {useLocation, useNavigate} from "react-router-dom";
import {formatDateToInputValue} from "../../InfoPersonel";
import { Editor } from 'primereact/editor';
import FileView from "../../Rendu/FileView";
import Dropzone from "react-dropzone";
import { Button } from 'primereact/button';
import {Event} from "../../../Model/Event";


const ArisEvent = ({show, setActive})=>{
    const [showContent, setShowContent] = useState(show);
    const navigate=useNavigate()
    const location = useLocation();
    const hide = useCallback(
        () => {
            changeElements('date', new Date())
            changeElements('titre', '')
            changeElements('content', '')
            setFiles([])
            setShowContent(false)
            setActive(1)
            if (location.pathname === "/accueil") {
                navigate("/vide")
            } else {
                navigate("/accueil");
            }
            setLoading(false)
        },
        []
    );

    const [elements, setElements] = useState({
        date: new Date(),
        titre: "",
        content: ""
    });
    const [loading, setLoading] = useState(false);

    const changeElements = useCallback(
        (attr, value) => {
            setElements(prev=>({...prev, [attr]: value}))
        },
        []
    );


    useEffect(() => {
        setShowContent(show)
    }, [show]);
    const [tailles, setTailles] = useState({
        minim: false,
        maxim: false,
        normal: true
    });
    const [files, setFiles] = useState([]);

    const onFileDrop = useCallback(
        (acceptedFiles) => {
            setFiles((prev) => {
                const newFiles = acceptedFiles.filter(
                    (file) => !prev.some((existingFile) => existingFile.name === file.name && existingFile.size === file.size)
                );
                return [...prev, ...newFiles];
            });
            setTailles((prev)=>({...prev, maxim : false}))
        },
        [],
    );

    const submit = useCallback(
        () => {
            if (elements.titre.trim().length===0){
                return
            }else{
                setLoading(true)
                console.log(files)
                Event.uploadEvent(elements.titre, elements.content, files,(new Date(elements.date)).toISOString().split("T")[0]).then((rep)=>{
                    hide()
                }).catch((e)=>{
                    console.log(e.message)
                })
                    .finally(()=>{
                    setLoading(false)
                })
            }
        },
        [files, elements]
    );

    return(
        <>
            <Modal show={showContent} onHide={()=>hide()} keyboard={false}
                   backdrop="static"
                   autoFocus={true}
                   dialogClassName="modal-dialog-centered modal-70w position-relative d-flex justify-content-center align-items-center"
                   contentClassName="d-flex justify-content-center w-100"
                   animation
            >
                <Modal.Header closeButton>
                    <Modal.Title className="fw-bolder text-concept">{"Ajouter un evenement"}</Modal.Title>
                </Modal.Header>
                <Modal.Body className="p-1 mb-0 rounded-3 ">
                    <div className="w-100 row m-0 p-2 text-print">
                        <Form.Group className="mb-1 col-6" controlId="edit-titre">
                            <Form.Label>Titre</Form.Label>
                            <Form.Control disabled={loading} className="input-show-placeholder" autoFocus type="text" value={elements.titre} onChange={(e)=>{
                                changeElements('titre',e.target.value)
                            }} placeholder="Donnez un titre" />
                        </Form.Group>
                        <Form.Group className="mb-1 col-6" controlId="edit-date">
                            <Form.Label>Date</Form.Label>
                            <Form.Control disabled={loading} type="date" value={formatDateToInputValue(elements.date)} onChange={(e)=>{
                                const dt = new Date(e.target.value);
                                changeElements('date',dt)
                            }} placeholder="Date debut" />
                        </Form.Group>
                        <Form.Group className="mb-1 12 " controlId="edit-comment">
                            <Form.Label>Contenu</Form.Label>
                            <Editor disabled={loading} value={elements.content} onTextChange={(e) => changeElements('content',e.htmlValue)} className="text-print rounded-3" style={{ height: '320px' }} />
                        </Form.Group>
                        <Form.Group className="col-12" controlId="fichier">
                            <Form.Label className={`mt-2 ${tailles.maxim ? 'opacity-0' : ''}`}>Fichier</Form.Label>
                            <div className="row m-0 p-0 w-100 ">
                                {files.map((file,index)=>(
                                    <FileView opacity={tailles.maxim} setAllFiles={setFiles} key={index} fichier={file}/>
                                ))}
                                {!loading && (
                                    <Dropzone accept={{ 'image/*': [], 'video/*': [] }}  onDrop={acceptedFiles => onFileDrop(acceptedFiles)}>
                                        {({getRootProps, getInputProps}) => (
                                            <section className={`border-is-null rounded-3 ${tailles.maxim ? 'position-absolute top-0 start-0 w-100 z-3 opacity-1 bg-danger bg-opacity-50 height-200' : files.length >0 ? 'col-4 align-items-stretch mb-2 height-80' : 'height-100 w-100'}`}>
                                                <div className="h-100 w-100 d-flex justify-content-center align-items-center" {...getRootProps()}>
                                                    <input {...getInputProps()} />
                                                    {files.length >0 ? (<i className="fa fa-plus-circle text-plus"/>) : (<p className="pb-0 m-0">Glissez ou cliquez ici pour ajouter vos fichiers</p>)}
                                                </div>
                                            </section>
                                        )}
                                    </Dropzone>
                                )}

                            </div>
                        </Form.Group>
                    </div>
                </Modal.Body>
                <Modal.Footer>
                    <div className="w-100 d-inline-flex justify-content-between">
                        <Button label="Annuler" severity="danger" onClick={hide} className="w-50-2rem py-2 rounded-3"/>
                        <Button onClick={submit} label="Publier" loading={loading} className="w-50-2rem py-2 rounded-3"/>
                    </div>
                </Modal.Footer>
            </Modal>
        </>
    )
}

export default ArisEvent