import React, {useCallback, useEffect, useMemo, useState} from "react";
import {Form, InputGroup, Modal} from "react-bootstrap";
import {APIURL} from "../../Model/APIURL";
import EtatEmployer from "../../Model/EtatEmployer";
import {formatDateToInputValue} from "../InfoPersonel";
import {addDays} from "date-fns";
import Pagination from "../Main/Utilitaire/Pagination";
import Quotidien from "./Quotidien";
import FileWeek from "./FileWeek";

export const normalizeString = (str)=>{
    return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}
const Hebdo = ()=>{
    const userProfile=useCallback((user)=>{
        if (user?.profile){
            return (
                <img
                    src={APIURL()+`${user.profile}`}
                    alt=""
                    className="border-dark-light rounded-circle mt-0 mx- p-0"
                    width={40} height={40}
                    style={{ objectFit: 'cover'}}
                />
            )
        }else{
            return (
                <span className="cursor-pointer position-relative d-flex justify-content-center bg-secondary mx-1 border-dark-light rounded-circle" style={{width:'42px', height: '42px'}}>
                    <i className={`far icon-20 fa-user-circle  my-auto ${user===null ? 'text-concept': 'text-white'}`}/>
                </span>
            )
        }

    },[])

    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [post, setPost] = useState('');
    const [filtered, setFiltered] = useState([]);

    const [allEmp, setAllEmp] = useState([]);

    useEffect(() => {
        EtatEmployer.getEmployeValider().then((resp)=>{
            setAllEmp(resp)
        }).catch(()=>{})
    }, []);

    useEffect(() => {
        let data = allEmp;
        if (matricule) {
            data = allEmp.filter(emp =>{
                if (emp.matricule){
                    return emp.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter(emp =>
                emp.nom.toLowerCase().includes(nom.toLowerCase()) ||
                emp.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        if (post){
            data = data.filter(emp=>normalizeString(emp.type.poste.toLowerCase()).includes(normalizeString(post.toLowerCase())))
        }
        setFiltered(data)
    }, [matricule,nom,allEmp,post]);

    const prevSemaine = useCallback((today) => {

        const dayOfWeek = today.getDay();
        const monday = new Date(today);
        monday.setDate(today.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));

        const prevMonday = new Date(monday);
        prevMonday.setDate(monday.getDate() - 7);

        const prevFriday = new Date(prevMonday);
        prevFriday.setDate(prevMonday.getDate() + 4);

        return {
            prevMonday,
            prevFriday
        };
    }, []);

    const [date, setDate] = useState(prevSemaine(new Date()).prevMonday);
    const [paginate, setPaginate] = useState(1);

    const [validateDates, setValidateDates] = useState(prevSemaine(addDays(date,7)));
    useEffect(() => {
        setValidateDates(()=>(prevSemaine(addDays(date,7))))
    }, [date]);

    //on teste si la date est valide!!

    const [show, setShow] = useState(false);
    const [userClicked, setUserClicked] = useState(null);
    const hide = useCallback(
        () => {
            setShow(false)
            setUserClicked(null)
        },
        []
    );

    const [isDetailClicked, setIsDetailClicked] = useState(true);
    const modalContent = useMemo(() => {
        if (userClicked){
            if (isDetailClicked){
                return (
                    <>
                        <Quotidien idUtilisateur={userClicked} dateMonday={validateDates.prevMonday} dateFriday={validateDates.prevFriday}/>
                    </>
                )
            }else{
                return (
                    <>
                        <FileWeek
                            user={userClicked}
                            fin={validateDates.prevFriday.toISOString().split('T')[0]}
                            debut={validateDates.prevMonday.toISOString().split('T')[0]}
                        />
                    </>
                )
            }
        }
    }, [userClicked, isDetailClicked,validateDates]);
    return(
        <>
            <div className="card w-100 mb-2">
                <div className="card-body pt-1 pb-1">
                    <h3 className="text-center">Liste des Salariés</h3>
                    <div className="row m-0 p-0">
                        <div className="col-3">
                            <InputGroup className="my-3">
                                <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                                <Form.Control
                                    placeholder="matricule"
                                    aria-label="matricule"
                                    aria-describedby="basic-addon1"
                                    type="search"
                                    value={matricule}
                                    onChange={(event)=>{
                                        setMatricule(event.target.value.replace(/\D/g, ''))
                                    }}
                                />
                            </InputGroup>
                        </div>
                        <div className="col-5">
                            <InputGroup className="my-3">
                                <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                                <Form.Control
                                    placeholder="nom ou prénom"
                                    aria-label="nom"
                                    aria-describedby="nom"
                                    type="search"
                                    value={nom}
                                    onChange={(event) => setNom(event.target.value)}
                                />
                            </InputGroup>
                        </div>
                        <div className="col-4">
                            <InputGroup className="my-3">
                                <InputGroup.Text id="basic-addon1">Poste</InputGroup.Text>
                                <Form.Control
                                    placeholder="nom ou prénom"
                                    aria-label="nom"
                                    aria-describedby="nom"
                                    type="search"
                                    value={post}
                                    onChange={(event) => setPost(event.target.value)}
                                />
                            </InputGroup>
                        </div>
                    </div>
                </div>
            </div>
            <div className="w-100 p-2 d-inline-flex justify-content-between">
                <span className="fs-4 fw-bolder">Semaine du {date.toLocaleDateString("fr-FR",  { day: "numeric", month: "short", year: "numeric" })}</span>
                <InputGroup size={"sm"} className="" style={{width: '16vw'}}>
                    <InputGroup.Text id="basic-addon1">Semaine du</InputGroup.Text>
                    <Form.Control
                        aria-label="semaine"
                        aria-describedby="basic-addon1"
                        type="date"
                        size={"sm"}
                        value={formatDateToInputValue(date)}
                        onChange={(e) => {
                            const dt = new Date(e.target.value);
                            const today = new Date();

                            today.setHours(0, 0, 0, 0);
                            dt.setHours(0, 0, 0, 0);

                            if (dt.getTime() > today.getTime()) {
                                setDate((prev) => prev);
                            } else {
                                setDate(dt);
                            }
                        }}

                    />
                </InputGroup>
            </div>
            <div className="m-0 w-100 rounded-3 bg-white mb-3">
                <div className="rounded-3 p-1 m-0 w-100">
                    <table className="table mb-0 table-striped table-hover">
                        <thead>
                            <tr className="text-center">
                                <th scope="col"/>
                                <th scope="col">M°</th>
                                <th scope="col">Nom</th>
                                <th scope="col">Prenom</th>
                                <th scope="col">Poste</th>
                                <th scope="col">Rendu</th>
                            </tr>
                        </thead>
                        <tbody>
                        {filtered.slice((paginate-1)*10,(paginate)*10).map((element,index)=>(
                            <tr key={index} className="cursor-pointer" onClick={()=> {
                                if (validateDates.prevMonday && !isNaN(new Date(validateDates.prevMonday).getTime())) {
                                    setUserClicked(element);
                                    setIsDetailClicked(true)
                                    setShow(true);
                                } else {
                                    alert("Date invalide");
                                }
                            }}>
                                <td>
                                    {userProfile(element)}
                                </td>
                                <th scope="row">{String(element.matricule).padStart(4, '0')}</th>
                                <td>{element.nom}</td>
                                <td>{element.prenom}</td>
                                <td>{element.type.poste}</td>
                                <td className="bg-success">Rendu du {validateDates.prevMonday.toLocaleDateString("fr-FR",  { day: "numeric" })} au {validateDates.prevFriday.toLocaleDateString("fr-FR",  { day: "numeric", month: "short", year: "numeric" })}</td>
                            </tr>
                        ))}
                        </tbody>

                    </table>
                </div>
                <div className="d-flex justify-content-end w-100 m-0 p-2">
                    <Pagination length={filtered.length % 10 === 0 ? filtered.length / 10 : Math.floor(filtered.length / 10) + 1} active={paginate} setActive={setPaginate}/>
                </div>
            </div>

            <Modal
                show={show}
                onHide={hide}
                keyboard={false}
                backdrop="static"
                dialogClassName="modal-90w position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center w-100"
            >
                <Modal.Header className="position-relative">
                    <div onClick={hide} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                    <Modal.Title className="fs-4 fw-bold">{userClicked ? userClicked?.nom + " "+ userClicked?.prenom: ""}</Modal.Title>
                </Modal.Header>
                <Modal.Body className="pt-1">
                    <div className="w-100 p-2">
                        <button onClick={()=>setIsDetailClicked(true)} type="button" className={`btn btn-dark btn-sm mx-2 shadow text-warning ${isDetailClicked ? 'scale-2' : 'scale-1'}`}>
                            Detail Rendu
                        </button>
                        <button onClick={()=>setIsDetailClicked(false)} className={`btn btn-sm btn-primary shadow text-white ${!isDetailClicked ? 'scale-2' : 'scale-1'}`}>
                            Fichier envoyés
                        </button>
                    </div>
                    {modalContent}
                </Modal.Body>
            </Modal>
        </>
    )
}
export default Hebdo