import React from "react";
import BoxFileview from "./BoxFileview";

function formatDate(date) {
    const formatter = new Intl.DateTimeFormat('fr-FR', {
        day: 'numeric',
        month: 'short',
        year: 'numeric'
    });
    return formatter.format(date).replace('.', '');
}
const ViewFile = ({data})=>{

    return(
        <div className="row p-0 mb-2 border-bottom border-2">
            <div className="w-100 d-inline-flex justify-content-between small pb-1">
                <span className="fw-bolder">{data.reference}</span>
                <span>{formatDate(new Date(data.date))}</span>
            </div>
            {data.fileNames.map((fileName,index)=>(
                <BoxFileview key={index} file={fileName}/>
            ))}
        </div>
    )
}
export default ViewFile