import React, {useEffect, useState} from "react";
import {Col, Form, Row} from "react-bootstrap";
import Type from "../../../Model/Type";
import Allinfo from "../../../Model/Allinfo";
import {formatDateToInputValue, genres, niveaus, statuts, validateAge} from "../../InfoPersonel";
import {handleTelChange} from "../Salarier/VoirInfo";

const ModifInfoPersonel = ({setActif,object, changeValueUser, isModifier,close}) => {

    const [clickTerminer,setClickTerminer]=useState(0)
    const [nom,setNom]=useState('')
    const [prenom,setPrenom]=useState('')
    const [naissance,setNaissance]=useState(new Date())
    const [tel,setTel]=useState('')
    const [adresse,setAdresse]=useState('')
    const [cin,setCin]=useState('')
    const [valide,setValide]=useState(new Date())
    const [nationalite,setNationalite]=useState('')
    const [genre,setGenre]=useState(null)
    const [statut,setStatut]=useState(null)
    const [enfant,setEnfant]=useState(0)
    const [niveau,setNiveau]=useState(null)


    useEffect(()=>{
        if (object){
            setNom(object.nom)
            setPrenom(object.prenom)
            setNaissance(new Date(object.naissance))
            setTel(object.tel)
            setAdresse(object.adresse)
            setCin(object.cin)
            setValide(new Date(object.valide))
            setNationalite(object.nationalite)
            setGenre(object.genre)
            setStatut(object.statut)
            setEnfant(parseInt(object.enfant || '0', 10))
            setNiveau(object.niveau)
        }
    },[])


    const changeValueObject = () => {
        changeValueUser({
            ...object,
            nom: nom,
            prenom: prenom,
            naissance: naissance,
            tel: tel,
            adresse: adresse,
            cin: cin,
            valide: valide,
            nationalite: nationalite,
            genre: genre,
            statut: statut,
            enfant: enfant,
            niveau: niveau
        })
    }
    const [validationErrors, setValidationErrors] = useState({
        validPrenom: true,
        validNom: true,
        validTel: true,
        validCIN: true,
        validNaissance: true,
        validAdress: true,
    });
    const handleSubmit = (event) => {
        event.preventDefault();


        const isValidNaissance = validateAge(naissance);

        const errors = {
            validPrenom: prenom.trim().length > 0,
            validNom: nom.trim().length >0,
            validTel: tel.length >= 17,
            validCIN: cin.length > 14,
            validNaissance: isValidNaissance,
            validAdress: adresse.trim().length>0
        };

        setValidationErrors(errors);
        const isValid = Object.values(errors).every(Boolean);

        if (!isValid) {
            return;
        }

        if (clickTerminer===1){
            Allinfo.modifEmployee({...object,
                nom: nom,
                prenom: prenom,
                naissance: naissance,
                tel: tel,
                adresse: adresse,
                cin: cin,
                valide: valide,
                nationalite: nationalite,
                genre: genre,
                statut: statut,
                enfant: enfant,
                niveau: niveau
            },object.mdp).catch((error)=>{
                console.log(error.message)
            }).finally(()=>{
                close()
                isModifier((prev)=>!prev)
            })
        }else if (clickTerminer===2){
            setActif(2)
            changeValueObject()
        }else{
            return
        }
    }
    return(
        <>
            <Form className="m-0 p-0"  autoComplete={"off"} onSubmit={handleSubmit}>
                <Row className="mb-3 border-bottom">
                    <Form.Group className="mb-3" as={Col} md="4" controlId="nom">
                        <Form.Label className="fw-bold small text-light-emphasis">Nom</Form.Label>
                        <Form.Control
                            required
                            type="text"
                            size={"sm"}
                            className="bg-transparent border-dark-light"
                            placeholder=""
                            value={nom}
                            onChange={(e)=>setNom(e.target.value)}
                            isInvalid={!validationErrors.validNom}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="4" controlId="prenom">
                        <Form.Label className="fw-bold small text-light-emphasis">Prénom</Form.Label>
                        <Form.Control
                            required
                            type="text"
                            className="bg-transparent border-dark-light"
                            placeholder=""
                            size={"sm"}
                            value={prenom}
                            onChange={(e)=>setPrenom(e.target.value)}
                            isInvalid={!validationErrors.validPrenom}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="4" controlId="naissance">
                        <Form.Label className="fw-bold small text- text-light-emphasis">Date de naissance</Form.Label>
                        <Form.Control
                            required
                            type="date"
                            className="bg-transparent border-dark-light"
                            size={"sm"}
                            isInvalid={!validationErrors.validNaissance}
                            value={formatDateToInputValue(naissance)}
                            onChange={(e)=>setNaissance(new Date(e.target.value))}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="3" controlId="tel">
                        <Form.Label className="fw-bold small text-light-emphasis">Tel</Form.Label>
                        <Form.Control
                            required
                            type="text"
                            className="bg-transparent border-dark-light"
                            size={"sm"}
                            value={tel}
                            isInvalid={!validationErrors.validTel}
                            onChange={(e)=>{ setTel(handleTelChange(e.target.value))}}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="3" controlId="adresse">
                        <Form.Label className="fw-bold small text-light-emphasis">Adresse</Form.Label>
                        <Form.Control
                            required
                            type="text"
                            isInvalid={!validationErrors.validAdress}
                            className="bg-transparent border-dark-light"
                            size={"sm"}
                            value={adresse}
                            onChange={(e)=>setAdresse(e.target.value)}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="3" controlId="cin">
                        <Form.Label className="fw-bold small text-light-emphasis">CIN</Form.Label>
                        <Form.Control
                            required
                            isInvalid={!validationErrors.validCIN}
                            type="text"
                            className="bg-transparent border-dark-light"
                            placeholder="CIN"
                            size={"sm"}
                            value={cin}
                            onChange={(e)=>{
                                let value = e.target.value.replace(/\D/g, '').slice(0, 12);
                                value = value.replace(/(.{3})/g, '$1 ').trim();
                                setCin(value)
                            }}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} md="3" controlId="validation">
                        <Form.Label className="fw-bold small text-light-emphasis">Date valide CIN</Form.Label>
                        <Form.Control
                            required
                            type="date"
                            size={"sm"}
                            className="bg-transparent border-dark-light"
                            value={formatDateToInputValue(new Date(valide))}
                            onChange={(e)=>setValide(new Date(e.target.value))}
                        />
                    </Form.Group>

                    <Form.Group className="mb-2 " as={Col} style={{width: '20%'}} controlId="nationalite">
                        <Form.Label className="fw-bold small text-light-emphasis">Nationalité</Form.Label>
                        <Form.Select size={"sm"} value={nationalite} onChange={(e)=> setNationalite(e.target.value)} className="bg-transparent border-dark-light" required>
                            <option className="text-dark" value={"Malagasy"}>Malagasy</option>
                            <option className="text-dark" value={"Etranger"}>Etranger</option>
                        </Form.Select>
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} style={{width: '20%'}} controlId="genre">
                        <Form.Label className="fw-bold small text-light-emphasis">Genre</Form.Label>
                        <Form.Select size={"sm"} value={genre?.id} onChange={(e)=>setGenre(genres.find((element)=>element.id===parseInt(e.target.value,10)))} className="bg-transparent border-dark-light" required>
                            {genres.map((e)=>(
                                <option key={e.id} className="text-dark" value={e.id}>{e.genre}</option>
                            ))}
                        </Form.Select>
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} style={{width: '20%'}} controlId="statut">
                        <Form.Label className="fw-bold small text-light-emphasis">Statut Marital</Form.Label>
                        <Form.Select size={"sm"} value={statut?.id} onChange={(e)=>setStatut(statuts.find((element)=>element.id===parseInt(e.target.value,10)))} className="bg-transparent border-dark-light" required>
                            {statuts.map((e)=>(
                                <option key={e.id} className="text-dark" value={e.id}>{e.value}</option>
                            ))}
                        </Form.Select>
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} style={{width: '20%'}} controlId="enfant">
                        <Form.Label className="fw-bold small text-light-emphasis">Nombre enfant</Form.Label>
                        <Form.Control
                            required
                            type="number"
                            size={"sm"}
                            className="bg-transparent border-dark-light"
                            min={0}
                            value={enfant}
                            onChange={(e)=>{
                                const val = e.target.value.replace(/\D/g, '')
                                setEnfant(parseInt(val))
                            }}
                        />
                    </Form.Group>
                    <Form.Group className="mb-3" as={Col} style={{width: '20%'}} controlId="etude">
                        <Form.Label className="fw-bold small text-light-emphasis">Niveau d'étude</Form.Label>
                        <Form.Select size={"sm"} value={niveau?.id} onChange={(e)=>setNiveau(niveaus.find((element)=>element.id===parseInt(e.target.value,10)))} className="bg-transparent border-dark-light" required>
                            {niveaus.map((e)=>(
                                <option key={e.id} className="text-dark" value={e.id}>{e.value}</option>
                            ))}
                        </Form.Select>
                    </Form.Group>
                </Row>
                <Row className="w-100 m-0 p-0 mb-2">
                    <Col md={6}>
                        <button type="submit" onClick={()=>setClickTerminer(1)} className="btn bg-blue text-white w-100 btn-sm">Terminer</button>
                    </Col>
                    <Col md={6}>
                        <button type="submit" onClick={()=> {
                            setClickTerminer(2)
                        }} className="btn btn-info text-white w-100 btn-sm">Suivant</button>
                    </Col>
                </Row>
            </Form>
        </>
    )
}
export default ModifInfoPersonel