import React, {useCallback, useState} from "react";

export const getFileIcon = (fileName) => {
    const extension = fileName.split(".").pop().toLowerCase();

    const icons = {
        "ppt": "fa-file-powerpoint text-warning-emphasis",
        "pptx": "fa-file-powerpoint text-warning-emphasis",
        "xls": "fa-file-excel text-success",
        "xlsx": "fa-file-excel text-success",
        "doc": "fa-file-word text-primary",
        "docx": "fa-file-word text-primary",
        "zip": "fa-file-zipper txt-yellow",
        "rar": "fa-file-zipper txt-yellow",
        "jpg": "fa-file-image text-aris",
        "jpeg": "fa-file-image text-aris",
        "png": "fa-file-image text-aris",
        "gif": "fa-file-image text-aris",
        "webp": "fa-file-image text-aris",
        "pdf": "fa-file-pdf text-danger",
        "txt": "fa-file-text text-secondary",
    };

    return icons[extension] || "fa-file text-dark-emphasis";
};
const FileView = ({fichier, opacity, setAllFiles})=>{
    const [deleteView, setDeleteView] = useState(false);
    const remove = useCallback(
        (file) => {
            setAllFiles((prev)=>prev.filter(rend=>rend.name !==file.name && rend.size!==file.size))
        },
        [],
    );

    return (
        <div onMouseEnter={()=>setDeleteView(true)} onMouseLeave={()=>setDeleteView(false)} className={`${opacity ? 'opacity-0' : ''} col-4 pe-1 height-80 ps-0 py-0 align-items-stretch mb-2 position-relative`}>
            <div className="card w-100 h-100 scale-1">
                <div className="card-header bg-grey">
                    <i className={`fa ${getFileIcon(fichier.name)}`} />
                </div>
                <div className="card-body m-0 p-0 d-flex justify-content-center align-items-center rounded-bottom-2 bg-concept text-white">
                    {fichier.name}
                </div>
            </div>
            {deleteView && (
                <div onClick={()=>remove(fichier)} style={{transform: 'translate(0.2rem,-0.7rem)', width: '30px', height: '30px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer z-3">
                    <i className="fa-solid fa-close  text-dark-emphasis"/>
                </div>
            )}
        </div>
    )
}
export default FileView