import React, {useCallback, useContext, useEffect, useMemo, useRef, useState} from "react";
import {
    Badge,
    Button,
    Card,
    CardBody, CardImg,
    CardTitle, Carousel,
    Col,
    FloatingLabel,
    Form,
    Modal,
    Offcanvas, Overlay, Popover, PopoverBody,
    Row
} from "react-bootstrap";
import Pointage from "../Model/Pointage";
import Conge from "../Model/Conge";
import {UserContext} from "./Main/Utilitaire/UserProvider";
import Flash from "./Accueil/Flash";
import Depeche from "./Accueil/Depeche";
import Politique from "./Accueil/Politique";
import Societe from "./Accueil/Societe";
import Economie from "./Accueil/Economie";
import Culture from "./Accueil/Culture";
import Sport from "./Accueil/Sport";
import ShowEvent from "./Accueil/Event/ShowEvent";
import {Event} from "../Model/Event";

const Content = () => {
    const {user: userContext}=useContext(UserContext)
    const [pointage,setPointage]=useState(null)
    const [solde,setSolde]=useState(0)
    const [hF,setHF]=useState("--:--")

    useEffect(()=>{
        if (userContext){
            Pointage.getPointageNow().then((res)=>{
                setPointage(res)
            }).catch(()=>{})
            Conge.getSold(userContext?.idEmp).then((res)=>{
                setSolde(parseFloat(res))
            }).catch(()=>{})
            const interval = setInterval(() => {
                setHF(getHeureMin((new Date())));
            }, 60000);
            setHF(getHeureMin(new Date()));
            return () => clearInterval(interval);
        }
    },[userContext])
    const getHeureMin = useCallback((date) => {
        if (!date) return "--:--";
        const d = new Date(date);

        const hours = String(d.getHours()).padStart(2, '0');
        const minutes = String(d.getMinutes()).padStart(2, '0');
        return `${hours}:${minutes}`;
    },[])

    const [listActus, setListActus] = useState([]);

    const [infoClicked,setInfoClicked]=useState(1)
    const clickedInfo=useCallback((id)=>{
        if (listActus.length===0 && id===8){
            return
        }
        setInfoClicked(id)
    },[listActus])
    useEffect(() => {
        Event.getEvents().then((rep)=>{
            setListActus(rep)
            if (rep.length>0){
                setInfoClicked(8)
            }
        }).catch((e)=>{
            console.log(e.message)
        })
    }, []);

    const htmlInfo=useMemo(()=>{
        switch (infoClicked) {
            case 1:
                return (<Flash usercontext={userContext}/>)
            case 2:
                return (<Depeche/>)
            case 3:
                return (<Politique/>)
            case 4:
                return (<Societe/>)
            case 5:
                return (<Economie/>)
            case 6:
                return (<Culture/>)
            case 7:
                return (<Sport/>)
            default: return (<ShowEvent listActu={listActus}/>)
        }
    },[infoClicked, userContext, listActus])
    return(
        <>
            <div className="w-100 rounded-3">
                <Row className="m-0 p-0 w-100">
                    <Col md={4} className="ps-0">
                        <Card className="bg-green">
                            <CardTitle className="text-center text-white pt-1 mb-0">Pointage</CardTitle>
                            <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                                <pre className="p-0 m-0">{getHeureMin(pointage?.dateDebut)}</pre><i className="fas fa-arrow-right"/><pre className="p-0 m-0">{hF}</pre>
                            </CardBody>
                        </Card>
                    </Col>
                    <Col md={4}>
                        <Card className="bg-blue-darker">
                        {/*<Card className="bg-white">*/}
                            <CardTitle className="text-center pt-1 mb-0 text-white">Prime</CardTitle>
                            <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                                <pre className="p-0 m-0">0,0</pre><span>MGA</span>
                            </CardBody>
                        </Card>
                    </Col>
                    <Col md={4} className="pe-0">
                        <Card className="bg-red">
                            <CardTitle className="text-center pt-1 mb-0 text-white">Solde Congés</CardTitle>
                            <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                                <pre className="p-0 m-0">{solde}</pre><span>Jour(s)</span>
                            </CardBody>
                        </Card>
                    </Col>
                </Row>
            </div>
            <div className="mt-4 w-100 rounded-3 pb-3">
                <Card className="h-100 m-0 p-0 bg-transparent border-0">
                    <CardTitle className="mb-0 bg-white rounded-top-2 shadow p-1">
                        <div className="w-100 p-1 d-inline-flex align-items-center rounded-top-1 justify-content-between">
                            <div className="flex-grow-1">
                                <h4 onClick={()=>clickedInfo(8)} className={`ms-3 fs-3 text-print cursor-pointer px-2 ${infoClicked===8 && 'width-max border-bottom border-primary border-2'}`}><span className="text-aris fw-bolder">Aris</span> <span className="fw-bolder text-concept">Actu</span></h4>
                            </div>
                            <div className="d-inline-flex justify-content-end h-100">
                                <ul className="list-inline my-auto">
                                    <li className="list-inline-item small border-end border-2 border-dark pe-2 cursor-pointer" onClick={()=>clickedInfo(1)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===1 ? 'border-concept color-param' : 'opacity-75'}`}>Top Info</pre></li>
                                    <li className="list-inline-item small border-end border-2 border-dark pe-2 cursor-pointer" onClick={()=>clickedInfo(2)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===2 ? 'border-concept color-param' : 'opacity-75'}`}>Dépêches</pre></li>
                                    <li className="list-inline-item small border-end border-2 border-dark pe-2 cursor-pointer" onClick={()=>clickedInfo(3)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===3 ? 'border-concept color-param' : 'opacity-75'}`}>Politique</pre></li>
                                    <li className="list-inline-item small border-end border-2 border-dark pe-2 cursor-pointer" onClick={()=>clickedInfo(4)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===4 ? 'border-concept color-param' : 'opacity-75'}`}>Société</pre></li>
                                    <li className="list-inline-item small border-end border-2 border-dark pe-2 cursor-pointer" onClick={()=>clickedInfo(5)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===5 ? 'border-concept color-param' : 'opacity-75'}`}>Economie</pre></li>
                                    <li className="list-inline-item small border-end border-2 border-dark pe-2 cursor-pointer" onClick={()=>clickedInfo(6)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===6 ? 'border-concept color-param' : 'opacity-75'}`}>Culture</pre></li>
                                    <li className="list-inline-item small pe-2 cursor-pointer" onClick={()=>clickedInfo(7)}><pre className={`m-0 p-1 fw-bolder ${infoClicked===7 ? 'border-concept color-param' : 'opacity-75'}`}>Sport</pre></li>
                                </ul>
                            </div>
                        </div>
                    </CardTitle>
                    <CardBody className="mt-2 rounded-bottom-3 mb-0 mx-0 p-0">
                        {htmlInfo}
                    </CardBody>
                </Card>
            </div>
        </>
    )
}

export default Content