import React, {useCallback, useState} from "react";
import {getFileIcon} from "./FileView";
import RenduFile from "../../Model/RenduFile";

const BoxFileview = ({file})=>{
    const [split, setSplit] = useState(file.split("-"));
    const download = useCallback(
        () => {
            RenduFile.downloadFileWithAxios(file).then((r)=>{})
                .catch(()=>{})
        },
        [file],
    );

    return(
        <div className={`col-6 pe-1 height-80 ps-0 py-0 align-items-stretch mb-2 position-relative`}>
            <div onClick={download} className="card w-100 h-100 scale-1 cursor-pointer card-hover">
                <div className="card-header bg-grey">
                    <i className={`fa ${getFileIcon(file)}`} />
                </div>
                <div className="card-body m-0 text-break p-0 d-flex justify-content-center align-items-center rounded-bottom-2 bg-concept text-white">
                    {split[split.length-1]}
                </div>
            </div>
        </div>
    )
}

export default BoxFileview