import {APIURL} from "./APIURL";

export default class Horoscope {
    climatAstral
    humeur
    sign

    constructor(climatAstral, humeur, sign) {
        this.climatAstral = climatAstral;
        this.humeur = humeur;
        this.sign = sign;
    }
    static async getHoroscope(dateNaissance){
        const dt=new Date(dateNaissance)
        const response = await fetch(APIURL() + `horoscope/${dt.getMonth() + 1}/${dt.getDate()}` , {
            method: 'get',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": 'Bearer '+ await window.electronStore.get('token'),
            },
        });

        if (response.ok) {
            return await response.json()
        }else{
            throw new Error('On ne peut pas faire cette requête pour le moment!');
        }
    }
}