import React, {useCallback, useContext, useEffect, useState} from "react";
import SlideBar from "../Component/Slide/SlideBar";
import {Outlet, useNavigate} from "react-router-dom";
import Header from "../Component/Main/Header";
import { UserProvider} from "../Component/Main/Utilitaire/UserProvider";
import {setupFetchInterceptor} from "../Route/fetchInterceptor";
import {Modal} from "react-bootstrap";
import {WSProvider} from "../WS/WSContext";
import {APIURL} from "../Model/APIURL";
import ReloadAll from "../WS/ReloadAll";
import RelLink from "./RelLink";
import { useSelector, useDispatch } from 'react-redux';
import {UserStatusProvider} from "../Component/Main/Salarier/Hook/StatusUserWSContext";

const MemoizedSlideBar = React.memo(SlideBar);
const MemoizedHeader = React.memo(Header);

const Home = () => {
    const [idActive,setActive]=useState(1)
    const setID = (id)=>{
        dispatch({ type: "SET_ETAT", payload: id });
    }
    const count = useSelector((state) => state.etat);
    const dispatch = useDispatch();
    useEffect(() => {
        setActive(count)
    }, [count]);

    const [nextVal, setNextVal] = useState(1);
    const navigate=useNavigate()
    const [loading, setLoading] = useState(false);
    useEffect(()=>{
        if (window.electronStore.get('token')===null || window.electronStore.get('token')===undefined){
            navigate("/")
        }else{
            setupFetchInterceptor(
                () => setLoading(true),
                () => setLoading(false)
            );
        }
    },[])

    const setValue = useCallback( (value) => {
        // setActive(value)
        setNextVal(value)
    },[])

    useEffect(() => {
        setActive(nextVal)
    }, [nextVal]);


    return(
        <>
            <div className="bg-opacity-25 content w-100 min-vh-100 position-relative">
                <UserProvider>
                    <WSProvider url={APIURL() + "ws"}>
                        <MemoizedSlideBar idActive={count} setActive={setID} />
                        <div className="float-end position-relative w-rest pt-3 px-2 vh-100 d-grid" style={{ gridTemplateRows: 'auto auto 1fr' }}>
                            {/*//utilisaterS status...manome status(active ou pas deconneter) atao ao anaty context ilay izy de mety tsara...ilaina ao am header(message) sy list mantsy*/}
                            <UserStatusProvider>
                                <MemoizedHeader idActive={count} setActive={setID}/>
                                <div className="m-t-4 w-100 rounded-3">
                                    <div id="head"/>
                                    <Outlet />
                                </div>
                            </UserStatusProvider>
                        </div>
                        <ReloadAll setActive={setActive}/>
                    </WSProvider>
                    <RelLink setNonValider={setValue} nextValue={nextVal} currentValue={idActive}/>
                </UserProvider>
            </div>
            {loading && (
                <Modal show={loading} dialogClassName="rounded-3 width-max" centered  >
                    <Modal.Body className="p-1 mb-0 rounded-3 ">
                        <div className="p-3">
                            <pre className="fs-4 m-0 p-0 ripple-text">Chargement...</pre>
                        </div>
                    </Modal.Body>
                </Modal>
            )}
        </>
    )
}
export default Home