import {APIURL} from "./APIURL";

export class Event {
    static uploadEvent = async (titre, content, files, date) => {
        const formData = new FormData();
        files.forEach(file => {
            formData.append("files", file);
        });

        formData.append("titre", titre);
        formData.append("content", content);
        formData.append("date", date);
        const token = await window.electronStore.get('token');
        const response = await fetch(APIURL()+"event/", {
            method: "POST",
            headers: {
                "Authorization": `Bearer ${token}`,
            },
            body: formData,
        });

        if (response.ok) {
            return true;
        } else {
            throw new Error("Erreur lors de l'upload des fichiers");
        }
    }

    static getEvents = async () => {
        const token = await window.electronStore.get('token');
        const response = await fetch(`${APIURL()}event/`, {
            method: "get",
            headers: {
                "Authorization": `Bearer ${token}`,
            },
        });

        if (response.ok) {
            const result = await response.json();
            return result;
        } else {
            throw new Error("Erreurs lors de l'initialisation des données");
        }
    }
}