import React, {useCallback, useMemo, useState} from "react";
import {Modal, Button, Col, Form, Toast} from "react-bootstrap";
import { differenceInYears } from 'date-fns'
import {APIURL} from "../../../Model/APIURL";
import {format} from "../../Conge/Detail";
import {formatDateToInputValue, genres, niveaus, statuts, validateAge} from "../../InfoPersonel";
import {allBanque} from "../../InfoBanque";
import Allinfo from "../../../Model/Allinfo";

export const handleTelChange = (e) => {
    let value = e.replace(/[^\d+]/g, '');
    if (value[0] !== '+') {
        value = '+261' + value.replace(/\D/g, '');
    }
    if (!value.startsWith('+261')) {
        value = '+261' + value.slice(value.startsWith('261') ? 3 : 0);
    }
    const mainNumber = value.slice(4).replace(/\D/g, '').slice(0, 9);
    const part1 = mainNumber.slice(0, 2);
    const part2 = mainNumber.slice(2, 4);
    const part3 = mainNumber.slice(4, 7);
    const part4 = mainNumber.slice(7);

    let formatted = '+261 ';
    if (part1) formatted += `${part1}`;
    if (part2) formatted += ` ${part2}`;
    if (part3) formatted += ` ${part3}`;
    if (part4) formatted += ` ${part4}`;
    return formatted
};

const VoirInfo = ({show, close, person,setNewPerson, valider=()=>{}, location=2, supprimer = ()=>{}}) => {
    const age=useCallback(()=>{
        if (person && person.emp.employe.naissance) {
            return differenceInYears(new Date(), new Date(person.emp.employe.naissance));
        }
        return 0;
    },[person])

    const [isModifClicked, setIsModifClicked] = useState(false);

    const [types, setTypes] = useState([
        {idType: 1, poste: 'Direction'},
        {idType: 2, poste: 'Ingénieurs en BTP'},
        {idType: 3, poste: 'Développeur'},
        {idType: 4, poste: 'Technicien'},
        {idType: 5, poste: 'Salarié'},
    ]);

    const [editableValues, setEditableValues] = useState({
        nom: person?.emp.employe.nom || "",
        prenom: person?.emp.employe.prenom || "",
        tel: person?.emp.employe.tel || "",
        adresse: person?.emp.employe.adresse || "",
        nationalite: person?.emp.employe.nationalite || "",
        cin: person?.emp.employe.cin || "",
        enfant: person?.emp.employe.enfant,
        genre: person?.emp.employe.genre,
        statut: person?.emp.employe.statut,
        naissance: person.emp.employe.naissance,
        dateEntre: person.emp.dateEntre,
        niveau: person.emp.employe.niveau,
        type: person?.emp.employe.type,
        matricule: person?.emp.employe.matricule,
        numCnaps: person?.emp.numCnaps,
        rib: person?.emp.rib,
        banque: person?.emp.banque,
    });

    const [validationErrors, setValidationErrors] = useState({
        validPrenom: true,
        validNom: true,
        validTel: true,
        validCIN: true,
        validNaissance: true,
        validDateEntre: true,
    });

    const handleInputChange = (field, value) => {
        setEditableValues((prev) => ({ ...prev, [field]: value }));
    };


    const [erreur, setErreur] = useState(false);
    const [erreurText, setErreurText] = useState("");
    const submit = useCallback(
        () => {
            const isValidNaissance = validateAge(editableValues.naissance);

            const errors = {
                validPrenom: editableValues.prenom.trim().length > 0,
                validNom: editableValues.nom.trim().length >0,
                validTel: editableValues.tel.length >= 17,
                validCIN: editableValues.cin.length > 14,
                validNaissance: isValidNaissance,
                validDateEntre: true,
            };

            setValidationErrors(errors);
            const isValid = Object.values(errors).every(Boolean);

            if (!isValid) {
                return;
            }else{
                const modifPerson ={...person,
                    emp:{
                        ...person.emp,
                        banque: editableValues.banque,
                        rib: editableValues.rib,
                        numCnaps: editableValues.numCnaps,
                        dateEntre: editableValues.dateEntre,
                        employe:{
                            ...person.emp.employe,
                            matricule: editableValues.matricule,
                            type: editableValues.type,
                            niveau: editableValues.niveau,
                            naissance: editableValues.naissance,
                            statut: editableValues.statut,
                            genre: editableValues.genre,
                            enfant: editableValues.enfant,
                            cin: editableValues.cin,
                            nationalite: editableValues.nationalite,
                            adresse: editableValues.adresse,
                            tel: editableValues.tel,
                            prenom: editableValues.prenom,
                            nom: editableValues.nom
                        }
                    }}
                Allinfo.updateEmp(modifPerson).then((e)=>{
                    close()
                    setNewPerson(modifPerson)
                    //enchainement de validation selon useLocation
                }).catch((e)=>{
                    setErreurText(e.message)
                    setErreur(true)
                    //gestion des erreurs
                })
            }
        },
        [editableValues,validationErrors],
    );

    return(
        <>
            <Modal
                show={show}
                onHide={close}
                keyboard={false}
                backdrop="static"
                dialogClassName="modal-dialog-centered modal-90w position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center w-100"
            >
                <Modal.Header className="d-inline-flex justify-content-between position-relative">
                    <Modal.Title className="flex-grow-1">Info sur un employé</Modal.Title>
                    {!isModifClicked && (
                        <div className="cursor-pointer" onClick={()=>setIsModifClicked(true)}>
                            <span className="mx-2">
                                <i className="text-concept fa fa-user-edit fa-2x"/>
                            </span>
                        </div>
                    )}
                    <div onClick={()=>close()} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body>
                    {person?.emp.employe.profile && (
                        <div className="d-flex justify-content-center mt-0 pt-0">
                            <img
                                src={APIURL()+`${person?.emp.employe.profile}`}
                                alt="captured or uploaded"
                                className="border-dark-light rounded-circle mt-0 pt-0"
                                width={130} height={130}
                                style={{ objectFit: 'cover' }}
                                decoding={"async"}
                            />
                        </div>
                    )}
                    <div className="d-flex justify-content-start mb-2">
                        <h6 className="small text-uppercase fw-bolder">Info Personelle</h6>
                    </div>
                    {isModifClicked ? (
                        <div className="row m-0 p-0">
                            <Form.Group className="mb-2 border-end" as={Col} md="4" controlId="nom">
                                <Form.Label className="small">Nom</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    autoFocus
                                    // disabled={loading}
                                    // type={showMdp ? 'text' : 'password'}
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={editableValues.nom}
                                    onChange={(e)=>handleInputChange("nom",e.target.value)}
                                    isInvalid={!validationErrors.validNom}
                                />
                            </Form.Group>
                            <Form.Group className="mb-2 border-end" as={Col} md="4" controlId="prenom">
                                <Form.Label className="small">Prénom</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    // disabled={loading}
                                    // type={showMdp ? 'text' : 'password'}
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={editableValues.prenom}
                                    onChange={(e)=>handleInputChange("prenom",e.target.value)}
                                    isInvalid={!validationErrors.validPrenom}
                                />
                            </Form.Group>
                            <Form.Group className="mb-2" as={Col} md="4" controlId="Tel">
                                <Form.Label className="small">Tel</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={editableValues.tel}
                                    onChange={(e)=>handleInputChange("tel",handleTelChange(e.target.value))}
                                    isInvalid={!validationErrors.validTel}
                                />
                            </Form.Group>

                            <hr className="mt-2"/>
                            <Form.Group className="mb-2 border-end" as={Col} md="4" controlId="nationalite">
                                <Form.Label className="sm">Nationalité</Form.Label>
                                <Form.Select size={"sm"} value={editableValues.nationalite} onChange={(e)=> handleInputChange('nationalite',e.target.value)} className="bg-transparent fw-bolder border-dark-light" required>
                                    <option className="text-dark" value={"Malagasy"}>Malagasy</option>
                                    <option className="text-dark" value={"Etranger"}>Etranger</option>
                                </Form.Select>
                            </Form.Group>
                            <Form.Group className="mb-2 border-end" as={Col} md="4" controlId="cin">
                                <Form.Label className="small">CIN</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={editableValues.cin}
                                    onChange={(e) => {
                                        let value = e.target.value.replace(/\D/g, '').slice(0, 12);
                                        value = value.replace(/(.{3})/g, '$1 ').trim();
                                        handleInputChange("cin", value);
                                    }}
                                    isInvalid={!validationErrors.validCIN}
                                />
                            </Form.Group>
                            <Form.Group className="mb-2" as={Col} md="4" controlId="adress">
                                <Form.Label className="small">Adresse</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    // disabled={loading}
                                    // type={showMdp ? 'text' : 'password'}
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={editableValues.adresse}
                                    onChange={(e)=>handleInputChange("adresse",e.target.value)}
                                    // isInvalid={mdp.length<6 && mdp.length>0}
                                />
                            </Form.Group>
                            <hr className="mt-2"/>

                            <Form.Group className="mb-2 border-end" as={Col} md="3" controlId="Genre">
                                <Form.Label className="sm">Genre</Form.Label>
                                <Form.Select size={"sm"} value={editableValues.genre.id} onChange={(e)=> handleInputChange('genre', genres.find(g => g.id === parseInt(e.target.value, 10)))} className="bg-transparent fw-bolder border-dark-light" required>
                                    {genres.map(g => (
                                        <option key={g.id} className="text-dark" value={g.id}>{g.genre}</option>
                                    ))}
                                </Form.Select>
                            </Form.Group>
                            <Form.Group className="mb-2 border-end" as={Col} md="3" controlId="Statut">
                                <Form.Label className="sm">Statut Mat</Form.Label>
                                <Form.Select size={"sm"} value={editableValues.statut.id} onChange={(e)=> handleInputChange('statut', statuts.find(g => g.id === parseInt(e.target.value, 10)))} className="bg-transparent fw-bolder border-dark-light" required>
                                    {statuts.map(g => (
                                        <option key={g.id} className="text-dark" value={g.id}>{g.value}</option>
                                    ))}
                                </Form.Select>
                            </Form.Group>

                            <Form.Group className="mb-2 border-end" as={Col} md="3" controlId="enfant">
                                <Form.Label className="small">Nb enfant</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    // disabled={loading}
                                    type="number"
                                    min={0}
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={parseInt(editableValues.enfant)}
                                    onChange={(e)=>handleInputChange("enfant",e.target.value)}
                                    // isInvalid={mdp.length<6 && mdp.length>0}
                                />
                            </Form.Group>

                            <Form.Group className="mb-2" as={Col} md="3" controlId="Naissance">
                                <Form.Label className="small">Date Naissance</Form.Label>
                                <Form.Control
                                    size={"sm"}
                                    required
                                    // disabled={loading}
                                    type="date"
                                    className="bg-transparent border-dark-light fw-bolder"
                                    value={formatDateToInputValue(new Date(editableValues.naissance))}
                                    onChange={(e)=>handleInputChange("naissance",new Date(e.target.value))}
                                    isInvalid={!validationErrors.validNaissance}
                                />
                            </Form.Group>

                            <hr className="mt-2"/>
                            <div className="d-flex justify-content-start mt-3 mb-2">
                                <h6 className="small text-uppercase fw-bolder">Info RH</h6>
                            </div>
                            <div className="row m-0 p-0 w-100">
                                <Form.Group className="mb-2 border-end" as={Col} md="3" controlId="entre">
                                    <Form.Label className="small">Date d'entrée</Form.Label>
                                    <Form.Control
                                        size={"sm"}
                                        required
                                        type="date"
                                        className="bg-transparent border-dark-light fw-bolder"
                                        value={formatDateToInputValue(new Date(editableValues.dateEntre))}
                                        onChange={(e)=>handleInputChange("dateEntre",new Date(e.target.value))}
                                        isInvalid={!validationErrors.validDateEntre}
                                    />
                                </Form.Group>
                                <Form.Group className="mb-2 border-end" as={Col} md="3" controlId="etude">
                                    <Form.Label className="sm">Niveau d'Etude</Form.Label>
                                    <Form.Select size={"sm"} value={editableValues.niveau.id} onChange={(e)=> handleInputChange('niveau', niveaus.find(g => g.id === parseInt(e.target.value, 10)))} className="bg-transparent fw-bolder border-dark-light" required>
                                        {niveaus.map(g => (
                                            <option key={g.id} className="text-dark" value={g.id}>{g.value}</option>
                                        ))}
                                    </Form.Select>
                                </Form.Group>
                                <Form.Group className="mb-2 border-end" as={Col} md="3" controlId="poste">
                                    <Form.Label className="sm">Poste</Form.Label>
                                    <Form.Select size={"sm"} value={editableValues.type.idType} onChange={(e)=> handleInputChange('type', types.find(g => g.idType === parseInt(e.target.value, 10)))} className="bg-transparent fw-bolder border-dark-light" required>
                                        {types.map(g => (
                                            <option key={g.idType} className="text-dark" value={g.idType}>{g.poste}</option>
                                        ))}
                                    </Form.Select>
                                </Form.Group>
                                <Form.Group className="mb-2" as={Col} md="3" controlId="Matricule">
                                    <Form.Label className="small">Matricule</Form.Label>
                                    <Form.Control
                                        size={"sm"}
                                        required
                                        className="bg-transparent border-dark-light fw-bolder"
                                        value={editableValues.matricule.split('').join(' ')}
                                        onChange={(e)=>{
                                                let value = e.target.value.replace(/\D/g, '')
                                                if (value.length > 0 && value[0] === '0') {
                                                    value = value.substring(1)
                                                }
                                                if (value.length > 4) {
                                                    value = value.slice(0, 4)
                                                } else {
                                                    value = value.padStart(4, '0')
                                                }
                                            handleInputChange("matricule",value)
                                        }}
                                    />
                                </Form.Group>
                                <hr className="mt-2"/>
                                <Form.Group className="mb-2 border-end" as={Col} md="4" controlId="cnaps">
                                    <Form.Label className=" fw-bold">Numeros CNAPS</Form.Label>
                                    <Form.Control
                                        size={"sm"}
                                        className="bg-transparent border-dark-light fw-bolder"
                                        value={editableValues.numCnaps}
                                        onChange={(e)=>{
                                            let value=e.target.value
                                            value = value.replace(/\D/g, '')
                                            handleInputChange("numCnaps",value.replace(/(.{4})/g, '$1 ').trim())
                                        }}
                                    />
                                </Form.Group>
                                <Form.Group className="mb-2 border-end" as={Col} md="4" controlId="Banque">
                                    <Form.Label className="sm">Banque</Form.Label>
                                    <Form.Select size={"sm"} value={editableValues.banque.id} onChange={(e)=> handleInputChange('banque', allBanque.find(g => g.id === parseInt(e.target.value, 10)))} className="bg-transparent fw-bolder border-dark-light" required>
                                        {allBanque.map(g => (
                                            <option key={g.id} className="text-dark" value={g.id}>{g.value}</option>
                                        ))}
                                    </Form.Select>
                                </Form.Group>

                                <Form.Group className="mb-2" as={Col} md="4" controlId="rib">
                                    <Form.Label className=" fw-bold">RIB</Form.Label>
                                    <Form.Control
                                        size={"sm"}
                                        className="bg-transparent border-dark-light fw-bolder"
                                        value={editableValues.rib}
                                        onChange={(e)=>{
                                            let value=e.target.value
                                            value = value.replace(/\D/g, '')
                                            handleInputChange("rib",value.replace(/(.{4})/g, '$1 ').trim())
                                        }}
                                    />
                                </Form.Group>
                            </div>
                        </div>
                    ) : (
                        <div className="row m-0 p-0">
                            <div className="col-4 mb-2 border-end">
                                <pre className="m-0 p-0">Nom : <span className="text-center fs-5 text-uppercase">{person?.emp.employe.nom}</span></pre>
                            </div>
                            <div className="col-4 mb-2 border-end">
                                <pre className="m-0 p-0">Prénom : <span className="text-center fs-5 text-capitalize"> {person?.emp.employe.prenom}</span></pre>
                            </div>
                            <div className="col-4 mb-2">
                                <pre className="m-0 p-0">Tel : <span className="text-center fs-5 text-capitalize">{person?.emp.employe.tel}</span></pre>
                            </div>
                            <hr/>
                            <div className="col-4 mb-2 border-end">
                                <pre className="m-0 p-0">Nationalité : <span className="text-center fs-5">{person.emp.employe.nationalite}</span></pre>
                            </div>
                            <div className="col-4 mb-2 border-end">
                                <pre className="m-0 p-0">CIN : <span className="text-center fs-5">{person.emp.employe.cin}</span></pre>
                            </div>
                            <div className="col-4 mb-2 ">
                                <pre className="m-0 p-0">Adresse : <span className="text-center fs-5">{person.emp.employe.adresse}</span></pre>
                            </div>
                            <hr/>
                            <div className="col-3 mb-2 border-end">
                                <pre className="m-0 p-0">Genre : <span className="text-center fs-5">{person.emp.employe.genre.genre}</span></pre>
                            </div>
                            <div className="col-3 mb-2 border-end">
                                <pre className="m-0 p-0">Statut Mat : <span className="text-center fs-5">{person.emp.employe.statut.value}</span></pre>
                            </div>
                            <div className="col-3 mb-2 border-end">
                                <pre className="m-0 p-0">Nb enfant : <span className="text-center fs-5">{person.emp.employe.enfant}</span></pre>
                            </div>
                            <div className="col-3 mb-2">
                                <pre className="m-0 p-0">Age : <span className="text-center fs-5">{age()}</span></pre>
                            </div>
                            <hr/>
                            <div className="d-flex justify-content-start mt-3 mb-2">
                                <h6 className="small text-uppercase fw-bolder">Info RH</h6>
                            </div>
                            <div className="row m-0 p-0 w-100">
                                <div className="col-3 mb-2 border-end">
                                    <pre className="m-0 p-0">Date d'entrée : <span className="text-center fs-5">{format(new Date(person.emp.dateEntre))}</span></pre>
                                </div>
                                <div className="col-3 mb-2 border-end">
                                    <pre className="m-0 p-0">Etude : <span className="text-center fs-5">{person.emp.employe.niveau.value}</span></pre>
                                </div>
                                <div className="col-3 mb-2 border-end">
                                    <pre className="m-0 p-0">Poste : <span className="text-center fs-5">{person.emp.employe.type.poste}</span></pre>
                                </div>
                                <div className="col-3 mb-2">
                                    <pre className="m-0 p-0">M° : <span className="text-center fs-5">{person.emp.employe.matricule}</span></pre>
                                </div>
                                <hr/>
                                <div className="col-4 mb-2 border-end">
                                    <pre className="m-0 p-0">CNAPS : <span className="text-center fs-5">{person.emp.numCnaps==='' ? 'null' : person.emp.numCnaps}</span></pre>
                                </div>
                                <div className="col-4 mb-2 border-end">
                                    <pre className="m-0 p-0">Banque : <span className="text-center fs-5">{person.emp.banque.value}</span></pre>
                                </div>
                                <div className="col-4 mb-2">
                                    <pre className="m-0 p-0">RIB : <span className="text-center fs-5">{person.emp.rib==='' ? 'null' : person.emp.rib}</span></pre>
                                </div>
                                <hr/>
                            </div>
                            <div className="d-flex justify-content-start mt-3 mb-2">
                                <h6 className="small text-uppercase fw-bolder">Contact Rapide</h6>
                            </div>
                            <div className="row m-0 p-0 w-100">
                                <div className="col-6 mb-2 border-end">
                                    <pre className="m-0 p-0">Nom du contact : <span className="text-center fs-5">{person.emp.contact}</span></pre>
                                </div>
                                <div className="col-6 mb-2">
                                    <pre className="m-0 p-0">Numeros : <span className="text-center fs-5">{person.emp.tel}</span></pre>
                                </div>
                            </div>
                        </div>
                    )}
                </Modal.Body>
                {isModifClicked ? (
                    <Modal.Footer>
                        <Button variant="danger" onClick={()=>setIsModifClicked(false)}>Annuler</Button>
                        <Button variant="primary" onClick={submit}>Sauvegarder</Button>
                    </Modal.Footer>
                ) : location===1 && (
                    <Modal.Footer>
                        <Button variant="danger" onClick={()=>{
                            supprimer(person.idEtat)
                            close()
                        }}>Supprimer</Button>
                        <Button variant="primary" className="px-3" onClick={()=> {
                            valider(person.emp.employe.idEmp)
                            close()
                        }}>Valider</Button>
                    </Modal.Footer>
                )}
                {erreur && (
                    <div className="position-fixed bottom-0 end-0 width-max p-2">
                        <Toast bg={"danger"} show={erreur} onClose={()=>setErreur(false)} autohide delay={5000}>
                            <Toast.Header>
                                <i className="rounded me-2 text-aris icon-30 fas fa-circle-exclamation"/>
                                <strong className="me-auto">Erreur</strong>
                                <small className="text-muted">Maintenant</small>
                            </Toast.Header>
                            <Toast.Body className><strong>{erreurText}</strong></Toast.Body>
                        </Toast>
                    </div>
                )}
            </Modal>
        </>
    )
}
export default VoirInfo