import React, {useCallback, useState} from "react";
import {Col, Form, Modal, Row} from "react-bootstrap";
import {SalaireBase} from "../../../Model/Paie/SalaireBase";

const ModifCotisation = ({show,hide, type, setCurrentValue})=>{

    const [changeValue, setChangeValue] = useState({
        valeur: 0,
        type: 1,
    });

    const submit = useCallback(
        () => {
            if (changeValue.valeur>0){
                SalaireBase.addCotisation(type.id, changeValue.valeur, changeValue.type).then(()=>{
                    setCurrentValue({valeur: changeValue.valeur, type: changeValue.type ===1 ? "POURCENTAGE" : "MGA"})
                }).catch(()=>{}).finally(()=>{
                    hide()
                })
            }
        },
        [changeValue,type],
    );

    return(
        <>
            <Modal
                show={show}
                onHide={hide}
                keyboard={false}
                backdrop="static"
                autoFocus={true}
                dialogClassName="modal-dialog-centered  position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center modal-70w"
            >
                <Modal.Header className="position-relative">
                   <strong> Modification : Cotisation {type.nom}</strong>
                    <div onClick={()=>hide()} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="pt-1">
                    <div className="row mt-0 mx-0 mb-3 p-0 w-100">
                        <Form.Group className="p-0 m-0" as={Col} md="8" controlId="valeur">
                            <Form.Label className="fw-bold">Valeur</Form.Label>
                            <Form.Control
                                type="text"
                                className="bg-transparent border-dark-light"
                                autoFocus={true}
                                value={changeValue.valeur}
                                onChange={(e) => {
                                    let val = e.target.value.replace(/[^0-9.]/g, '');
                                    val = val.replace(/(\..*)\./g, '$1');

                                    setChangeValue((prev) => ({ ...prev, valeur: val }));
                                }}
                                placeholder="valeur"
                                required
                            />
                        </Form.Group>
                        <Form.Group className="m-0 ps-2 pe-0 py-0" as={Col} md="4" controlId="type">
                            <Form.Label className="fw-bold">Type</Form.Label>
                            <Form.Select
                                value={changeValue.type}
                                onChange={(e) => setChangeValue(prev => ({
                                    ...prev, type: parseInt(e.target.value)
                                }))}
                                className="bg-transparent border-dark-light"
                                required
                            >
                                <option className="text-dark" value={1}>Pourcentage</option>
                                <option className="text-dark" value={2}>MGA</option>
                            </Form.Select>
                        </Form.Group>
                    </div>
                    <Row>
                        <Col md={6}>
                            <button type="button" onClick={()=>hide()} className="btn btn-sm bg-aris text-white w-100">Annuler</button>
                        </Col>
                        <Col md={6}>
                            <button type="button" onClick={submit} className="btn btn-sm bg-blue text-white w-100">Valider</button>
                        </Col>
                    </Row>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default ModifCotisation