import React, {useEffect, useState} from "react";
import TopInfo from "../../Model/TopInfo";
import {Carousel} from "react-bootstrap";
import Horoscope from "../../Model/Horoscope";

const Flash = ({usercontext}) => {
    const [topInfo,setTopInfo]=useState([])
    const [loadingHP,setLoadingHP]=useState(true)
    const [horoscope,setHoroscope]=useState(null)
    useEffect(()=>{
        TopInfo.getTopInfo().then((res)=>{
            setTopInfo(res)
        }).catch((er)=>{
            console.log(er.message)
        })
    },[])
    useEffect(()=>{
        setLoadingHP(true)
        if (usercontext){
            Horoscope.getHoroscope(usercontext?.naissance).then((res)=>{
                setHoroscope(res)
            }).catch((e)=>{
                console.log(e)})
                .finally(()=>{
                setLoadingHP(false)
            })
        }
    },[usercontext])
    return (
        <>
            <div className="w-100 m-0 p-0 row">
                <div className="ps-0 col-8">
                    <Carousel prevIcon={topInfo.length===0 && null} prevLabel={topInfo.length===0 && null} nextIcon={topInfo.length===0 && null} nextLabel={topInfo.length===0 && null}>
                        {topInfo.map(({linkImage, date,desc, linkDetail},index)=>(
                            <Carousel.Item key={index} interval={2000}>
                                <div className="w-100" style={{
                                    height: '475px',
                                    backgroundImage: `url(${linkImage})`,
                                    backgroundSize: 'cover',
                                    backgroundPosition: 'center',
                                }}>
                                </div>
                                <Carousel.Caption className="start-0 w-100">
                                    <div className="text-start mb-1 small opacity-75">
                                        <i className="fa-solid fa-calendar mx-2"/> {date}
                                    </div>
                                    <h4>{desc}</h4>
                                </Carousel.Caption>
                            </Carousel.Item>
                        ))}
                    </Carousel>
                </div>
                <div className="col-4 p-0 bg-body-tertiary">
                    {loadingHP ? (
                        <>
                            <div className="w-100 bg-body-secondary pt-3 pb-2 text-center mb-1 text-concept">
                                <div className="skeleton skeleton-heading"/>
                            </div>
                            <div className="p-2 row m-0">
                                <div className="skeleton skeleton-text w-50" />
                                <div className="skeleton skeleton-text" style={{width: '100%'}}/>
                                <div className="skeleton skeleton-text" style={{width: '90%'}}/>
                                <div className="skeleton skeleton-text" style={{width: '85%'}}/>
                            </div>
                            <div className="p-2 row m-0">
                                <div className="skeleton w-50 skeleton-text" />
                                <div className="skeleton skeleton-text" style={{width: '100%'}}/>
                                <div className="skeleton skeleton-text" style={{width: '90%'}}/>
                                <div className="skeleton skeleton-text" style={{width: '85%'}}/>
                            </div>
                        </>
                    ): (
                        <>
                            <div className="w-100 bg-body-secondary pt-3 pb-2 text-center mb-1 text-concept">
                                <strong>Horoscope du {horoscope?.sign} aujourd'hui</strong>
                            </div>
                            <div className="p-2 row m-0">
                                <h5 className="text-aris"><i className="fas fa-circle me-1 fs-7 text-black"/>Votre climat astral</h5>
                                <p className="m-0 p-0">
                                    {horoscope?.climatAstral}
                                </p>
                            </div>
                            <div className="p-2 row m-0">
                                <h5 className="text-aris"><i className="fas fa-circle me-1 fs-7 text-black"/>Humeur</h5>
                                <p className="m-0 p-0">
                                    {horoscope?.humeur}
                                </p>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </>
    )
}
export default Flash