import React, {useCallback, useEffect, useState} from "react";
import {Dropdown, Form} from "react-bootstrap";
import {APIURL} from "../../../Model/APIURL";
import {formatNumber} from "./ViewSalaireBrute";

export const userProfile=(user)=>{
    if (user?.profile){
        return (
            <img
                src={APIURL()+`${user.profile}`}
                alt=""
                className="border-dark-light rounded-circle mt-0  p-0"
                width={40} height={40}
                style={{ objectFit: 'cover'}}
            />
        )
    }else{
        return (
            <span className="cursor-pointer position-relative d-flex justify-content-center bg-secondary  border-dark-light rounded-circle" style={{width:'42px', height: '42px'}}>
                <i className={`far icon-20 fa-user-circle  my-auto ${user===null ? 'text-concept': 'text-white'}`}/>
            </span>
        )
    }

}

const PersIndView = ({element,setIdChecked, idChecked})=>{
    const [checkClicked, setCheckClicked] = useState(idChecked.some(e=>element.emp.idEmp === e));

    useEffect(() => {
        setCheckClicked(idChecked.some(e=>element.emp.idEmp === e))
    }, [idChecked]);


    return(
        <tr onClick={()=>{
            setCheckClicked(prev => {
                if (prev){
                    setIdChecked(el =>el.filter(k=>k !==element.emp.idEmp))
                }else{
                    setIdChecked(el=>[...el, element.emp.idEmp])
                }
                return !prev
            })
        }} className="cursor-pointer" >
            <td className="p-0 bg-warning">
                <div className="d-flex justify-content-center align-items-center w-100  m-0 p-0" style={{ minHeight: "40px" }}>
                    <Form.Check
                        type="checkbox"
                        className="m-0 cursor-pointer"
                        id={`validation-${element.idIndemnite}`}
                        checked={checkClicked}
                        onChange={()=>{}}
                    />
                </div>
            </td>

            <td>
                {userProfile(element.emp)}
            </td>
            <th scope="row">{String(element.emp.matricule).padStart(4, '0')}</th>
            <td>{element.emp.nom}</td>
            <td>{element.emp.prenom}</td>
            <td>{element.emp.type.poste}</td>
            <td className="fw-bold h4-Edit text-center" >{formatNumber(element.valeur)}</td>
            <td>{element.periode ? element.periode : '--'}</td>
        </tr>
    )
}

export default PersIndView