import React, {useCallback, useMemo, useState} from "react";
import {Col, Form, Modal, Row} from "react-bootstrap";
import {SalaireBase} from "../../../Model/Paie/SalaireBase";
import {getNextDateMonth} from "../Paramettre";

const ViewInterval = ({show,hide, setCurrentValue, currentValue})=>{

    const [changeValue, setChangeValue] = useState(currentValue);
    const date = useMemo(() => getNextDateMonth(changeValue), [changeValue]);

    const submit = useCallback(
        () => {
            SalaireBase.addInterval(date.firstDay.toLocaleDateString("fr-FR",{day: 'numeric'})).then(()=>{
                setCurrentValue(date.firstDay.toLocaleDateString("fr-FR",{day: 'numeric'}))
            }).catch(()=>{}).finally(()=>{
                hide()
            })
        },
        [date],
    );

    return(
        <>
            <Modal
                show={show}
                onHide={hide}
                keyboard={false}
                backdrop="static"
                autoFocus={true}
                dialogClassName="modal-dialog-centered  position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center modal-70w"
            >
                <Modal.Header className="position-relative">
                    <strong>Modifier l'interval de temps de payement</strong>
                    <div onClick={()=>hide()} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="pt-1">
                    <div className="mt-0 d-inline-flex justify-content-between mx-0 mb-2 p-0 w-100 ">
                        <Form.Group className="p-0 m-0" controlId="valeur">
                            <Form.Label className="fw-bold">Debut</Form.Label>
                            <Form.Control
                                type="date-day"
                                className="bg-transparent border-dark-light"
                                autoFocus={true}
                                size={"sm"}
                                value={changeValue}
                                onChange={(e) => {
                                    let val = e.target.value.replace(/[^0-9.]/g, '');
                                    val = val.replace(/(\..*)\./g, '$1');

                                    setChangeValue(val);
                                }}
                                placeholder="valeur"
                                required
                            />
                        </Form.Group>
                        <div className="d-flex align-items-center">
                            <i className="fa align-middle fa-right-long mt-4"/>
                        </div>
                        <Form.Group className="p-0 m-0" controlId="fin">
                            <Form.Label className="fw-bold">Fin</Form.Label>
                            <Form.Control
                                type="date-day"
                                size={"sm"}
                                className="bg-transparent border-dark-light"
                                autoFocus={true}
                                value={date.lastDay.toLocaleDateString("fr-FR", {day: 'numeric'})}
                                onChange={(e) => {
                                    let val = e.target.value.replace(/[^0-9.]/g, '');
                                    val = val.replace(/(\..*)\./g, '$1');

                                    setChangeValue((prev) => ({ ...prev, initial: val }));
                                }}
                                placeholder="valeur"
                                disabled
                            />
                        </Form.Group>
                    </div>
                    <div className="w-100 mb-3 d-inline-flex">
                        <p className="h4-Edit fst-italic mb-0 text-decoration-underline underline-spacing">Exemple :</p>
                        <span className="ms-2 text-print fw-bold">{date.firstDay.toLocaleDateString("fr-FR", {day: 'numeric', month: 'short'})} <i className="fa align-middle fa-arrow-right mx-2"/> {date.lastDay.toLocaleDateString("fr-FR", {day: 'numeric', month: 'short'})}</span>
                    </div>
                    <Row>
                        <Col md={6}>
                            <button type="button" onClick={()=>hide()} className="btn btn-sm bg-aris text-white w-100">Annuler</button>
                        </Col>
                        <Col md={6}>
                            <button type="button" onClick={submit} className="btn btn-sm bg-blue text-white w-100">Valider</button>
                        </Col>
                    </Row>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default ViewInterval