import {APIURL} from "../../../Model/APIURL";
import React, {useCallback, useEffect, useMemo, useState} from "react";
import {addDays, getDate} from "date-fns";
import TDOverlay from "./TDOverlay";
import Conge from "../../../Model/Conge";
import { Button } from 'primereact/button';
import {Modal, Form, Col} from "react-bootstrap";
import {formatDateToInputValue} from "../../InfoPersonel";
import {differenceEnJours, formatNumberDay} from "../Demande";

const ViewSolde = ({element})=>{
    const [year, setYear] = useState((new Date()).getFullYear());
    const [dateClicked, setDateClicked]=useState(null)
    const [values, setValues] = useState(element.perMonth);

    const monthYear = useMemo(()=>{
        return ["Jan", "Fev", "Mar", "Avr", "Mai", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    },[])
    const daysInWeek = useMemo(()=>{
        return ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam']
    },[])
    const [monthClicked,setMonthClicked]=useState(0)

    const daysInMonth = useMemo(() => new Date(year, monthClicked, 0).getDate(), [year, monthClicked]);
    const firstDayOfMonth = useMemo(() => new Date(year, monthClicked - 1, 1).getDay(), [year, monthClicked]);
    const dates = useMemo(() => {
        const initialDates = Array(firstDayOfMonth).fill(null).concat(
            Array.from({ length: daysInMonth }, (_, i) => i + 1)
        );
        while (initialDates.length % 7 !== 0) {
            initialDates.push(null);
        }
        return initialDates;
    }, [daysInMonth, firstDayOfMonth]);
    const isComprise = useCallback(
        (jour)=> {
            if (dateClicked){
                const plageTrouvee = dateClicked.find(({ dateDebut, dateFin }) => {
                    const debut = getDate(new Date(dateDebut));
                    const fin = getDate(new Date(dateFin));
                    return jour >= debut && jour <= fin;
                });

                if (plageTrouvee) {
                    return {
                        comprise: true,
                        cause: plageTrouvee.cause,
                        dateDemande: plageTrouvee.dateDemande
                    };
                }
            }
            return {
                comprise: false,
                cause: null,
                dateDemande: null
            };
        },[dateClicked]);

    const showCongerPerMonth = useMemo(() => {
        if (monthClicked>0 && dateClicked){
            return (
                <table className="days-table w-100 mt--10">
                    <thead>
                    <tr>
                        {daysInWeek.map((day, index) => (
                            <th key={index} className="day p-0">{day}</th>
                        ))}
                    </tr>
                    </thead>
                    <tbody>
                    {Array.from({ length: dates.length / 7 }, (_, weekIndex) => (
                        <tr key={weekIndex}>
                            {dates.slice(weekIndex * 7, (weekIndex + 1) * 7).map((id, index) => {
                                const comp= isComprise(id)
                                return (
                                    <TDOverlay comp={comp} id={id} key={(weekIndex+1)*(index+1)}/>
                                );
                            })}
                        </tr>
                    ))}
                    </tbody>
                </table>
            )
        }
    }, [dateClicked,daysInWeek, dates]);

    const handleClickValue = useCallback((value, an) => {
        setMonthClicked(value)
        Conge.getInfoMonth(element.employe.idEmp, an, value).then((res)=>{
            setDateClicked(res)
        }).catch((er)=>{
            console.log(er.message)
        })
    },[])

    const clickedYear= useCallback(
        (an) => {
            Conge.getPerMonth(element.employe.idEmp, an).then((resp)=>{
                if (resp){
                    setMonthClicked(-3)
                    setValues(resp)
                }
            }).catch((e)=>{
                console.log(e.message)
            })
        },
        []
    );
    const [sol, setSol] = useState(element.soldeRestant);
    const reloadObj = useCallback(
        () => {
            Conge.reload(element.employe.idEmp, year).then((rep)=>{
                setSol(rep.soldeRestant)
                setValues(rep.perMonth)
            }).catch((e)=>{
                console.log(e.message)
            })
        },
        [year,element]
    );


    const [show, setShow] = useState(false);
    const [congeElement, setCongeElement] = useState({
        dateDebut: new Date(),
        dateFin: new Date(),
        cause: '',
        isMatinDebut: true,
        isMatinFin: false,
    });
    const [dateRetour, setDateRetour] = useState('');
    const changeElementConge = useCallback(
        (attr, value) => {
            setCongeElement(prev=>({...prev, [attr]: value}))
        }, []
    );
    const dure = useMemo( () => {
        let diffDays = differenceEnJours(congeElement.dateFin, congeElement.dateDebut);
        if (congeElement.isMatinDebut && congeElement.isMatinFin){
            diffDays+=0.5;
        }else if(congeElement.isMatinDebut && !congeElement.isMatinFin){
            diffDays+=1;
        }else if(!congeElement.isMatinDebut && !congeElement.isMatinFin){
            diffDays+=0.5;
        }
        const valiny=Math.max(diffDays, 0)
        return valiny;
    },[congeElement])

    useEffect(() => {
        setDateRetour( ()=>{
            if (dure===0){
                return "--/--/---- : --"
            }
            const format=formatDateToInputValue(addDays(congeElement.dateDebut, formatNumberDay(dure, congeElement.isMatinDebut,congeElement.isMatinFin))).split("-")
            return format[2]+"/"+format[1]+"/"+format[0]+`${congeElement.isMatinFin ? ' : Midi' : ' : Matin'}`
        });
    }, [dure]);
    const [loading, setLoading] = useState(false);
    const submit= useCallback(
        () => {
            if (dure>0){
                setLoading(true)
                const conge=new Conge(congeElement.dateDebut, congeElement.dateFin,element.employe.idEmp, congeElement.cause, congeElement.isMatinDebut,congeElement.isMatinFin)
                Conge.addCongeByAdmin({dateDebut: conge.dateDebut, dateFin: conge.dateFin, idEmp: conge.idEmp, cause: conge.cause, matinDebut: conge.isMatinDebut, matinFin: conge.matinFin}).then(()=>{
                    changeElementConge("dateDebut", new Date())
                    changeElementConge("dateFin", new Date())
                    changeElementConge("cause", "")
                    changeElementConge("isMatinDebut", true)
                    changeElementConge("isMatinFin", false)
                }).catch((e)=>{
                    console.log(e)
                    // setErrorMessage(e.message)
                    // setErreur(true)
                }).finally(()=>{
                    setLoading(false)
                    setShow(false)
                    reloadObj()
                })
            }
        },
        [congeElement,element,year],
    );


    return(
        <>
            <div className="rounded-3 p-2 my-2 w-100 border border-primary-subtle">
                <div className="w-100 d-inline-flex align-items-center border-bottom border-primary-subtle position-relative">
                    <div className="">
                        <img
                            src={APIURL()+`${element.employe.profile}`}
                            alt=""
                            className="border-dark-light rounded-circle mt-0 mx-2 p-0"
                            width={50} height={50}
                            style={{ objectFit: 'cover'}}
                            decoding={"async"}
                        />
                    </div>
                    <div className="d-flex w-100 justify-content-start flex-column text-print ps-2">
                        <span className="fw-bolder text-uppercase fw-5">{element.employe.nom} <span className="text-capitalize fs-5">{element.employe.prenom}</span></span>
                        <span className="fs-4 text-grey fw-bold">{element.employe.matricule}</span>
                    </div>
                    <div className="position-absolute width-max end-0 top-0 mt-2 me-2 cursor-pointer">
                        <Button label="Ajouter Congé" onClick={()=>setShow(true)} className="btn-sm small p-2 rounded-3" severity="info" />
                    </div>
                </div>
                <div className="mt-2 row w-100 mx-0 p-0 d-flex align-items-center">
                    <div className="col-7 ps-0">
                        <div className="p-2 border rounded-3 w-100">
                            <div className="centered-year-container my-2">
                                <div>
                                    <i onClick={() => setYear(prev => {
                                        clickedYear(prev-1)
                                        return prev - 1
                                    })} className="fas fa-chevron-left fs-5 cursor-pointer"/>
                                </div>
                                <div className="year">
                                    <pre className="text-dark fs-5 m-0 p-0">{year}</pre>
                                </div>
                                <div>
                                    <i onClick={() => setYear(prev => {
                                        clickedYear(prev+1)
                                        return prev + 1
                                    })} className="fa fa-chevron-right fs-5 cursor-pointer"/>
                                </div>
                            </div>
                            <div className="day-content pb-2 border-bottom">
                                <table className="days-table w-100">
                                    {Array.from({length: 2},(_,v)=>(
                                        <React.Fragment key={v}>
                                            <thead>
                                            <tr>
                                                {monthYear.slice(v*6,(v+1)*6).map((day, index) => (
                                                    <th key={index} scope="col" className={`day p-0 text-print ${((v*6)+index+1)===monthClicked ? 'text-aris fw-bolder': ''}`}>{day}</th>
                                                ))}
                                            </tr>
                                            </thead>
                                            <tbody>
                                            <tr>
                                                {values.slice(v*6,(v+1)*6).map((value,index)=>(
                                                    <td key={index} className={`date-cell fw-bold`}>
                                                        {value!==0 ? (
                                                            <div
                                                                onClick={()=>handleClickValue((v*6)+index+1, year)}
                                                                className={`date-content shadow cursor-pointer ${((v*6)+index+1)===monthClicked ? 'bg-aris text-white':''}`}>
                                                                <pre className="m-0 p-0">{value || ''}</pre>
                                                            </div>
                                                        ) : ('--')}
                                                    </td>
                                                ))}
                                            </tr>
                                            </tbody>
                                        </React.Fragment>
                                    ))}
                                </table>
                            </div>
                        </div>
                    </div>
                    <div className="col-5 border rounded-3">
                        <ul className={`list-group list-group-flush ${monthClicked===0 ? 'h-100 d-flex justify-content-center' : 'top-9 bg-white width-max mx-auto'}`}>
                            <li className="list-group-item border-0 bg-transparent text-center px-2 py-1 w-100">
                                <pre className="m-0 p-0 fs-5 fw-bolder"><span className="text-decoration-underline">Congé restant:</span> <span className="px-2 py-1 bg-info-subtle text-info rounded-3">{sol}</span></pre>
                            </li>
                        </ul>
                        {showCongerPerMonth}
                    </div>
                </div>
            </div>
            <Modal
                show={show}
                onHide={()=>setShow(false)}
                keyboard={false}
                backdrop="static"
                dialogClassName="modal-dialog-centered modal-70w position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center w-100"
                animation
                autoFocus={true}>
                <Modal.Header closeButton>
                    <Modal.Title className="text-capitalise text-print text-grey text-break">{element.employe.nom + " "+ element.employe.prenom}</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form.Group className="mb-1" controlId="edit-dateDebut">
                        <Form.Label>Date debut</Form.Label>
                        <Form.Control disabled={loading} autoFocus type="date" value={formatDateToInputValue(congeElement.dateDebut)} onChange={(e)=>{
                            const dt = new Date(e.target.value);
                            changeElementConge('dateDebut',dt)
                        }} placeholder="Date debut" />
                    </Form.Group>
                    <Form.Group className="mb-3" controlId="dateDebutEdit">
                        <Form.Check
                            inline
                            label="Matin"
                            name="group3"
                            disabled={loading}
                            type={"radio"}
                            checked={congeElement.isMatinDebut===true}
                            onChange={()=>changeElementConge('isMatinDebut',true)}
                            id="radio-3"
                        />
                        <Form.Check
                            inline
                            label="Après-midi"
                            name="group3"
                            type={"radio"}
                            disabled={loading}
                            checked={congeElement.isMatinDebut===false}
                            onChange={()=>changeElementConge('isMatinDebut',false)}
                            id="radio-4"
                        />
                    </Form.Group>

                    <Form.Group className="mb-1" controlId="editDateFin">
                        <Form.Label>Date fin</Form.Label>
                        <Form.Control type="date" disabled={loading} value={formatDateToInputValue(congeElement.dateFin)} onChange={(e)=>{
                            const dt = new Date(e.target.value);
                            changeElementConge('dateFin', dt)
                        }} placeholder="Date fin" />
                    </Form.Group>
                    <Form.Group className="mb-2" controlId="DateFinRadio-Edit">
                        <Form.Check
                            inline
                            name={"groupe4"}
                            label="Matin"
                            type={"radio"}
                            checked={congeElement.isMatinFin===true}
                            onChange={()=>changeElementConge('isMatinFin',true)}
                            disabled={loading}
                            id="radio-25"
                        />
                        <Form.Check
                            inline
                            name={"groupe4"}
                            label="Après-midi"
                            type={"radio"}
                            disabled={loading}
                            checked={congeElement.isMatinFin===false}
                            onChange={()=>changeElementConge('isMatinFin',false)}
                            id="radio-29"
                        />
                    </Form.Group>
                    <div className="row m-0 p-0 w-100">
                        <Form.Group as={Col} sm={4} className="ps-0 mb-3" controlId="NombreJour">
                            <Form.Label>Durée</Form.Label>
                            <Form.Control type="text" disabled value={`${dure}j`}  placeholder="Nombre de jours" />
                        </Form.Group>
                        <Form.Group as={Col} sm={8} className="pe-0 mb-3" controlId="dateRetour">
                            <Form.Label>Date retour</Form.Label>
                            <Form.Control type="text" disabled value={dateRetour}  placeholder="Date retour au travail" />
                        </Form.Group>
                    </div>

                    <Form.Group className="mb-3" controlId="Cause">
                        <Form.Label>Cause (Optionnel)</Form.Label>
                        <Form.Control disabled={loading} value={congeElement.cause} onChange={(e)=>changeElementConge('cause', e.target.value.trim())} as={"textarea"} rows={3} placeholder="Cause" />
                    </Form.Group>
                    <div className="row m-0 p-0 w-100 d-flex justify-content-between">
                        <Button label={"Annuler"} severity="warning" onClick={()=>setShow(false)} className="text-white w-50-2rem py-1"/>
                        <Button label={"Envoyer"} severity="primary" loading={loading} onClick={()=>submit()} className="text-white w-50-2rem py-1"/>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}
export default ViewSolde