import React, {useEffect, useMemo, useState} from "react";
import {Card, CardBody, CardTitle, Dropdown, Placeholder} from "react-bootstrap";
import {formatDateToInputValue} from "../InfoPersonel";
import ViewCotisation from "./Parameter/ViewCotisation";
import ViewSalaireBrute from "./Parameter/ViewSalaireBrute";
import ViewIndemnite from "./Parameter/ViewIndemnite";
import ViewPrime from "./Parameter/ViewPrime";
import ViewAcompte from "./Parameter/ViewAcompte";
import ViewPret from "./Parameter/ViewPret";
import {SalaireBase} from "../../Model/Paie/SalaireBase";
import ViewInterval from "./Parameter/ViewInterval";
import {addDays, addMonths} from "date-fns";

export const getNextDateMonth=(dateCurrentMonth)=>{
    const today = new Date();
    const firstDay = new Date(today.getFullYear(), today.getMonth(), dateCurrentMonth);
    const lastDay = addDays(new Date(today.getFullYear(), today.getMonth()+1, dateCurrentMonth),-1)
    if (firstDay>today){
        return{firstDay: addMonths(firstDay,-1), lastDay: addMonths(lastDay,-1)}
    }
    return{firstDay,lastDay}
}

const Paramettre = ()=>{

    const [currentInterval, setCurrentInterval] = useState(1);

    const date = useMemo(() => {
        return getNextDateMonth(currentInterval)
    }, [currentInterval]);


    const [viewSalaire, setViewSalaire] = useState(false);
    const [indemnite, setIndemnite] = useState(false);
    const [prime, setPrime] = useState(false);
    const [viewAcompte, setViewAcompte] = useState(false);
    const [pret, setPret] = useState(false);

    const [showInterval, setShowInterval] = useState(false);


    const [cotisations, setCotisations] = useState([]);
    useEffect(() => {
        SalaireBase.getAllCotisations().then((e)=>{
            setCotisations(e)
        }).catch(()=>{})
        SalaireBase.getCurrentintervalPaiement().then((res)=>{
            setCurrentInterval(res.valeur)
        }).catch(()=>{})
    }, []);


    return(
        <>
            <div className="mt-3 row w-100 m-0 p-0">
                <h4 className="small mb-3">Rénumération brute</h4>
                <div className="col-3 px-2">
                    <Card onClick={()=>setShowInterval(true)} className="bg-green h-100 cursor-pointer">
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-stopwatch me-1 text-success-emphasis"/>Periode</CardTitle>
                        <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                            <pre className="p-0 m-0">{formatDateToInputValue(date.firstDay)}</pre><i className="fas fa-arrow-right"/><pre className="p-0 m-0">{formatDateToInputValue(date.lastDay)}</pre>
                        </CardBody>
                    </Card>
                </div>
                <div className="col-3 px-2">
                    <Card className="bg-green h-100 cursor-pointer" onClick={()=>setViewSalaire(true)}>
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-sack-dollar me-1 text-success-emphasis"/>Salaire de Base</CardTitle>
                        <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                            <pre className="p-0 m-0">{formatDateToInputValue(date.firstDay)}</pre><i className="fas fa-arrow-right"/><pre className="p-0 m-0">{formatDateToInputValue(date.lastDay)}</pre>
                        </CardBody>
                    </Card>
                </div>
                <div className="col-3 px-2">
                    <Card className="bg-green h-100 cursor-pointer" onClick={()=>setIndemnite(true)}>
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-train-subway me-1 text-success-emphasis"/>Indemnité</CardTitle>
                        <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                            <pre className="p-0 m-0">{formatDateToInputValue(date.firstDay)}</pre><i className="fas fa-arrow-right"/><pre className="p-0 m-0">{formatDateToInputValue(date.lastDay)}</pre>
                        </CardBody>
                    </Card>
                </div>
                <div className="col-3 px-2">
                    <Card onClick={()=>setPrime(true)} className="bg-green h-100 cursor-pointer">
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-award me-1 text-success-emphasis"/>Prime de fonction</CardTitle>
                        <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                            <pre className="p-0 m-0">{formatDateToInputValue(date.firstDay)}</pre><i className="fas fa-arrow-right"/><pre className="p-0 m-0">{formatDateToInputValue(date.lastDay)}</pre>
                        </CardBody>
                    </Card>
                </div>

                <h4 className="small my-3">Cotisations</h4>
                {cotisations.length===0 &&(
                    <>
                        <div className="col-6 px-2">
                            <Card className="bg-blue-darker h-100">
                                <Placeholder as={Card.Title} className="mb-3" animation="glow">
                                    <Placeholder xs={12} />
                                </Placeholder>
                                <Placeholder as={"div"} className="mt-0 row mx-0 px-0 mb-2" animation="glow">
                                    <Placeholder xs={6}/>
                                    <Placeholder xs={6} />
                                </Placeholder>
                            </Card>
                        </div>
                        <div className="col-6 px-2">
                            <Card className="bg-blue-darker h-100">
                                <Placeholder as={Card.Title} className="mb-3" animation="glow">
                                    <Placeholder xs={12} />
                                </Placeholder>
                                <Placeholder as={"div"} className="mt-0 row mx-0 px-0 mb-2" animation="glow">
                                    <Placeholder xs={6}/>
                                    <Placeholder xs={6} />
                                </Placeholder>
                            </Card>
                        </div>
                    </>
                )}
                {cotisations.map((e)=>(
                    <div key={e.idCotisation} className="col-6 px-2">
                        <ViewCotisation object={e} />
                    </div>
                ))}

                <h4 className="small my-3">Retenu</h4>
                <div className="col-8 px-2 m-0">
                    <Card className="bg-aris h-100">
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-chart-simple text-danger-emphasis me-1"/> IRSA</CardTitle>
                        <CardBody className="mt-1 mb-0 p-0">
                            <div className="d-grid gap-2 grid-col-2 w-100 m-0 p-2 text-white">
                                <pre className="p-0 mb-2">jusqu’à Ar 350.000 : <strong className="fs-5">0<i className="fa fa-percent ms-1"/></strong></pre>
                                <pre className="p-0 mb-2">minimum de perception : <strong className="fs-5">3.000 Ar</strong> </pre>
                                <pre className="p-0 mb-2">Trans: 350.001 <i className="fa fa-arrow-right"/> 400.000 <i className="fa fa-right-long"/> <strong className="fs-5">5<i className="fa fa-percent ms-1"/></strong></pre>
                                <pre className="p-0 mb-2">Trans: 400.001 <i className="fa fa-arrow-right"/> 500.000 <i className="fa fa-right-long"/> <strong className="fs-5">10<i className="fa fa-percent ms-1"/></strong></pre>
                                <pre className="p-0 mb-2">Trans: 500.001 <i className="fa fa-arrow-right"/> 600.000 <i className="fa fa-right-long"/> <strong className="fs-5">15<i className="fa fa-percent ms-1"/></strong></pre>
                                <pre className="p-0 mb-2"><i className="fa fa-greater-than-equal"/> 600.001 <i className="fa fa-right-long"/> <strong className="fs-5">20<i className="fa fa-percent ms-1"/></strong></pre>
                            </div>
                        </CardBody>
                    </Card>
                </div>
                <div className="col-4">
                    <Card onClick={()=>setViewAcompte(true)} className="bg-aris mb-2 cursor-pointer" style={{height: 'calc(50% - 0.25rem)'}}>
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-calendar-check text-danger-emphasis me-1"/>Acompte</CardTitle>
                        <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                            <pre className="p-0 m-0">{formatDateToInputValue(date.firstDay)}</pre><i className="fas fa-arrow-right"/><pre className="p-0 m-0">{formatDateToInputValue(date.lastDay)}</pre>
                        </CardBody>
                    </Card>
                    <Card onClick={()=>setPret(true)} className="bg-aris cursor-pointer" style={{height: 'calc(50% - 0.25rem)'}}>
                        <CardTitle className="text-center text-white pt-1 mb-0"><i className="fa fa-filter-circle-dollar me-1 text-danger-emphasis"/>Remboursement Prêt</CardTitle>
                        <CardBody className="mt-0 text-center d-inline-flex justify-content-between">
                            <pre className="p-0 m-0">-- --</pre><pre className="p-0 m-0">---</pre>
                        </CardBody>
                    </Card>
                </div>
            </div>

            {viewSalaire && (
                <ViewSalaireBrute show={viewSalaire} hide={()=>setViewSalaire(false)}/>
            )}

            {indemnite && (
                <ViewIndemnite show={indemnite} hide={()=>setIndemnite(false)}/>
            )}

            {prime && (
                <ViewPrime show={prime} hide={()=>setPrime(false)}/>
            )}

            {viewAcompte && (
                <ViewAcompte currentInterval={currentInterval} show={viewAcompte} hide={()=>setViewAcompte(false)}/>
            )}

            {pret && (
                <ViewPret currentInterval={currentInterval} show={pret} hide={()=>setPret(false)}/>
            )}
            {showInterval && (
                <ViewInterval currentValue={currentInterval} show={showInterval} hide={()=>setShowInterval(false)} setCurrentValue={setCurrentInterval}/>
            )}
        </>
    )
}
export default Paramettre