import React, {useCallback, useEffect, useState} from "react";
import {Col, Form, InputGroup, Modal, Row} from "react-bootstrap";
import Pagination from "../../Main/Utilitaire/Pagination";
import {userProfile} from "./PersIndView";
import {SalaireBase} from "../../../Model/Paie/SalaireBase";
import {normalizeString} from "../../Rendu/Hebdo";
import {formatNumber} from "./ViewSalaireBrute";

const ViewPrime = ({show,hide})=>{
    const [matricule, setMatricule] = useState('');
    const [nom, setNom] = useState('');
    const [post, setPost] = useState('');
    const [filtered, setFiltered] = useState([]);
    const [allData, setAllData] = useState([]);
    useEffect(() => {
        SalaireBase.getAllPrimeMonth().then((resp)=>{
            setAllData(resp)
        }).catch(()=>{})
    }, []);

    const [paginate, setPaginate] = useState(1);

    const [showModif, setShowModif] = useState(false);
    const [mask, setMask] = useState(false);
    useEffect(() => {
        if (!show){
            setMask(false)
            return
        }
        if (showModif){
            setMask(false)
        }else{
            setMask(true)
        }
    }, [show,showModif]);

    useEffect(() => {
        let data = allData;
        if (matricule) {
            data = allData.filter((emp) =>{
                if (emp.matricule){
                    return emp.matricule.includes(matricule)
                }else{
                    return true
                }
            });
        }
        if (nom) {
            data = data.filter((emp) =>
                emp.nom.toLowerCase().includes(nom.toLowerCase()) ||
                emp.prenom.toLowerCase().includes(nom.toLowerCase())
            );
        }
        if (post){
            data = data.filter((emp)=>normalizeString(emp.poste.toLowerCase()).includes(normalizeString(post.toLowerCase())))
        }
        setFiltered(data)
    }, [allData, matricule, nom, post]);


    const [valeurs, setValeurs] = useState({
        total: 0,
        valeur: 0,
        description: '',
        id: -100,
        nom: ''
    });
    const [checked, setChecked] = useState(false);
    const [error, setError] = useState(false);
    const clickedTr = useCallback((emp) => {
        setShowModif(true)
        setValeurs(()=>({
            total: emp.somme,
            valeur: 0,
            description: '',
            id: emp.idEmp,
            nom: emp.nom + " "+ emp.prenom
        }))
        setChecked(false)
    }, []);
    useEffect(()=>{
        if (checked){
            setError(false)
        }
    },[checked])
    const submit = useCallback(() => {
        if (!checked){
            setError(true)
            return
        }
        SalaireBase.addPrime(valeurs.id,valeurs.valeur,valeurs.description).catch(()=>{})
            .then(()=>{
                setAllData((prev)=>prev.map(e=>e.idEmp===valeurs.id ? {...e, somme: valeurs.valeur + e.somme} : e))
            })
            .finally(()=>{
                setShowModif(false)
            })
    }, [valeurs,checked]);

    return(
        <>
            <Modal
                show={mask}
                onHide={hide}
                keyboard={false}
                backdrop="static"
                autoFocus={true}
                dialogClassName="modal-dialog-centered modal-W position-relative d-flex justify-content-center align-items-center"
                contentClassName="d-flex justify-content-center modal-90w"
            >
                <Modal.Header className="position-relative py-2">
                    <strong>Ajouter Prime</strong>
                    <div onClick={()=>hide()} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                        <i className="fa-solid fa-close  text-dark-emphasis"/>
                    </div>
                </Modal.Header>
                <Modal.Body className="bg-dark bg-opacity-75">
                    <div className="card w-100 mb-2">
                        <div className="card-body pt-1 pb-1">
                            <h3 className="text-center">Liste des Salariés</h3>
                            <div className="row m-0 p-0">
                                <div className="col-3">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">M°</InputGroup.Text>
                                        <Form.Control
                                            placeholder="matricule"
                                            aria-label="matricule"
                                            aria-describedby="basic-addon1"
                                            type="search"
                                            value={matricule}
                                            onChange={(event)=>{
                                                setMatricule(event.target.value.replace(/\D/g, ''))
                                            }}
                                        />
                                    </InputGroup>
                                </div>
                                <div className="col-5">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">Nom</InputGroup.Text>
                                        <Form.Control
                                            placeholder="nom ou prénom"
                                            aria-label="nom"
                                            aria-describedby="nom"
                                            type="search"
                                            value={nom}
                                            onChange={(event) => setNom(event.target.value)}
                                        />
                                    </InputGroup>
                                </div>
                                <div className="col-4">
                                    <InputGroup className="my-3">
                                        <InputGroup.Text id="basic-addon1">Poste</InputGroup.Text>
                                        <Form.Control
                                            placeholder="nom ou prénom"
                                            aria-label="nom"
                                            aria-describedby="nom"
                                            type="search"
                                            value={post}
                                            onChange={(event) => setPost(event.target.value)}
                                        />
                                    </InputGroup>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="m-0 w-100 rounded-3 bg-white">
                        <div className="rounded-3 p-1 m-0 w-100">
                            <table className="table mb-0 table-striped table-hover">
                                <thead>
                                <tr className="text-center">
                                    <th scope="col"/>
                                    <th scope="col">M°</th>
                                    <th scope="col">Nom</th>
                                    <th scope="col">Prenom</th>
                                    <th scope="col">Poste</th>
                                    <th scope="col">Total Prime</th>
                                </tr>
                                </thead>
                                <tbody>
                                {filtered.slice((paginate-1)*10,(paginate)*10).map((element,index)=>(
                                    <tr onClick={()=>clickedTr(element)} key={index} className="cursor-pointer" >
                                        <td>
                                            {userProfile(element)}
                                        </td>
                                        <th scope="row">{String(element.matricule).padStart(4, '0')}</th>
                                        <td>{element.nom}</td>
                                        <td>{element.prenom}</td>
                                        <td>{element.poste}</td>
                                        <td className="fw-bold h4-Edit">{formatNumber(element.somme)}</td>
                                    </tr>
                                ))}
                                </tbody>

                            </table>
                        </div>
                        <div className="d-flex justify-content-end w-100 m-0 p-2">
                            <Pagination length={filtered.length % 10 === 0 ? filtered.length / 10 : Math.floor(filtered.length / 10) + 1} active={paginate} setActive={setPaginate}/>
                        </div>
                    </div>
                </Modal.Body>
            </Modal>
            {showModif && (
                <>
                    <Modal
                        show={showModif}
                        onHide={()=>setShowModif(false)}
                        keyboard={false}
                        backdrop="static"
                        autoFocus={true}
                        dialogClassName="modal-dialog-centered  position-relative d-flex justify-content-center align-items-center"
                        contentClassName="d-flex justify-content-center modal-70w bg-green"
                    >
                        <Modal.Header className="position-relative">
                            <strong className="text-capitalize">{valeurs.nom}</strong>
                            <div onClick={()=>setShowModif(false)} style={{transform: 'translate(0.9rem,-0.9rem)', width: '40px', height: '40px'}} className="position-absolute top-0 end-0 bg-secondary-subtle rounded-circle d-flex align-items-center justify-content-center cursor-pointer">
                                <i className="fa-solid fa-close  text-dark-emphasis"/>
                            </div>
                        </Modal.Header>
                        <Modal.Body className="pt-1">
                            <div className="row mt-0 mx-0 mb-3 p-0 w-100">
                                <Form.Group className="p-0 mt-0 mx-0 mb-2" as={Col} md="12" controlId="valeur Actuel">
                                    <Form.Label className="fw-bold">Total Valeur Actuel</Form.Label>
                                    <div className="position-relative">
                                        <Form.Control
                                            type="text"
                                            className="bg-transparent border-dark-light"
                                            value={formatNumber(valeurs.total)}
                                            placeholder="Valeur"
                                            disabled={true}
                                            required
                                        />
                                        <pre className="position-absolute fw-bold top-50 mb-0 mt-0 end-0 translate-middle-y me-3 bg-warning ">
                                            MGA
                                        </pre>
                                    </div>
                                </Form.Group>
                                <Form.Group className="p-0 mt-0 mx-0 mb-2" as={Col} md="12" controlId="Nouveau">
                                    <Form.Label className="fw-bold">Ajouter Autre valeur</Form.Label>
                                    <div className="position-relative">
                                        <Form.Control
                                            type="text"
                                            className="bg-transparent border-dark-light"
                                            autoFocus={true}
                                            value={formatNumber(valeurs.valeur)}
                                            onChange={(e) => {
                                                const val = e.target.value.replace(/\D/g,'')
                                                setValeurs((prev) => ({...prev, valeur: parseInt(val)}))
                                            }}
                                            placeholder="Valeur"
                                            required
                                        />
                                        <pre className="position-absolute fw-bold top-50 mb-0 mt-0 end-0 translate-middle-y me-3 bg-warning ">
                                            MGA
                                        </pre>
                                    </div>
                                </Form.Group>

                                <Form.Group className="p-0 mt-0 mx-0 mb-2" as={Col} md="12" controlId="description">
                                    <Form.Label className="fw-bold">description</Form.Label>
                                    <Form.Control
                                        type="text"
                                        className="bg-transparent border-dark-light"
                                        value={valeurs.description}
                                        onChange={(e) => setValeurs((prev)=>({...prev, description: e.target.value}))}
                                        placeholder="description"
                                        required
                                    />
                                </Form.Group>

                                <Form.Check
                                    type="checkbox"
                                    className="bg-transparent"
                                    label="Je valide mon choix"
                                    id={`validation-${valeurs.id}`}
                                    value={checked}
                                    onChange={()=>setChecked(prev=>!prev)}
                                    isInvalid={error}
                                />

                            </div>
                            <Row>
                                <Col md={6}>
                                    <button type="button" onClick={()=>setShowModif(false)} className="btn btn-sm bg-aris text-white w-100">Annuler</button>
                                </Col>
                                <Col md={6}>
                                    <button type="button" onClick={submit} className="btn btn-sm bg-blue text-white w-100">Valider</button>
                                </Col>
                            </Row>
                        </Modal.Body>
                    </Modal>
                </>
            )}
        </>
    )
}
export default ViewPrime