import './dialog.css'
import {useMemo} from "react";
import React from "react";

export const MessageDate = ({date})=>{

    return (
        <>
            <div className="w-100 mt-1 mb-2 d-inline-flex text-nowrap justify-content-center sticky-top z-3">
                <span className="py-1 px-2 bg-secondary text-white rounded-pill text-print bg-opacity-50 shadow-lg">📅 {(new Date(date)).toLocaleDateString("fr-FR", {day: 'numeric', month: 'short', year: 'numeric'})}</span>
            </div>
        </>
    )
}

export const DateLimiter = ({date})=>{
    const formatDate = (dateStr) => {
        const now = new Date();
        const givenDate = new Date(dateStr);
        const diffTime = Math.abs(now - givenDate);
        const diffDays = diffTime / (1000 * 60 * 60 * 24);
        const diffMonths = diffDays / 30;

        const optionsDayName = { weekday: 'long' };
        const optionsFull = { weekday: 'long', day: 'numeric', month: 'short' };
        const optionsDateYear = { day: 'numeric', month: 'short', year: 'numeric' };

        if (diffMonths > 6) {
            return givenDate.toLocaleDateString("fr-FR", optionsDateYear);
        } else if (diffDays < 7) {
            return givenDate.toLocaleDateString("fr-FR", optionsDayName);
        } else {
            return givenDate.toLocaleDateString("fr-FR", optionsFull);
        }
    };
    return (
        <>
            <div className="w-100 my-2 mb-2 d-inline-flex text-nowrap justify-content-center z-2 align-items-center">
                <div className="flex-grow-1 border-top"/>
                <span className="py-1 px-2  text-white text-print">
                    {formatDate(date)}
                </span>
                <div className="flex-grow-1 border-top"/>
            </div>
        </>
    )
}

export const MessageSecondary = ({isMine, content, status, date})=>{
    const formattedTime = formatTime(date);
    const htmlContent = formatTextWithLinks(content);
    return (
        <>
            <div className="w-100 mb-1">
                {!isMine ? (
                    <>
                        <div className="bubble-container mt-1">
                            <div className="bubble-secondary d-flex flex-column bg-white ms-2">
                                <span className="message-text flex-grow-1" dangerouslySetInnerHTML={{ __html: htmlContent }} />
                                <span className="time-secondary w-100 text-end">
                                    {formattedTime}
                                </span>
                            </div>
                        </div>
                    </>
                ): (
                    <>
                        <div className="bubble-container justify-content-end mt-1">
                            <div className="d-flex flex-column bg-me-secondary float-end me-1">
                                <span className="message-text" dangerouslySetInnerHTML={{ __html: htmlContent }} />
                                <span className="time-secondary w-100 text-end">
                                    {formattedTime}{iconStatut(status)}
                                </span>
                            </div>
                        </div>
                    </>
                )}
            </div>
        </>
    )
}

const formatTextWithLinks = (text) => {
    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const emailRegex = /([\w.-]+@[\w.-]+\.\w+)/g;

    let result = text.replace(urlRegex, (url) => {
        return `<a href="${url}" class="link-primary-in text-print" target="_blank" rel="noopener noreferrer">${url}</a>`;
    });

    result = result.replace(emailRegex, (email) => {
        return `<a href="mailto:${email}" class="link-primary-in text-print">${email}</a>`;
    });

    return result.replace(/\n/g, "<br />");
};

const formatTime = (dateString) => {
    const date = new Date(dateString);
    let hours = date.getHours();
    const minutes = date.getMinutes().toString().padStart(2, '0');
    const isMorning = hours < 12;

    // Convert to 12h format
    hours = hours % 12 || 12;

    return `${hours}:${minutes} ${isMorning ? 'matin' : 'après-midi'}`;
};

export const iconStatut =(status, color='text-grey') => {
    if (status === "loading") {
        return <i className={`ms-1 fa fa-spin-pulse fa-spinner small ${color}`} />
    } else if (status === "nonVue") {
        return <i className={`ms-1 fa fa-check small ${color}`} />
    } else if (status === "ignorer") {
        return <i className={`ms-1 fa fa-circle-check small ${color}`} />
    } else {
        return <i className={`ms-1 fa fa-check-double small ${color}`} />
    }
}
const MessageText = ({ isMine, content, date, status }) => {

    const formattedTime = formatTime(date);

    const htmlContent = formatTextWithLinks(content);

    return (
        <div className="w-100 mb-1">
            {!isMine ? (
                <div className="bubble-container mt-2">
                    <div className="bubble d-flex flex-column bg-white ms-2">
                        <span className="message-text flex-grow-1" dangerouslySetInnerHTML={{ __html: htmlContent }} />
                        <span className="time w-100 text-end">{formattedTime}</span>
                    </div>
                </div>
            ) : (
                <div className="bubble-container justify-content-end mt-2">
                    <div className="d-flex flex-column bg-me float-end me-1">
                        <span className="message-text" dangerouslySetInnerHTML={{ __html: htmlContent }} />
                        <span className="time w-100 text-end">
                            {formattedTime}{iconStatut(status)}
                        </span>
                    </div>
                </div>
            )}
        </div>
    );
};

export default MessageText